def _cli_message_for_tool(tool_name: str, count: int) -> Optional[str]:
    if tool_name in CLI_SILENT_TOOLS:
        return None
    static_messages = {
        "initialize_run_state": "I'm setting up the run and preparing a clean workspace.",
        "tool_parse_goal_request": "I'm reading your request and deciding whether this needs design work, analysis, or a direct answer.",
        "tool_validate_goal_schema": "I'm validating the design objective and normalizing the constraints.",
        "tool_resolve_isoforms_and_sites": "I'm resolving the transcripts, isoforms, and splice sites that matter for this request.",
        "tool_reference_preflight": "I'm checking that the required reference assets are available before the heavy lifting starts.",
        "tool_download_reference_assets": "I'm downloading the missing reference assets and building any required genome indexes.",
        "tool_materialize_region_constraints": "I'm building the targeting constraints from any motifs, binding sites, or explicit regions you asked for.",
        "tool_derive_exploratory_steric_regions": "I'm mapping the steric targeting windows that are worth exploring.",
        "tool_build_steric_regions": "I'm assembling the steric target regions for candidate generation.",
        "tool_build_gapmer_regions": "I'm assembling the gapmer target regions for knockdown design.",
        "tool_emit_tiling_config": "I'm preparing the tiling configuration for the design engine.",
        "tool_run_steric_tiling": "I'm tiling steric ASO candidates across the selected regions.",
        "tool_collect_steric_results": "I'm collecting and organizing the initial steric tiling results.",
        "tool_filter_steric_tiles": "I'm filtering out weak steric candidates before deeper scoring.",
        "tool_annotate_offtarget_expression": "I'm checking whether likely off-target genes are actually expressed in relevant tissue contexts.",
        "tool_score_steric_uniqueness": "I'm scoring steric candidates for specificity and uniqueness.",
        "tool_run_splice_eval": "I'm estimating splice effects for the steric candidates.",
        "tool_build_routing_plan": "I'm turning the splice predictions into route-specific candidate sets.",
        "tool_summarize_routes": "I'm summarizing the routed candidate sets into clean deliverables.",
        "tool_run_gapmer_tiling": "I'm tiling candidate gapmers for the knockdown branch.",
        "tool_score_gapmer_uniqueness": "I'm scoring gapmer candidates for specificity and uniqueness.",
        "tool_apply_gapmer_constraints": "I'm applying the final gapmer constraints and cleanup rules.",
        "tool_build_report_payload": "I'm assembling the final story of the run from the artifacts I generated.",
        "tool_write_markdown_report": "I'm writing the markdown report so the run is easy to review.",
        "tool_write_aux_exports": "I'm generating the HTML summary and export files.",
        "tool_execute_design_task": "I'm launching the next scoped design task as its own child run.",
        "tool_answer_question": "I'm answering your ASO question directly without launching a design run.",
        "tool_analyze_artifact": "I'm reading the referenced run artifacts and extracting the conclusion from them.",
        "tool_evaluate_existing_aso_set": "I'm normalizing the provided ASO sequences so I can evaluate or compare them cleanly.",
        "tool_compare_aso_sets": "I'm comparing the provided ASOs against the referenced candidate set.",
        "tool_trace_filter_decisions": "I'm tracing where the provided ASOs survive or drop out across the pipeline stages.",
        "tool_run_sandbox_analysis": "I'm running the custom derived analysis in the sandboxed analysis step.",
        "tool_build_composite_report": "I'm combining the completed analyses into one clean answer.",
        "tool_persist_run_outputs": "I'm saving everything into a reproducible run folder.",
        "finalize_run_state": "I'm doing a final integrity check before I call the run complete.",
        "request_clarification": "I need one clarification before I continue.",
    }
    if tool_name == "tool_execute_route_goal":
        return (
            "I'm executing the next routing objective and refining the candidate set."
            if count <= 1
            else f"I'm executing routing objective {count} and tightening the candidate set."
        )
    return static_messages.get(tool_name)


def _captured_log_highlights(captured_text: str, max_lines: int = 3) -> List[str]:
    highlights: List[str] = []
    seen: Set[str] = set()
    for raw_line in captured_text.splitlines():
        line = str(raw_line or "").strip()
        if not line:
            continue
        lower = line.lower()
        if "[warn]" not in lower and "[error]" not in lower and "failed" not in lower:
            continue
        if line in seen:
            continue
        seen.add(line)
        highlights.append(line)
    if len(highlights) <= max_lines:
        return highlights
    return highlights[-max_lines:]


class _CliNarrator:
    def __init__(
        self,
        *,
        stream: Any,
        enable_stream: bool = True,
        enable_spinner: bool = True,
    ) -> None:
        self.stream = stream
        self.enable_stream = bool(enable_stream)
        self.enable_spinner = bool(enable_spinner and getattr(stream, "isatty", lambda: False)())
        self._spinner_stop: Optional[threading.Event] = None
        self._spinner_thread: Optional[threading.Thread] = None
        self._spinner_width = 0
        self._tool_counts: Dict[str, int] = {}
        self._last_message: str = ""
        self._spinner_interval = 0.5

    def _write(self, text: str) -> None:
        try:
            self.stream.write(text)
            self.stream.flush()
        except Exception:
            pass

    def _stream_line(self, text: str) -> None:
        line = str(text or "").strip()
        if not line:
            return
        self.stop_spinner(clear=True)
        if not self.enable_stream:
            self._write(line + "\n")
            return
        chunks = re.findall(r"\S+\s*", line)
        if not chunks:
            self._write(line + "\n")
            return
        delay = min(0.03, 0.55 / max(len(chunks), 1))
        for idx, chunk in enumerate(chunks):
            self._write(chunk)
            if idx < len(chunks) - 1:
                time.sleep(delay)
        self._write("\n")

    def _start_spinner(self, message: str) -> None:
        if not self.enable_spinner:
            return
        self.stop_spinner(clear=True)
        spinner_message = str(message or "").strip()
        if len(spinner_message) > 88:
            spinner_message = spinner_message[:85].rstrip() + "..."
        stop_event = threading.Event()
        self._spinner_stop = stop_event

        def _spin() -> None:
            frames = ("|", "/", "-", "\\")
            idx = 0
            while not stop_event.wait(self._spinner_interval):
                frame = frames[idx % len(frames)]
                line = f"\r  {frame} {spinner_message}"
                self._spinner_width = max(self._spinner_width, len(line))
                self._write(line.ljust(self._spinner_width))
                idx += 1

        self._spinner_thread = threading.Thread(target=_spin, daemon=True)
        self._spinner_thread.start()

    def stop_spinner(self, *, clear: bool = True) -> None:
        stop_event = self._spinner_stop
        thread = self._spinner_thread
        if stop_event is None:
            return
        stop_event.set()
        if thread is not None and thread.is_alive():
            thread.join(timeout=0.2)
        if clear and self._spinner_width:
            self._write("\r" + (" " * self._spinner_width) + "\r")
        elif self._spinner_width:
            self._write("\n")
        self._spinner_stop = None
        self._spinner_thread = None

    def intro(self, *, resuming: bool = False) -> None:
        self._write("\nMODAL-ASO\n")
        if resuming:
            self._stream_line("I'm picking the run back up and figuring out exactly where we left off.")
        else:
            self._stream_line("I'm taking your request and working through it step by step.")

    def on_runner_event(self, event: Dict[str, Any]) -> None:
        if not isinstance(event, dict):
            return
        event_type = str(event.get("type") or "").strip().lower()
        if event_type == "tool_call":
            tool_name = str(event.get("tool") or "").strip()
            if not tool_name:
                return
            count = self._tool_counts.get(tool_name, 0) + 1
            self._tool_counts[tool_name] = count
            message = _cli_message_for_tool(tool_name, count)
            if not message:
                return
            if tool_name != "tool_execute_route_goal" and message == self._last_message:
                self._start_spinner(message)
                return
            self._last_message = message
            self._stream_line(message)
            self._start_spinner(message)
            return
        if event_type == "tool_result":
            self.stop_spinner(clear=True)

    def show_clarification(
        self,
        *,
        questions: List[str],
        reason: str = "",
        context: str = "",
        why_this_matters: str = "",
        recommendation: str = "",
        active_question_index: Optional[int] = None,
        show_intro: bool = True,
    ) -> None:
        self.stop_spinner(clear=True)
        if show_intro:
            self._stream_line("I need a bit more information before I can continue cleanly.")
            if reason:
                self._write(f"Reason: {reason}\n")
            if context:
                self._write(f"Context: {context}\n")
            if why_this_matters:
                self._write(f"Why this matters: {why_this_matters}\n")
            if recommendation:
                self._write(f"Recommended path: {recommendation}\n")
        if active_question_index is None:
            question_items = list(enumerate(questions, start=1))
        elif 1 <= active_question_index <= len(questions):
            question_items = [(active_question_index, questions[active_question_index - 1])]
        else:
            question_items = []
        for idx, question in question_items:
            self._write(f"\nQuestion {idx}/{len(questions)}\n{question}\n")

    def show_completion(self, agentic_result: Dict[str, Any]) -> None:
        self.stop_spinner(clear=True)
        self._stream_line("The run is complete. I saved the outputs and wrapped everything into a clean run folder.")
        run_dir = str(agentic_result.get("run_dir") or "").strip()
        if run_dir:
            self._write(f"Run folder: {run_dir}\n")
        artifacts = agentic_result.get("artifacts") if isinstance(agentic_result.get("artifacts"), dict) else {}
        report_md = str(artifacts.get("report_md") or "").strip()
        report_html = str(artifacts.get("report_html") or "").strip()
        if report_md:
            self._write(f"Report: {report_md}\n")
        if report_html:
            self._write(f"HTML summary: {report_html}\n")

    def show_failure(self, agentic_result: Dict[str, Any], captured_text: str = "") -> None:
        self.stop_spinner(clear=True)
        self._stream_line("The run stopped before completion.")
        error = agentic_result.get("error")
        error_text = ""
        if isinstance(error, dict):
            error_text = str(error.get("message") or error.get("kind") or error).strip()
        else:
            error_text = str(error or "").strip()
        if error_text:
            self._write(f"Reason: {error_text}\n")
        highlights = _captured_log_highlights(captured_text)
        if highlights:
            self._write("Recent low-level warnings:\n")
            for line in highlights:
                self._write(f"- {line}\n")
        run_dir = str(agentic_result.get("run_dir") or "").strip()
        if run_dir:
            self._write(f"Run folder: {run_dir}\n")
        state_path = str(agentic_result.get("state_path") or "").strip()
        if state_path:
            self._write(f"State file: {state_path}\n")
        decision_log_path = str(agentic_result.get("decision_log_path") or "").strip()
        if decision_log_path:
            self._write(f"Decision log: {decision_log_path}\n")

    def show_out_of_scope(self, agentic_result: Dict[str, Any]) -> None:
        self.stop_spinner(clear=True)
        self._stream_line("This is outside ASO design, evaluation, or analysis, so I closed intake instead of asking again.")
        reason = str(agentic_result.get("reason") or "").strip()
        if reason:
            self._write(f"Reason: {reason}\n")



def _normalize_motif_target_level(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip().lower()
    if not text:
        return None
    if text in {"pre_mrna", "pre-mrna", "premrna", "genomic", "splice_region", "splice-region"}:
        return "pre_mrna"
    if text in {"mature_mrna", "mature-mrna", "mature mrna", "mrna", "cdna", "spliced_transcript", "spliced-transcript"}:
        return "mature_mrna"
    return None


def _normalize_aso_overlap_requirement(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    if not text:
        return None
    if text in {
        "any_overlap",
        "any_overlap_counts",
        "partial_overlap",
        "partial_overlap_counts",
        "partial",
        "overlap",
        "overlap_counts",
        "any",
    }:
        return "any_overlap"
    if text in {"full_containment", "full", "contained", "containment", "within", "fully_within", "full_within"}:
        return "full_containment"
    if text in {"contains_feature", "covers_feature", "feature_containment"}:
        return "contains_feature"
    return None


def _infer_aso_overlap_requirement_from_request_text(text: Any) -> Optional[str]:
    request_text = str(text or "")
    if not request_text.strip():
        return None
    normalized = re.sub(r"[^a-z0-9]+", " ", request_text.lower()).strip()
    full_containment_denied = bool(
        re.search(r"\bdo\s+not\s+require\s+full\s+containment\b", normalized)
        or re.search(r"\bnot\s+require\s+(?:the\s+)?full\s+(?:aso|oligo|candidate)", normalized)
    )
    if (
        re.search(r"\bany\s+overlap\s+counts\b", normalized)
        or re.search(r"\b(?:accept|allow|permit|use)\s+any\s+overlap\b", normalized)
        or re.search(r"\bwith\s+any\s+overlap\b", normalized)
        or re.search(r"\bany\s+overlap\s+with\s+(?:each|any|the)\s+(?:site|sites|interval|intervals|region|regions)\b", normalized)
        or re.search(r"\bpartial\s+overlap\s+counts\b", normalized)
        or re.search(r"\bpartial\s+overlap\b", normalized)
        or re.search(r"\beven\s+1\s+(?:nt|bp|base|nucleotide)\s+overlap\s+is\s+sufficient\b", normalized)
        or re.search(r"\b1\s+(?:nt|bp|base|nucleotide)\s+overlap\s+is\s+sufficient\b", normalized)
    ):
        return "any_overlap"
    if not full_containment_denied and (
        re.search(r"\bfull\s+containment\b", normalized)
        or re.search(r"\bfully\s+(?:contained|within)\b", normalized)
        or re.search(r"\bmust\s+(?:lie|fall|be)\s+(?:entirely|fully)\s+within\b", normalized)
    ):
        return "full_containment"
    return None


def _infer_minimum_overlap_bp_from_request_text(text: Any) -> Optional[int]:
    request_text = str(text or "")
    if not request_text.strip():
        return None
    normalized = re.sub(r"[^a-z0-9_]+", " ", request_text.lower()).strip()
    if re.search(r"\bminimum_overlap_bp\b.{0,40}\b1\b", request_text, flags=re.IGNORECASE | re.DOTALL):
        return 1
    if re.search(r"\bmin(?:imum)?\s+overlap(?:\s+bp)?\b.{0,40}\b1\b", normalized):
        return 1
    if re.search(r"\beven\s+1\s+(?:nt|bp|base|nucleotide)\s+overlap\s+is\s+sufficient\b", normalized):
        return 1
    if re.search(r"\b1\s+(?:nt|bp|base|nucleotide)\s+overlap\s+is\s+sufficient\b", normalized):
        return 1
    return None


def _apply_region_overlap_hints_from_request_text(
    structured_goal: Optional[Dict[str, Any]],
    request_text: Any,
) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    overlap_requirement = _infer_aso_overlap_requirement_from_request_text(request_text)
    min_overlap_bp = _infer_minimum_overlap_bp_from_request_text(request_text)
    if not overlap_requirement and min_overlap_bp is None:
        return False
    changed = False

    def _apply_to_container(container: Dict[str, Any]) -> None:
        nonlocal changed
        if overlap_requirement and not _normalize_aso_overlap_requirement(container.get("aso_overlap_requirement")):
            container["aso_overlap_requirement"] = overlap_requirement
            changed = True
        if min_overlap_bp is not None and _coerce_positive_int(container.get("minimum_overlap_bp")) is None:
            container["minimum_overlap_bp"] = min_overlap_bp
            changed = True
        for nested_key in ("rbp_binding", "mirna_binding", "motif_tiling"):
            nested = container.get(nested_key)
            if not isinstance(nested, dict):
                continue
            if overlap_requirement and not _normalize_aso_overlap_requirement(nested.get("aso_overlap_requirement")):
                nested["aso_overlap_requirement"] = overlap_requirement
                changed = True
            if min_overlap_bp is not None and _coerce_positive_int(nested.get("minimum_overlap_bp")) is None:
                nested["minimum_overlap_bp"] = min_overlap_bp
                changed = True

    constraints = structured_goal.get("region_constraints")
    if isinstance(constraints, list) and constraints:
        _apply_to_container(structured_goal)
        for entry in constraints:
            if isinstance(entry, dict):
                _apply_to_container(entry)
    for program in _iter_design_programs(structured_goal):
        program_constraints = program.get("region_constraints")
        if isinstance(program_constraints, list) and program_constraints:
            _apply_to_container(program)
            for entry in program_constraints:
                if isinstance(entry, dict):
                    _apply_to_container(entry)
    return changed


async def _prompt_user_for_answers(questions: List[str]) -> List[str]:
    answers: List[str] = []
    for idx, q in enumerate(questions, 1):
        prompt = f"\nClarification question {idx}/{len(questions)}:\n{q}\nYour answer: "
        try:
            ans = await asyncio.to_thread(input, prompt)
        except Exception:
            ans = ""
        answers.append((ans or "").strip())
    return answers


def _normalize_prompt_items(raw_items: Any) -> List[str]:
    if isinstance(raw_items, str):
        text = raw_items.strip()
        if text.startswith("[") or text.startswith("{"):
            try:
                parsed = json.loads(text)
                raw_items = parsed
            except Exception:
                pass
    if isinstance(raw_items, dict):
        for key in ("items", "questions", "suggested_answers", "values"):
            candidate = raw_items.get(key)
            if isinstance(candidate, (list, str)):
                raw_items = candidate
                break
    if isinstance(raw_items, list):
        normalized: List[str] = []
        for item in raw_items:
            if isinstance(item, str):
                parsed_item = item
                text = item.strip()
                if text.startswith("[") or text.startswith("{"):
                    try:
                        parsed_item = json.loads(text)
                    except Exception:
                        parsed_item = item
                if isinstance(parsed_item, dict):
                    for key in ("text", "value", "label", "question", "answer"):
                        candidate = str(parsed_item.get(key) or "").strip()
                        if candidate:
                            normalized.append(candidate)
                            break
                    else:
                        dumped = json.dumps(parsed_item, ensure_ascii=False).strip()
                        if dumped:
                            normalized.append(dumped)
                else:
                    text = str(parsed_item).strip()
                    if text:
                        normalized.append(text)
            else:
                text = str(item).strip()
                if text:
                    normalized.append(text)
        return normalized
    if isinstance(raw_items, str):
        text = raw_items.strip()
        if not text:
            return []
        lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
        if len(lines) > 1:
            normalized: List[str] = []
            for line in lines:
                cleaned = re.sub(r"^\s*(?:[-*]|\d+[.)])\s*", "", line).strip()
                if cleaned:
                    normalized.append(cleaned)
            return normalized
        return [text]
    return []


def _answer_looks_uncertain(answer: str) -> bool:
    text = (answer or "").strip().lower()
    if not text:
        return False
    uncertain_markers = (
        "i don't know",
        "i dont know",
        "do not know",
        "not sure",
        "unsure",
        "idk",
        "no idea",
        "see previous",
        "same as above",
    )
    return any(marker in text for marker in uncertain_markers)


def _agentic_progress_signature(state_path: Optional[str]) -> Optional[Tuple[Any, ...]]:
    from aso_agents.pipeline_tools import _agentic_progress_signature as _impl

    return _impl(state_path)


def _apply_translation_start_guard(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if intake_out.get("status") == "ready":
        structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
        if isinstance(structured_goal, dict) and _translation_start_needs_isoform(structured_goal):
            return {
                "status": "need_clarification",
                "questions": [
                    "Translation-start blocking requires a specific transcript/isoform (e.g., ENST... or MANE/canonical). Which transcript should we use?"
                ],
            }
    return intake_out


def _apply_motif_target_level_guard(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if intake_out.get("status") != "ready":
        return intake_out
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not isinstance(structured_goal, dict):
        return intake_out

    motif_request = _extract_motif_tiling_request(structured_goal)
    if not motif_request:
        return intake_out

    target_level = _normalize_motif_target_level(motif_request.get("target_level"))
    if not target_level:
        return {"status": "need_clarification", "questions": [MOTIF_TARGET_LEVEL_QUESTION]}

    motif_cfg = structured_goal.get("motif_tiling")
    if not isinstance(motif_cfg, dict):
        motif_cfg = {}
    motif_cfg = dict(motif_cfg)
    motif_cfg["motifs"] = motif_request.get("motifs") or motif_cfg.get("motifs")
    if motif_request.get("motifs_input"):
        motif_cfg["motifs_input"] = motif_request.get("motifs_input")
    if motif_request.get("motif_input_alphabet"):
        motif_cfg["motif_input_alphabet"] = motif_request.get("motif_input_alphabet")
    if motif_request.get("aso_overlap_requirement"):
        motif_cfg["aso_overlap_requirement"] = motif_request.get("aso_overlap_requirement")
    motif_cfg["target_level"] = target_level
    if motif_request.get("operator"):
        motif_cfg["operator"] = motif_request.get("operator")
    if motif_request.get("strand_mode"):
        motif_cfg["strand_mode"] = motif_request.get("strand_mode")
    if motif_request.get("max_hits") is not None:
        motif_cfg["max_hits"] = motif_request.get("max_hits")
    structured_goal["motif_tiling"] = motif_cfg
    return intake_out


def _raw_motif_tiling_request(structured_goal: Dict[str, Any]) -> Any:
    if not isinstance(structured_goal, dict):
        return None
    raw_constraints = structured_goal.get("constraints")
    constraints = raw_constraints if isinstance(raw_constraints, dict) else {}
    return (
        structured_goal.get("motif_tiling")
        or constraints.get("motif_tiling")
        or constraints.get("motif_targeting")
        or constraints.get("motifs")
        or constraints.get("motif")
    )


def _motif_tiling_request_is_broad_region_tiling(raw_request: Any, structured_goal: Dict[str, Any]) -> bool:
    if not isinstance(raw_request, dict):
        return False
    motif_keys = ("motifs", "patterns", "sequences", "motif", "motif_name", "motifs_input")
    if any(raw_request.get(key) not in (None, "", [], {}) for key in motif_keys):
        return False
    strategy = str(
        raw_request.get("strategy")
        or raw_request.get("mode")
        or raw_request.get("tiling_strategy")
        or ""
    ).strip().lower()
    if strategy and "til" not in strategy:
        return False
    region = _normalize_target_region(
        raw_request.get("region")
        or raw_request.get("target_region")
        or structured_goal.get("target_region")
    )
    return region in {"utr3", "utr5", "utrs", "translation_start", "cds"}


def _motif_constraint_request_unresolved(constraint: Dict[str, Any]) -> bool:
    if not isinstance(constraint, dict):
        return False
    motif_request = constraint.get("motif_tiling")
    if not isinstance(motif_request, dict) and constraint.get("motifs") is None:
        return False
    if isinstance(motif_request, dict) and _motif_tiling_request_is_broad_region_tiling(motif_request, {}):
        return False
    probe: Dict[str, Any] = {
        "motif_tiling": deepcopy(motif_request) if isinstance(motif_request, dict) else {"motifs": deepcopy(constraint.get("motifs"))},
    }
    target_level = (
        (motif_request or {}).get("target_level")
        if isinstance(motif_request, dict)
        else constraint.get("target_level")
    )
    if target_level is not None:
        probe["motif_target_level"] = target_level
    overlap_requirement = (
        (motif_request or {}).get("aso_overlap_requirement")
        if isinstance(motif_request, dict)
        else constraint.get("aso_overlap_requirement")
    )
    if overlap_requirement is not None:
        probe["aso_overlap_requirement"] = overlap_requirement
    return _extract_motif_tiling_request(probe) is None


def _region_constraint_entry_requests_localization(entry: Dict[str, Any]) -> bool:
    if not isinstance(entry, dict):
        return False

    concrete_keys = {
        "motif_tiling",
        "motifs",
        "rbp_binding",
        "rbp",
        "mirna_binding",
        "miRNA_binding",
        "mirnas",
        "miRNAs",
        "mirna_family_or_id",
        "miRNA_family_or_id",
        "splice_relative_window",
        "rows",
        "bed_rows",
        "genomic_rows",
        "cdna_rows",
        "intervals",
        "genomic_intervals",
        "chr",
        "chrom",
        "chromosome",
        "start",
        "end",
        "pos",
        "position",
        "coordinate",
        "coordinates",
        "exon_label",
        "target_exon",
        "exon_number",
        "exon_index",
        "bed",
        "bed_path",
        "bed_file",
    }
    if any(key in entry for key in concrete_keys):
        return True

    hint = str(
        entry.get("source_type")
        or entry.get("constraint_type")
        or entry.get("type")
        or entry.get("kind")
        or ""
    ).strip().lower()
    if not hint or hint in {"region_constraints", "region_constraint", "preference", "targeting_preference", "note"}:
        return False
    explicit_tokens = (
        "motif",
        "mirna",
        "rbp",
        "coordinate",
        "bed",
        "explicit",
        "exon",
        "site",
        "element",
        "branch",
        "polypyrimidine",
    )
    return any(token in hint for token in explicit_tokens)


def _site_constraint_coordinates_required(structured_goal: Dict[str, Any]) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    raw_motif_request = _raw_motif_tiling_request(structured_goal)
    if raw_motif_request and _extract_motif_tiling_request(structured_goal) is None:
        if (
            not _motif_tiling_request_is_broad_region_tiling(raw_motif_request, structured_goal)
            and not _named_motif_splice_relative_constraints(structured_goal)
        ):
            return True

    raw_constraints = structured_goal.get("region_constraints")
    if isinstance(raw_constraints, list) and raw_constraints:
        normalized_constraints = _normalize_region_constraints(raw_constraints, context=structured_goal)
        for entry in raw_constraints:
            if (
                isinstance(entry, dict)
                and _region_constraint_entry_requests_localization(entry)
                and not _normalize_region_constraints([entry], context=structured_goal)
            ):
                return True
        if any(_motif_constraint_request_unresolved(entry) for entry in normalized_constraints):
            return True

    for program in _iter_design_programs(structured_goal):
        raw_program_constraints = program.get("region_constraints")
        if not isinstance(raw_program_constraints, list) or not raw_program_constraints:
            continue
        normalized_program_constraints = _normalize_region_constraints(raw_program_constraints, context=program)
        for entry in raw_program_constraints:
            if (
                isinstance(entry, dict)
                and _region_constraint_entry_requests_localization(entry)
                and not _normalize_region_constraints([entry], context=program)
            ):
                return True
        if any(_motif_constraint_request_unresolved(entry) for entry in normalized_program_constraints):
            return True
    return False


def _apply_site_coordinate_guard(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if intake_out.get("status") != "ready":
        return intake_out
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not isinstance(structured_goal, dict):
        return intake_out
    if _site_constraint_coordinates_required(structured_goal):
        return {"status": "need_clarification", "questions": [SITE_COORDINATES_REQUIRED_QUESTION]}
    return intake_out


def _has_explicit_splice_coordinate_span(structured_goal: Dict[str, Any]) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    for field in ("explicit_splice_targets", "evaluation_targets"):
        raw = structured_goal.get(field)
        items = raw if isinstance(raw, list) else [raw] if isinstance(raw, dict) else []
        for item in items:
            if not isinstance(item, dict):
                continue
            chrom = str(item.get("chrom") or "").strip()
            start = _coerce_positive_int(item.get("start"))
            end = _coerce_positive_int(item.get("end"))
            if chrom and start is not None and end is not None and start != end:
                return True
    return False


def _collect_nonstandard_splice_exon_labels(structured_goal: Dict[str, Any]) -> List[str]:
    if not isinstance(structured_goal, dict):
        return []
    labels: List[str] = []
    seen: Set[str] = set()

    def _add(value: Any) -> None:
        values = value if isinstance(value, list) else [value]
        for item in values:
            text = str(item or "").strip()
            if not text:
                continue
            embedded = [
                match.group(1).strip()
                for match in re.finditer(r"\bexon\s+([0-9]+[A-Za-z][A-Za-z0-9_.-]*)\b", text, flags=re.IGNORECASE)
            ]
            if embedded:
                for label in embedded:
                    key = label.lower()
                    if key not in seen:
                        seen.add(key)
                        labels.append(label)
                continue
            if not re.search(r"\d", text) or not re.search(r"[A-Za-z]", text):
                continue
            if not re.fullmatch(r"[A-Za-z]*\d+[A-Za-z][A-Za-z0-9_.-]*", text, flags=re.IGNORECASE):
                continue
            if not re.fullmatch(r"(?:exon\s*)?\d+", text, flags=re.IGNORECASE):
                key = text.lower()
                if key not in seen:
                    seen.add(key)
                    labels.append(text)

    for field in ("exon_label", "exon_labels"):
        _add(structured_goal.get(field))
    for objective in structured_goal.get("splice_isoform_objectives") or []:
        if isinstance(objective, dict):
            for field in ("exon_label", "exon_labels", "target_exon", "target_exons"):
                _add(objective.get(field))
    for program in _iter_design_programs(structured_goal):
        for field in ("exon_label", "exon_labels", "target_exon", "target_exons"):
            _add(program.get(field))

    return labels


def _apply_nonstandard_splice_exon_coordinate_guard(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if intake_out.get("status") != "ready":
        return intake_out
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not isinstance(structured_goal, dict):
        return intake_out
    intent = str(structured_goal.get("intent") or "").strip().lower()
    context_text = json.dumps(structured_goal, ensure_ascii=False, default=str).lower()
    if intent != "splice_modulation" and "splice" not in context_text:
        return intake_out
    if _has_explicit_splice_coordinate_span(structured_goal):
        return intake_out
    labels = _collect_nonstandard_splice_exon_labels(structured_goal)
    if not labels:
        return intake_out
    label_text = ", ".join(labels[:4])
    return {
        "status": "need_clarification",
        "kind": "goal_intake",
        "clarification_kind": "goal_intake",
        "restart_stage": "intake",
        "reason": "nonstandard_splice_exon_coordinates_missing",
        "context": (
            f"The request names non-standard exon label(s): {label_text}. "
            "These labels cannot be mapped safely from transcript exon numbers alone."
        ),
        "questions": [
            (
                f"Please provide exact genomic coordinates and strand for {label_text} "
                "(for example, hg38 chr:start-end, strand +/-), or confirm the standard transcript exon number to use."
            )
        ],
    }


def _apply_region_overlap_requirement_guard(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if intake_out.get("status") != "ready":
        return intake_out
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not isinstance(structured_goal, dict):
        return intake_out

    def _scope_requirement(constraints: List[Dict[str, Any]]) -> Tuple[Set[str], bool]:
        requirements: Set[str] = set()
        missing_requirement = False
        for constraint in constraints:
            if not isinstance(constraint, dict):
                continue
            overlap_requirement = _normalize_aso_overlap_requirement(
                constraint.get("aso_overlap_requirement")
            )
            if not overlap_requirement:
                missing_requirement = True
                continue
            requirements.add(overlap_requirement)
        return requirements, missing_requirement

    def _apply_requirement(container: Dict[str, Any], overlap_requirement: str) -> None:
        container["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("rbp_binding"), dict):
            container["rbp_binding"] = dict(container["rbp_binding"])
            container["rbp_binding"]["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("motif_tiling"), dict):
            container["motif_tiling"] = dict(container["motif_tiling"])
            container["motif_tiling"]["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("mirna_binding"), dict):
            container["mirna_binding"] = dict(container["mirna_binding"])
            container["mirna_binding"]["aso_overlap_requirement"] = overlap_requirement

    _normalize_region_constraints_in_goal(structured_goal)
    scope_items: List[Tuple[Dict[str, Any], List[Dict[str, Any]]]] = [
        (structured_goal, _goal_region_constraints(structured_goal))
    ]
    for program in _iter_design_programs(structured_goal):
        constraints = _program_region_constraints(program)
        if constraints:
            scope_items.append((program, constraints))
    if not any(constraints for _container, constraints in scope_items):
        return intake_out

    for container, constraints in scope_items:
        if not constraints:
            continue
        requirements, missing_requirement = _scope_requirement(constraints)
        if missing_requirement or len(requirements) > 1:
            return {"status": "need_clarification", "questions": [CONSTRAINT_OVERLAP_REQUIREMENT_QUESTION]}
        overlap_requirement = next(iter(requirements), None)
        if overlap_requirement:
            _apply_requirement(container, overlap_requirement)
    return intake_out


def _apply_intake_guards(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    guarded = _apply_translation_start_guard(intake_out)
    guarded = _apply_motif_target_level_guard(guarded)
    guarded = _apply_site_coordinate_guard(guarded)
    guarded = _apply_nonstandard_splice_exon_coordinate_guard(guarded)
    guarded = _apply_region_overlap_requirement_guard(guarded)
    return guarded


def _enforce_motif_target_level_requirement(
    structured_goal: Dict[str, Any],
    final_payload: Optional[Dict[str, Any]] = None,
) -> None:
    if not isinstance(structured_goal, dict):
        return
    motif_request = _extract_motif_tiling_request(structured_goal)
    if not motif_request:
        return

    target_level = _normalize_motif_target_level(motif_request.get("target_level"))
    if not target_level:
        raise SystemExit(
            "Motif tiling requires motif_tiling.target_level set to 'pre_mrna' or 'mature_mrna'."
        )

    motif_cfg = structured_goal.get("motif_tiling")
    if not isinstance(motif_cfg, dict):
        motif_cfg = {}
    motif_cfg = dict(motif_cfg)
    motif_cfg["motifs"] = motif_request.get("motifs") or motif_cfg.get("motifs")
    if motif_request.get("motifs_input"):
        motif_cfg["motifs_input"] = motif_request.get("motifs_input")
    if motif_request.get("motif_input_alphabet"):
        motif_cfg["motif_input_alphabet"] = motif_request.get("motif_input_alphabet")
    if motif_request.get("aso_overlap_requirement"):
        motif_cfg["aso_overlap_requirement"] = motif_request.get("aso_overlap_requirement")
    motif_cfg["target_level"] = target_level
    if motif_request.get("operator"):
        motif_cfg["operator"] = motif_request.get("operator")
    if motif_request.get("strand_mode"):
        motif_cfg["strand_mode"] = motif_request.get("strand_mode")
    if motif_request.get("max_hits") is not None:
        motif_cfg["max_hits"] = motif_request.get("max_hits")

    structured_goal["motif_tiling"] = motif_cfg
    if isinstance(final_payload, dict):
        final_payload["motif_tiling"] = motif_cfg


def _enforce_region_constraint_overlap_requirement(
    structured_goal: Dict[str, Any],
    final_payload: Optional[Dict[str, Any]] = None,
    request_text: Any = "",
) -> None:
    if not isinstance(structured_goal, dict):
        return
    def _scope_requirement(constraints: List[Dict[str, Any]]) -> Tuple[Set[str], bool]:
        requirements: Set[str] = set()
        missing_requirement = False
        for constraint in constraints:
            if not isinstance(constraint, dict):
                continue
            overlap_requirement = _normalize_aso_overlap_requirement(
                constraint.get("aso_overlap_requirement")
            )
            if not overlap_requirement:
                missing_requirement = True
                continue
            requirements.add(overlap_requirement)
        return requirements, missing_requirement

    def _apply_requirement(container: Dict[str, Any], overlap_requirement: str) -> None:
        container["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("rbp_binding"), dict):
            container["rbp_binding"] = dict(container["rbp_binding"])
            container["rbp_binding"]["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("motif_tiling"), dict):
            container["motif_tiling"] = dict(container["motif_tiling"])
            container["motif_tiling"]["aso_overlap_requirement"] = overlap_requirement
        if isinstance(container.get("mirna_binding"), dict):
            container["mirna_binding"] = dict(container["mirna_binding"])
            container["mirna_binding"]["aso_overlap_requirement"] = overlap_requirement

    _apply_region_overlap_hints_from_request_text(structured_goal, request_text)
    _normalize_region_constraints_in_goal(structured_goal)
    scope_items: List[Tuple[Dict[str, Any], List[Dict[str, Any]]]] = [
        (structured_goal, _goal_region_constraints(structured_goal))
    ]
    for program in _iter_design_programs(structured_goal):
        constraints = _program_region_constraints(program)
        if constraints:
            scope_items.append((program, constraints))
    if not any(constraints for _container, constraints in scope_items):
        return

    top_level_requirement = ""
    for container, constraints in scope_items:
        if not constraints:
            continue
        requirements, missing_requirement = _scope_requirement(constraints)
        if missing_requirement:
            raise ValueError(
                "Region-constrained ASO design requires aso_overlap_requirement set to 'any_overlap', 'full_containment', or 'contains_feature'."
            )
        if len(requirements) > 1:
            raise ValueError(
                "Mixed aso_overlap_requirement values are not supported within one constrained scope. Use one overlap rule per request/program."
            )
        overlap_requirement = next(iter(requirements), None)
        if not overlap_requirement:
            continue
        _apply_requirement(container, overlap_requirement)
        if container is structured_goal:
            top_level_requirement = overlap_requirement
    if top_level_requirement and isinstance(final_payload, dict):
        final_payload["aso_overlap_requirement"] = top_level_requirement


def _render_clarification_history(qa_history: List[Dict[str, str]]) -> str:
    history_lines = []
    for pair in qa_history:
        request_effect = str(pair.get("request_effect") or "").strip().lower()
        effect_line = (
            f"\nRequest effect: {request_effect}"
            if request_effect in {"augment", "replace", "close"}
            else ""
        )
        history_lines.append(
            f"Q: {pair.get('question')}\nA: {pair.get('answer')}{effect_line}"
        )
    return "\n".join(history_lines) or "(none)"


def _default_goal_intake_clarification_answer(question: Any, user_request: str) -> str:
    question_text = str(question or "").strip()
    if not question_text:
        return ""
    lowered = question_text.lower()
    if "target context" not in lowered:
        return ""
    if not any(token in lowered for token in ("tissue", "cell type", "disease", "model", "no specific")):
        return ""
    request_lower = str(user_request or "").lower()
    if "mouse" in request_lower:
        species_label = "mouse"
    elif "human" in request_lower:
        species_label = "human"
    else:
        species_label = "requested-species"
    return f"No specific tissue/cell/model context; use general {species_label} baseline context."


def _partition_defaultable_goal_intake_questions(
    questions: List[str],
    user_request: str,
) -> Tuple[List[Dict[str, str]], List[str]]:
    defaulted: List[Dict[str, str]] = []
    unresolved: List[str] = []
    for question in questions:
        answer = _default_goal_intake_clarification_answer(question, user_request)
        if answer:
            defaulted.append({"question": question, "answer": answer})
        else:
            unresolved.append(question)
    return defaulted, unresolved


def _normalize_design_programs_in_goal(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    raw_programs = structured_goal.get("design_programs")
    if raw_programs is None:
        return
    if not isinstance(raw_programs, list):
        structured_goal.pop("design_programs", None)
        return
    normalized: List[Dict[str, Any]] = []
    for idx, program in enumerate(raw_programs, start=1):
        if not isinstance(program, dict):
            continue
        entry = {str(key): deepcopy(value) for key, value in program.items() if isinstance(key, str)}
        program_id = str(entry.get("program_id") or "").strip()
        if not program_id:
            program_id = f"program_{idx:02d}"
        entry["program_id"] = program_id
        label = str(entry.get("label") or entry.get("design_label") or entry.get("objective") or program_id).strip()
        if label:
            entry["label"] = label
        modality = _design_program_modality(entry)
        if modality:
            entry["modality"] = modality
        intent = str(entry.get("intent") or "").strip().lower()
        if intent:
            entry["intent"] = intent
        chemistry = _normalize_requested_chemistry(entry.get("chemistry"))
        if chemistry:
            entry["chemistry"] = chemistry
        # Preserve an unresolved description for the semantic chemistry agent.
        # Dropping it here lets a later default replace an explicit request.
        target_region = _normalize_target_region(entry.get("target_region"))
        if target_region:
            entry["target_region"] = target_region
        elif "target_region" in entry:
            entry.pop("target_region", None)
        site_kind = _normalize_design_program_site_kind(entry.get("site_kind"))
        if site_kind:
            entry["site_kind"] = site_kind
        elif "site_kind" in entry:
            entry.pop("site_kind", None)
        site_context = _normalize_design_program_site_context(entry.get("site_context"))
        if site_context:
            entry["site_context"] = site_context
        elif "site_context" in entry:
            entry.pop("site_context", None)
        targeting_policy = _normalize_steric_targeting_policy(entry.get("targeting_policy"))
        if targeting_policy:
            entry["targeting_policy"] = targeting_policy
        elif "targeting_policy" in entry:
            entry.pop("targeting_policy", None)
        for bool_key in ("run_splice_eval", "run_splice_router", "focus_exons_only"):
            coerced = _coerce_bool(entry.get(bool_key))
            if coerced is None:
                entry.pop(bool_key, None)
            else:
                entry[bool_key] = coerced
        flanks = entry.get("flanks")
        if isinstance(flanks, dict):
            flanks_norm: Dict[str, int] = {}
            up_val = _coerce_nonnegative_int(flanks.get("up"))
            down_val = _coerce_nonnegative_int(flanks.get("down"))
            if up_val is not None:
                flanks_norm["up"] = up_val
            if down_val is not None:
                flanks_norm["down"] = down_val
            if flanks_norm:
                entry["flanks"] = flanks_norm
            else:
                entry.pop("flanks", None)
        normalized.append(entry)
    # Some intake responses expand requested candidate slots into duplicate
    # programs. Constraint IDs and labels are presentation identities; the
    # underlying source, interval and overlap rule define the scientific scope.
    def scientific_spec(program: Dict[str, Any]) -> Dict[str, Any]:
        spec = {key: deepcopy(value) for key, value in program.items()
                if key not in {"program_id", "label", "design_label", "notes"}}
        constraints = spec.get("region_constraints")
        if isinstance(constraints, list):
            spec["region_constraints"] = [
                {key: value for key, value in item.items()
                 if key not in {"constraint_id", "label", "notes"}}
                if isinstance(item, dict) else item
                for item in constraints
            ]
        return spec

    requested_count = _coerce_positive_int(structured_goal.get("candidate_limit"))
    minimum_count = _coerce_positive_int(structured_goal.get("candidate_minimum"))
    # An overall panel count describes the number of distinct molecules, not
    # the number of search programs. Equivalent programs can therefore be
    # duplicates even when the parser emitted fewer programs than molecules.
    if len(normalized) > 1 and (requested_count is not None or minimum_count is not None):
        if all(str(program.get("objective") or "").strip() for program in normalized) and not any(
            _coerce_bool(program.get("independent_panel")) is True or program.get("panel_id") not in (None, "")
            for program in normalized
        ):
            scientific_specs = [scientific_spec(program) for program in normalized]
            dropped_ids = {program["program_id"] for program in normalized[1:]}
            for program in normalized[1:]:
                for constraint in program.get("region_constraints") or []:
                    if isinstance(constraint, dict) and constraint.get("constraint_id"):
                        dropped_ids.add(str(constraint["constraint_id"]))
            def references_dropped_program(value: Any) -> bool:
                if isinstance(value, str):
                    return value in dropped_ids
                if isinstance(value, dict):
                    return any(references_dropped_program(item) for item in value.values())
                if isinstance(value, (list, tuple)):
                    return any(references_dropped_program(item) for item in value)
                return False
            other_goal_fields = {key: value for key, value in structured_goal.items() if key != "design_programs"}
            local_counts = {_coerce_positive_int(program.get("candidate_limit")) for program in normalized}
            count_consistent = len(local_counts) == 1 and (
                None in local_counts or requested_count is None or local_counts == {requested_count}
            )
            def compatible_notes(values: List[Any]) -> bool:
                texts = [str(value or "").strip().casefold() for value in values if str(value or "").strip()]
                return not texts or any(all(text in longest for text in texts) for longest in texts)
            note_compatible = compatible_notes([program.get("notes") for program in normalized])
            first_constraints = normalized[0].get("region_constraints")
            if isinstance(first_constraints, list):
                for index in range(len(first_constraints)):
                    note_compatible = note_compatible and compatible_notes([
                        program["region_constraints"][index].get("notes")
                        for program in normalized
                        if isinstance(program.get("region_constraints"), list)
                        and index < len(program["region_constraints"])
                        and isinstance(program["region_constraints"][index], dict)
                    ])
            if (all(spec == scientific_specs[0] for spec in scientific_specs[1:])
                    and not references_dropped_program(other_goal_fields)
                    and count_consistent and note_compatible):
                # Free-text notes are additive evidence, not independent
                # physical search scopes. Preserve every distinct note when
                # identical typed candidate slots collapse into one panel.
                notes = [str(program.get("notes") or "").strip()
                         for program in normalized if str(program.get("notes") or "").strip()]
                if notes:
                    normalized[0]["notes"] = max(notes, key=len)
                if isinstance(first_constraints, list):
                    for index, first_constraint in enumerate(first_constraints):
                        if not isinstance(first_constraint, dict):
                            continue
                        constraint_notes = list(dict.fromkeys(
                            str(program["region_constraints"][index].get("notes") or "").strip()
                            for program in normalized
                            if isinstance(program.get("region_constraints"), list)
                            and index < len(program["region_constraints"])
                            and isinstance(program["region_constraints"][index], dict)
                            and str(program["region_constraints"][index].get("notes") or "").strip()
                        ))
                        if constraint_notes:
                            first_constraint["notes"] = max(constraint_notes, key=len)
                normalized = normalized[:1]
    if normalized:
        structured_goal["design_programs"] = normalized
    else:
        structured_goal.pop("design_programs", None)


def _normalize_envelope_design_programs(envelope: Any) -> None:
    if not isinstance(envelope, dict):
        return
    containers = [envelope, envelope.get("default_context"), envelope.get("task_context")]
    tasks = envelope.get("tasks")
    if isinstance(tasks, list):
        for task in tasks:
            if isinstance(task, dict):
                containers.extend((task, task.get("context")))
    for container in containers:
        if not isinstance(container, dict):
            continue
        _normalize_design_programs_in_goal(container)
        _normalize_design_programs_in_goal(container.get("structured_goal"))


def _normalize_envelope_user_transcript_locks(envelope: Any, request_text: Any) -> None:
    if not isinstance(envelope, dict):
        return
    containers = [envelope, envelope.get("default_context"), envelope.get("task_context")]
    tasks = envelope.get("tasks")
    if isinstance(tasks, list):
        for task in tasks:
            if isinstance(task, dict):
                containers.extend((task, task.get("context")))
    for container in containers:
        if not isinstance(container, dict):
            continue
        _remove_unquoted_user_transcript_lock(container, request_text)
        _remove_unquoted_user_transcript_lock(container.get("structured_goal"), request_text)


def _structured_goal_requests_gapmer_knockdown(structured_goal: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    if str(structured_goal.get("intent") or "").strip().lower() != "knockdown":
        return False
    raw_programs = structured_goal.get("design_programs")
    if isinstance(raw_programs, list) and any(
        isinstance(program, dict) and _design_program_modality(program) == "gapmer"
        for program in raw_programs
    ):
        return False

    # Gapmer-only routing is already an LLM-parsed structured decision. Using it
    # here avoids reparsing request prose when an optional program list is absent.
    splice_router = _coerce_bool(structured_goal.get("run_splice_router"))
    splice_eval = _coerce_bool(structured_goal.get("run_splice_eval"))
    if splice_router is False and splice_eval is False:
        return True

    constraints = structured_goal.get("constraints") if isinstance(structured_goal.get("constraints"), dict) else {}
    chemistry_values: List[Any] = [
        structured_goal.get("chemistry"),
        constraints.get("chemistry"),
        structured_goal.get("platform"),
        structured_goal.get("aso_type"),
        structured_goal.get("aso_modality"),
        structured_goal.get("modality"),
        structured_goal.get("mechanism"),
        constraints.get("aso_type"),
        constraints.get("aso_modality"),
        constraints.get("modality"),
        constraints.get("mechanism"),
    ]
    for value in chemistry_values:
        if isinstance(value, dict):
            aso_type = str(value.get("aso_type") or value.get("type") or value.get("modality") or "").strip().lower()
            mechanism = str(value.get("mechanism") or value.get("mechanism_of_action") or "").strip().lower()
            if aso_type == "gapmer" or mechanism in {"rnaseh", "rnase_h", "rnase h"}:
                return True
        elif isinstance(value, str):
            normalized = value.strip().lower().replace("-", "_").replace(" ", "_")
            if normalized in {"gapmer", "rnaseh", "rnase_h", "rnase_h_gapmer"}:
                return True
    return False


def _gapmer_goal_has_explicit_region_scope(structured_goal: Dict[str, Any]) -> bool:
    if _normalize_target_region(structured_goal.get("target_region")):
        return True
    for key in ("explicit_splice_targets", "patient_variant", "region_constraints", "materialized_region_constraints"):
        value = structured_goal.get(key)
        if value not in (None, "", [], {}):
            return True
    for key in ("rbp_binding", "motif_tiling", "mirna_binding"):
        value = structured_goal.get(key)
        if isinstance(value, dict) and value:
            return True
    return False


def _synthesize_default_gapmer_program_if_needed(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    if not _structured_goal_requests_gapmer_knockdown(structured_goal):
        return
    constraints = structured_goal.get("constraints") if isinstance(structured_goal.get("constraints"), dict) else {}
    requested_chemistry = constraints.get("chemistry") or structured_goal.get("chemistry")
    chemistry = _normalize_requested_chemistry(requested_chemistry) or deepcopy(requested_chemistry) or {}
    chemistry_constraint = constraints.get("chemistry") if isinstance(constraints.get("chemistry"), dict) else {}
    length = _coerce_positive_int(
        chemistry_constraint.get("length_nt")
        or chemistry_constraint.get("length")
        or constraints.get("length_nt")
        or constraints.get("oligo_length_nt")
        or structured_goal.get("length_nt")
        or structured_goal.get("oligo_length_nt")
    )
    if length is None and isinstance(chemistry, dict):
        length = _coerce_positive_int(chemistry.get("length") or chemistry.get("length_nt"))
    gene = str(structured_goal.get("gene_symbol") or structured_goal.get("gene_id") or "gene").strip()
    safe_gene = re.sub(r"[^a-z0-9]+", "_", gene.lower()).strip("_") or "gene"
    program: Dict[str, Any] = {
        "program_id": f"gapmer_{safe_gene}_gene_wide",
        "label": f"{gene} gene-wide RNase H gapmer tiling",
        "modality": "gapmer",
        "intent": "knockdown",
        "objective": "Tile mature transcript sequence with RNase H gapmer candidates for gene-level knockdown.",
        "selection_source": "deterministic_default_gapmer_gene_wide",
    }
    if chemistry:
        program["chemistry"] = chemistry
    if length:
        program["chemistry_length"] = length
    if structured_goal.get("target_scope"):
        program["target_scope"] = structured_goal.get("target_scope")
    target_region = _normalize_target_region(structured_goal.get("target_region"))
    if target_region:
        program["target_region"] = target_region
    for field in ("region_constraints", "explicit_splice_targets"):
        value = structured_goal.get(field)
        if value not in (None, "", [], {}):
            program[field] = deepcopy(value)
    if "run_splice_eval" not in structured_goal:
        structured_goal["run_splice_eval"] = False
    if "run_splice_router" not in structured_goal:
        structured_goal["run_splice_router"] = False

    raw_programs = structured_goal.get("design_programs")
    programs = [entry for entry in raw_programs if isinstance(entry, dict)] if isinstance(raw_programs, list) else []
    programs.append(program)
    structured_goal["design_programs"] = programs
    _normalize_design_programs_in_goal(structured_goal)


def _normalize_steric_targeting_policy(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "explicit": "explicit_user_region",
        "explicit_user": "explicit_user_region",
        "explicit_region": "explicit_user_region",
        "explicit_user_target": "explicit_user_region",
        "specific": "explicit_user_region",
        "specific_region": "explicit_user_region",
        "user_region": "explicit_user_region",
        "user_specified": "explicit_user_region",
        "default": "default_exploratory",
        "exploratory": "default_exploratory",
        "default_explore": "default_exploratory",
        "exploratory_default": "default_exploratory",
        "auto_explore": "default_exploratory",
        "derived": "exploratory_derived",
        "derived_exploratory": "exploratory_derived",
        "auto_derived": "exploratory_derived",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"explicit_user_region", "default_exploratory", "exploratory_derived"} else ""


def _normalize_steric_targeting_policy_in_goal(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    normalized = _normalize_steric_targeting_policy(
        structured_goal.get("steric_targeting_policy") or structured_goal.get("targeting_policy")
    )
    if normalized:
        structured_goal["steric_targeting_policy"] = normalized
    else:
        structured_goal.pop("steric_targeting_policy", None)
    structured_goal.pop("targeting_policy", None)


def _normalize_isoform_scope_source(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "user": "user_specified",
        "explicit": "user_specified",
        "explicit_user": "user_specified",
        "user_locked": "user_specified",
        "resolver": "resolver_inferred",
        "inferred": "resolver_inferred",
        "resolved": "resolver_inferred",
        "auto": "resolver_inferred",
        "default": "default_exon_splice_context",
        "default_exon_context": "default_exon_splice_context",
        "default_transcript_context": "default_exon_splice_context",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"user_specified", "resolver_inferred", "default_exon_splice_context"} else ""


def _normalize_isoform_scope_source_in_goal(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    normalized = _normalize_isoform_scope_source(structured_goal.get("isoform_scope_source"))
    if normalized:
        structured_goal["isoform_scope_source"] = normalized
    else:
        structured_goal.pop("isoform_scope_source", None)


def _normalize_splice_isoform_objectives_in_goal(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    raw_objectives = structured_goal.get("splice_isoform_objectives")
    if not isinstance(raw_objectives, list):
        return
    normalized_objectives: List[Any] = []
    for objective in raw_objectives:
        if not isinstance(objective, dict):
            normalized_objectives.append(objective)
            continue
        item = objective
        scope = _normalize_splice_objective_scope(item.get("objective_scope"))
        if scope:
            item["objective_scope"] = scope
            if scope == "default_exon_context":
                structured_goal.setdefault("isoform_scope_source", "default_exon_splice_context")
        aggregate_class = _normalize_splice_aggregate_class(item.get("aggregate_class"), item)
        if aggregate_class:
            item["aggregate_class"] = aggregate_class
            item["objective_scope"] = "aggregate_class"
        normalized_objectives.append(item)
    structured_goal["splice_isoform_objectives"] = normalized_objectives


def _extract_explicit_transcript_accessions_from_text(request_text: Any) -> List[str]:
    text = str(request_text or "")
    if not text:
        return []
    candidates: List[str] = []
    for pattern in (
        r"\bENS[A-Z]*T\d+(?:\.\d+)?\b",
        r"\b(?:N[MR]|X[MR])_\d+(?:\.\d+)?\b",
    ):
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            value = match.group(0).strip()
            if value and value.upper() not in {item.upper() for item in candidates}:
                candidates.append(value)
    return candidates


def _remove_unquoted_user_transcript_lock(
    structured_goal: Optional[Dict[str, Any]],
    request_text: Any,
    final_payload: Optional[Dict[str, Any]] = None,
) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    existing_lock = structured_goal.get("transcript_lock")
    if isinstance(existing_lock, dict) and str(existing_lock.get("source") or "") in {
        "user_request", "explicit_request_text",
    }:
        # A user-authored lock requires the accession in the actual request.
        # Intake may choose a public transcript but must not recast a model-
        # inferred accession as a user command and then exclude the resolved
        # reference catalog. Compare accession identity without version so a
        # user-supplied unversioned ID can resolve to an annotated version.
        accession = str(existing_lock.get("value") or "").strip()
        base_accession = accession.split(".", 1)[0].casefold()
        if base_accession and base_accession not in str(request_text or "").casefold():
            structured_goal.pop("transcript_lock", None)
            if str(structured_goal.get("transcript_policy") or "").strip() == "user_locked":
                structured_goal.pop("transcript_policy", None)
            if isinstance(final_payload, dict):
                final_payload.pop("transcript_lock", None)
                if str(final_payload.get("transcript_policy") or "").strip() == "user_locked":
                    final_payload.pop("transcript_policy", None)
            return True
    return False


def _apply_explicit_transcript_lock_from_request_text(
    structured_goal: Optional[Dict[str, Any]],
    request_text: Any,
    final_payload: Optional[Dict[str, Any]] = None,
) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    _remove_unquoted_user_transcript_lock(structured_goal, request_text, final_payload)
    existing_lock = structured_goal.get("transcript_lock")
    if isinstance(existing_lock, dict) and str(existing_lock.get("value") or "").strip():
        return False
    accessions = _extract_explicit_transcript_accessions_from_text(request_text)
    unique = []
    seen: Set[str] = set()
    for accession in accessions:
        key = accession.split(".", 1)[0].upper()
        if key in seen:
            continue
        seen.add(key)
        unique.append(accession)
    if len(unique) != 1:
        return False

    accession = unique[0]
    kind = "reference_accession" if _looks_like_refseq_transcript_accession(accession) else "explicit_id"
    lock = {
        "kind": kind,
        "value": accession,
        "source": "explicit_request_text",
        "note": "Preserved exact transcript accession supplied by the user.",
    }
    structured_goal["transcript_policy"] = "user_locked"
    structured_goal["transcript_lock"] = lock

    objectives = structured_goal.get("splice_isoform_objectives")
    if isinstance(objectives, list):
        for objective in objectives:
            if not isinstance(objective, dict):
                continue
            if kind == "reference_accession":
                objective.setdefault("reference_accession", accession)
            else:
                objective.setdefault("transcript_id", accession)
    if isinstance(final_payload, dict):
        final_payload["transcript_policy"] = structured_goal["transcript_policy"]
        final_payload["transcript_lock"] = deepcopy(lock)
        if isinstance(objectives, list):
            final_payload["splice_isoform_objectives"] = deepcopy(objectives)
        if isinstance(final_payload.get("structured_goal"), dict):
            final_payload["structured_goal"]["transcript_policy"] = structured_goal["transcript_policy"]
            final_payload["structured_goal"]["transcript_lock"] = deepcopy(lock)
    return True


def _request_mentions_co_skipping(request_text: Any) -> bool:
    text = str(request_text or "").strip().lower()
    if not text:
        return False
    normalized = re.sub(r"[\s_-]+", " ", text)
    if any(token in normalized for token in ("co skip", "co skipping", "co skipped", "coskip", "coskipping")):
        return True
    return bool(re.search(r"\bco\s*[-_ ]?\s*skip(?:ping|ped)?\b", text, flags=re.IGNORECASE))


def _extract_requested_co_skip_exon_groups(request_text: Any) -> List[List[int]]:
    if not _request_mentions_co_skipping(request_text):
        return []
    text = str(request_text or "")
    groups: List[List[int]] = []
    seen: Set[Tuple[int, ...]] = set()

    def _add_group(values: List[int]) -> None:
        normalized: List[int] = []
        for value in values:
            if isinstance(value, int) and value > 0 and value not in normalized:
                normalized.append(value)
        if len(normalized) < 2:
            return
        key = tuple(normalized)
        if key in seen:
            return
        seen.add(key)
        groups.append(normalized)

    range_sep = r"(?:[-\u2010-\u2015]|\bto\b|\bthrough\b|\bthru\b)"
    for match in re.finditer(
        rf"\bexons?\s+(\d+)\s*{range_sep}\s*(\d+)\b",
        text,
        flags=re.IGNORECASE,
    ):
        start = _coerce_positive_int(match.group(1))
        end = _coerce_positive_int(match.group(2))
        if start is None or end is None:
            continue
        low, high = sorted((start, end))
        if high - low > 20:
            continue
        _add_group(list(range(low, high + 1)))

    for match in re.finditer(
        r"\bexons?\s+(\d+)\s*(?:,|\band\b|&|\+|/)\s*(\d+)\b",
        text,
        flags=re.IGNORECASE,
    ):
        first = _coerce_positive_int(match.group(1))
        second = _coerce_positive_int(match.group(2))
        if first is not None and second is not None:
            _add_group([first, second])

    return groups


def _format_exon_group_label(exon_group: List[int]) -> str:
    values = [int(value) for value in exon_group if isinstance(value, int)]
    if not values:
        return ""
    if len(values) == 1:
        return str(values[0])
    if values == list(range(values[0], values[-1] + 1)):
        return f"{values[0]}-{values[-1]}"
    return ", ".join(str(value) for value in values)


def _apply_requested_co_skip_events_from_text(
    structured_goal: Optional[Dict[str, Any]],
    request_text: Any,
) -> None:
    if not isinstance(structured_goal, dict):
        return
    if str(structured_goal.get("intent") or "").strip().lower() != "splice_modulation":
        return
    exon_groups = _extract_requested_co_skip_exon_groups(request_text)
    if not exon_groups:
        return

    transcript_lock = structured_goal.get("transcript_lock") if isinstance(structured_goal.get("transcript_lock"), dict) else {}
    reference_accession = ""
    if isinstance(transcript_lock, dict) and str(transcript_lock.get("kind") or "").strip().lower() == "reference_accession":
        reference_accession = str(transcript_lock.get("value") or "").strip()

    objectives: List[Dict[str, Any]] = []
    for exon_group in exon_groups:
        label = _format_exon_group_label(exon_group)
        objective: Dict[str, Any] = {
            "objective_scope": "default_exon_context",
            "exon_labels": exon_group,
            "desired_abundance": "decrease",
            "desired_effect": "skipping",
            "role": "context",
            "rationale": f"User explicitly requested co-skipping of exons {label}.",
        }
        if reference_accession:
            objective["reference_accession"] = reference_accession
        objectives.append(objective)

    structured_goal["splice_isoform_objectives"] = objectives
    structured_goal["isoform_scope_source"] = "default_exon_splice_context"
    structured_goal["focus_exons_only"] = True
    structured_goal["desired_effect"] = "skipping"
    structured_goal["exon_labels"] = list(
        dict.fromkeys(exon for group in exon_groups for exon in group)
    )

    raw_programs = structured_goal.get("design_programs")
    existing_programs = [deepcopy(item) for item in raw_programs if isinstance(item, dict)] if isinstance(raw_programs, list) else []

    def _is_splice_program(program: Dict[str, Any]) -> bool:
        intent = str(program.get("intent") or "").strip().lower()
        if intent == "splice_modulation":
            return True
        if _coerce_bool(program.get("run_splice_eval")) is True or _coerce_bool(program.get("run_splice_router")) is True:
            return True
        text = _design_program_text(program)
        return "splice" in text or "skip" in text

    base_program: Dict[str, Any] = {}
    for program in existing_programs:
        if _is_splice_program(program):
            base_program = deepcopy(program)
            break
    retained_programs = [program for program in existing_programs if not _is_splice_program(program)]

    for exon_group in exon_groups:
        label = _format_exon_group_label(exon_group)
        program = deepcopy(base_program)
        for stale_key in ("exon_label", "target_exon"):
            program.pop(stale_key, None)
        program.update(
            {
                "program_id": f"steric_exons_{'_'.join(str(exon) for exon in exon_group)}_coskipping",
                "label": f"Co-skip exons {label}",
                "modality": "steric",
                "intent": "splice_modulation",
                "objective": f"Design steric ASOs to induce co-skipping of exons {label}.",
                "desired_delta": "decrease",
                "desired_effect": "skipping",
                "exon_labels": exon_group,
                "run_splice_router": True,
                "run_splice_eval": True,
                "focus_exons_only": True,
                "selection_source": "explicit_user_co_skipping_request",
            }
        )
        retained_programs.append(program)

    structured_goal["design_programs"] = retained_programs


def _design_program_modality(program: Any) -> str:
    if not isinstance(program, dict):
        return ""
    return str(program.get("modality") or "").strip().lower()


def _iter_design_programs(structured_goal: Optional[Dict[str, Any]], modality: str = "") -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    raw_programs = structured_goal.get("design_programs")
    if not isinstance(raw_programs, list):
        return []
    modality_norm = str(modality or "").strip().lower()
    programs: List[Dict[str, Any]] = []
    for idx, program in enumerate(raw_programs, start=1):
        if not isinstance(program, dict):
            continue
        program_modality = _design_program_modality(program)
        if modality_norm and program_modality != modality_norm:
            continue
        program_copy = dict(program)
        if not str(program_copy.get("program_id") or "").strip():
            program_copy["program_id"] = f"{program_modality or modality_norm or 'program'}_{idx:02d}"
        programs.append(program_copy)
    return programs


def _design_program_text(program: Any) -> str:
    if not isinstance(program, dict):
        return ""
    parts = [
        program.get("label"),
        program.get("objective"),
        program.get("notes"),
        program.get("intent"),
        program.get("target_region"),
        program.get("site_kind"),
        program.get("site_context"),
    ]
    return " ".join(str(part).strip() for part in parts if str(part or "").strip()).lower()


def _normalize_design_program_site_kind(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "3ss": "acceptor",
        "acceptor_site": "acceptor",
        "splice_acceptor": "acceptor",
        "5ss": "donor",
        "donor_site": "donor",
        "splice_donor": "donor",
        "splice_site": "both",
        "junction": "both",
        "both_sites": "both",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"acceptor", "donor", "both"} else ""


def _normalize_design_program_site_context(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "site": "site_window",
        "window": "site_window",
        "splice_site": "site_window",
        "splice_window": "site_window",
        "junction_window": "site_window",
        "upstream_intronic": "upstream_intron",
        "intronic_upstream": "upstream_intron",
        "upstream_intron_window": "upstream_intron",
        "downstream_intronic": "downstream_intron",
        "intronic_downstream": "downstream_intron",
        "downstream_intron_window": "downstream_intron",
        "exonic": "exon_body",
        "exonic_side": "exon_body",
        "exon": "exon_body",
        "exon_window": "exon_body",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"site_window", "upstream_intron", "downstream_intron", "exon_body"} else ""


def _has_splice_objective_signal(payload: Any) -> bool:
    if not isinstance(payload, dict):
        return False
    splice_objective = payload.get("splice_objective")
    if isinstance(splice_objective, dict) and any(value not in (None, "", [], {}) for value in splice_objective.values()):
        return True
    for key in (
        "splice_isoform_objectives",
        "splice_site_plan",
        "site_direction_hints",
        "explicit_splice_targets",
    ):
        value = payload.get(key)
        if isinstance(value, list) and value:
            return True
    return False


def _design_program_requires_splice_eval(program: Any) -> bool:
    if not isinstance(program, dict):
        return False
    explicit = _coerce_bool(program.get("run_splice_eval"))
    if explicit is not None:
        return explicit
    target_region = _normalize_target_region(program.get("target_region"))
    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False
    if _has_splice_objective_signal(program):
        return True
    intent = str(program.get("intent") or "").strip().lower()
    return intent in {"splice_modulation", "knockdown"}


def _design_program_requires_splice_router(program: Any) -> bool:
    if not isinstance(program, dict):
        return False
    explicit = _coerce_bool(program.get("run_splice_router"))
    if explicit is not None:
        return explicit
    target_region = _normalize_target_region(program.get("target_region"))
    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False
    if _has_splice_objective_signal(program):
        return True
    intent = str(program.get("intent") or "").strip().lower()
    return intent == "splice_modulation"


def _relabel_region_rows(rows: Any, label: str) -> List[List[Any]]:
    relabeled: List[List[Any]] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, list) or len(row) < 3:
            continue
        row_copy = list(row[:6])
        while len(row_copy) < 6:
            row_copy.append("+" if len(row_copy) == 5 else 0)
        row_copy[3] = label
        relabeled.append(row_copy)
    return relabeled


def _build_followup_prompt(user_request: str, qa_history: List[Dict[str, str]]) -> str:
    history_text = _render_clarification_history(qa_history)
    return (
        "Continue goal intake based on the user's answers.\n\n"
        f"Original request: {user_request}\n"
        f"Clarification history so far:\n{history_text}\n\n"
        "Use the history above to fill any known fields and only ask about missing fields.\n"
        "Do not repeat any previously answered questions.\n"
        "If the user left transcript selection open, asked to choose later, or said to search later, do not ask again; leave transcript_policy='agent_choice'.\n"
        "If the request mixes multiple requested steric/gapmer sets, encode them in structured_goal.design_programs instead of asking to split the run.\n"
        "Return JSON with fields: status ('ready' or 'need_clarification'), and when ready include 'structured_goal'.\n"
        "If need_clarification, include only new, not-previously-asked questions."
    )


def _build_completion_prompt(
    user_request: str,
    qa_history: List[Dict[str, str]],
    open_questions: List[str],
) -> str:
    history_text = _render_clarification_history(qa_history)
    question_lines = [f"- {question}" for question in open_questions if str(question).strip()]
    questions_text = "\n".join(question_lines) if question_lines else "(none)"
    return (
        "Finalize goal intake using the answered clarification history below.\n\n"
        f"Original request: {user_request}\n"
        f"Clarification history:\n{history_text}\n\n"
        f"Remaining open points:\n{questions_text}\n\n"
        "Return JSON with fields: status='ready' and structured_goal.\n"
        "Do not ask more clarification questions.\n"
        "Use reasonable downstream-compatible assumptions for any remaining ambiguity.\n"
        "If transcript selection remains open, leave transcript_policy='agent_choice' and transcript_lock absent.\n"
        "If the request mixes multiple requested steric/gapmer sets, preserve them in structured_goal.design_programs.\n"
    )


def _parse_agent_json(payload: Any) -> Dict[str, Any]:
    if isinstance(payload, dict):
        return payload
    if isinstance(payload, str):
        try:
            return json.loads(payload)
        except Exception as exc:  # pragma: no cover - defensive parsing
            raise RuntimeError(f"Goal intake agent did not return JSON: {payload}") from exc
    raise RuntimeError(f"Unexpected goal intake payload type: {type(payload)}")


