def _normalize_splice_objective_scope(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if not text:
        return ""
    text = _SPLICE_OBJECTIVE_SCOPE_ALIASES.get(text, text)
    return text if text in _CANONICAL_SPLICE_OBJECTIVE_SCOPES else ""


def _normalize_aggregate_basis(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if not text:
        return ""
    text = _AGGREGATE_BASIS_ALIASES.get(text, text)
    return text if text in _CANONICAL_AGGREGATE_BASES else ""


def _normalize_aggregate_presence(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if not text:
        return ""
    text = _AGGREGATE_PRESENCE_ALIASES.get(text, text)
    return text if text in {"included", "excluded"} else ""


def _normalize_splice_aggregate_class(
    value: Any,
    objective: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    source = value if isinstance(value, dict) else {}
    objective = objective if isinstance(objective, dict) else {}
    basis = _normalize_aggregate_basis(source.get("basis") or objective.get("aggregate_basis"))
    if not basis and source:
        basis = _normalize_aggregate_basis(source.get("type") or source.get("kind") or source.get("class"))
    if not basis:
        return {}

    normalized: Dict[str, Any] = {"basis": basis}
    if basis == "exon_presence":
        exon_values = []
        for raw in (
            source.get("exon_label"),
            source.get("exon_labels"),
            objective.get("exon_label"),
            objective.get("exon_labels"),
        ):
            from aso_agents.feature_identity import exon_number
            for value in raw if isinstance(raw, list) else [raw]:
                number = exon_number(value)
                label = number if number is not None else value.strip() if isinstance(value, str) else None
                if label and label not in exon_values:
                    exon_values.append(label)
        if not exon_values:
            return {}
        normalized["exon_label"] = exon_values[0]
        if len(exon_values) > 1:
            normalized["exon_labels"] = exon_values
        presence = _normalize_aggregate_presence(
            source.get("presence")
            or source.get("exon_presence")
            or objective.get("aggregate_presence")
            or objective.get("exon_presence")
        )
        if not presence:
            return {}
        normalized["presence"] = presence
    elif basis == "role":
        role = str(source.get("role") or objective.get("role") or "").strip().lower()
        if role not in {"beneficial", "pathogenic", "context"}:
            return {}
        normalized["role"] = role
    elif basis == "residual_other_isoforms":
        pass

    label = str(source.get("label") or "").strip()
    if label:
        normalized["label"] = label
    return normalized


def _splice_aggregate_class_key(objective: Dict[str, Any], isoform_label: Any = None) -> str:
    label = str(isoform_label or objective.get("isoform_label") or objective.get("label") or "").strip()
    if label:
        return label
    aggregate_class = _normalize_splice_aggregate_class(objective.get("aggregate_class"), objective)
    basis = str(aggregate_class.get("basis") or "aggregate_class").strip() or "aggregate_class"
    parts = ["aggregate", basis]
    if basis == "exon_presence":
        exon_label = aggregate_class.get("exon_label")
        if exon_label:
            parts.append(f"exon_{exon_label}")
        if aggregate_class.get("presence"):
            parts.append(str(aggregate_class["presence"]))
    elif basis == "role" and aggregate_class.get("role"):
        parts.append(str(aggregate_class["role"]))
    elif basis == "residual_other_isoforms":
        parts.append("residual")
    return ":".join(parts)


def _iter_splice_isoform_objective_records(payload: Any) -> List[Tuple[str, Dict[str, Any]]]:
    records: List[Tuple[str, Dict[str, Any]]] = []

    def _walk(value: Any, path: str) -> None:
        if isinstance(value, dict):
            raw_objectives = value.get("splice_isoform_objectives")
            if isinstance(raw_objectives, list):
                for idx, objective in enumerate(raw_objectives):
                    if isinstance(objective, dict):
                        records.append((f"{path}.splice_isoform_objectives[{idx}]", objective))
            for key, child in value.items():
                child_path = f"{path}.{key}" if path else str(key)
                _walk(child, child_path)
        elif isinstance(value, list):
            for idx, item in enumerate(value):
                _walk(item, f"{path}[{idx}]")

    _walk(payload, "$")
    return records


def _splice_objective_has_transcript_or_artifact_reference(objective: Dict[str, Any]) -> bool:
    for field in _SPLICE_OBJECTIVE_TRANSCRIPT_FIELDS + ("snapgene_path", "artifact_ref", "artifact_ref_path"):
        if str(objective.get(field) or "").strip():
            return True
    return False


def _find_splice_objective_schema_violations(payload: Any, *, limit: int = 80) -> List[Dict[str, str]]:
    violations: List[Dict[str, str]] = []
    for path, objective in _iter_splice_isoform_objective_records(payload):
        if len(violations) >= limit:
            break
        raw_scope = objective.get("objective_scope")
        scope = _normalize_splice_objective_scope(raw_scope)
        if raw_scope not in (None, "") and not scope:
            violations.append(
                {
                    "path": f"{path}.objective_scope",
                    "key": "objective_scope",
                    "replacement": (
                        "one of specific_transcript, specific_isoform, aggregate_class, "
                        "default_exon_context"
                    ),
                    "category": "splice_isoform_objective",
                }
            )
            if len(violations) >= limit:
                break

        for key in _SPLICE_OBJECTIVE_AGGREGATE_ALIAS_KEYS:
            if key in objective:
                violations.append(
                    {
                        "path": f"{path}.{key}",
                        "key": key,
                        "replacement": _SPLICE_OBJECTIVE_AGGREGATE_ALIAS_KEYS[key],
                        "category": "splice_isoform_objective",
                    }
                )
                if len(violations) >= limit:
                    break
        if len(violations) >= limit:
            break

        aggregate_raw = objective.get("aggregate_class")
        aggregate_norm = _normalize_splice_aggregate_class(aggregate_raw, objective)
        if aggregate_raw not in (None, "", [], {}) and scope != "aggregate_class":
            violations.append(
                {
                    "path": f"{path}.objective_scope",
                    "key": "objective_scope",
                    "replacement": "set objective_scope='aggregate_class' when aggregate_class is present",
                    "category": "splice_isoform_objective",
                }
            )
        elif scope == "aggregate_class" and not aggregate_norm:
            violations.append(
                {
                    "path": f"{path}.aggregate_class",
                    "key": "aggregate_class",
                    "replacement": (
                        "canonical aggregate_class, e.g. {basis:'exon_presence', exon_label:int|str, "
                        "presence:'included'|'excluded'}, {basis:'role', role:'beneficial'|'pathogenic'|'context'}, "
                        "or {basis:'residual_other_isoforms'}"
                    ),
                    "category": "splice_isoform_objective",
                }
            )
        elif (
            raw_scope in (None, "")
            and not _splice_objective_has_transcript_or_artifact_reference(objective)
        ):
            violations.append(
                {
                    "path": f"{path}.objective_scope",
                    "key": "objective_scope",
                    "replacement": (
                        "add objective_scope so the item is classified as specific_isoform, aggregate_class, "
                        "or default_exon_context without relying on labels/rationale text"
                    ),
                    "category": "splice_isoform_objective",
                }
            )
    return violations


def _goal_schema_repair_enabled() -> bool:
    raw = str(os.environ.get("ASO_GOAL_SCHEMA_REPAIR", "1")).strip().lower()
    return raw not in {"0", "false", "no", "off", "disabled"}


def _goal_schema_repair_max_attempts() -> int:
    raw = str(os.environ.get("ASO_GOAL_SCHEMA_REPAIR_MAX_ATTEMPTS") or "2").strip()
    try:
        value = int(raw)
    except Exception:
        value = 2
    return max(0, min(value, 4))


def _find_goal_schema_key_violations(payload: Any, *, limit: int = 80) -> List[Dict[str, str]]:
    violations: List[Dict[str, str]] = []

    def _walk(value: Any, path: str) -> None:
        if len(violations) >= limit:
            return
        if isinstance(value, dict):
            for key, child in value.items():
                key_text = str(key)
                child_path = f"{path}.{key_text}" if path else key_text
                replacement = _GOAL_SCHEMA_ALIAS_REPLACEMENTS.get(key_text)
                if replacement is not None:
                    violations.append(
                        {
                            "path": child_path,
                            "key": key_text,
                            "replacement": replacement,
                        }
                    )
                    if len(violations) >= limit:
                        return
                _walk(child, child_path)
        elif isinstance(value, list):
            for idx, item in enumerate(value):
                if len(violations) >= limit:
                    return
                _walk(item, f"{path}[{idx}]")

    _walk(payload, "$")
    if len(violations) < limit:
        violations.extend(_find_splice_objective_schema_violations(payload, limit=limit - len(violations)))
    if len(violations) < limit and isinstance(payload, dict):
        goal = payload.get("structured_goal")
        programs = goal.get("design_programs") if isinstance(goal, dict) else None
        if isinstance(programs, list):
            for index, program in enumerate(programs):
                if not isinstance(program, dict):
                    continue
                if str(program.get("targeting_policy") or "").strip().lower() != "explicit_user_region":
                    continue
                if str(program.get("intent") or goal.get("intent") or "").strip().lower() != "binding":
                    continue
                if str(program.get("modality") or "").strip().lower() != "steric":
                    continue
                if _normalize_target_region(program.get("target_region") or goal.get("target_region")):
                    continue
                if any(program.get(key) or goal.get(key) for key in (
                    "region_constraints", "region_rows", "explicit_splice_targets",
                    "rbp_binding", "mirna_binding", "motif_tiling",
                )):
                    continue
                violations.append({
                    "path": f"$.structured_goal.design_programs[{index}].target_region",
                    "key": "target_region",
                    "replacement": (
                        "the executable feature target and any explicitly stated numeric "
                        "mature-RNA window in target_region and flanks; preserve the "
                        "original program and do not infer a genomic coordinate"
                    ),
                    "category": "binding_feature_region",
                })
                if len(violations) >= limit:
                    break
    return violations


def _build_goal_schema_repair_prompt(
    original_prompt: str,
    raw_payload: Dict[str, Any],
    violations: List[Dict[str, str]],
) -> str:
    violation_lines = [
        f"- {item.get('path')}: replace `{item.get('key')}` with {item.get('replacement')}"
        for item in violations[:80]
    ]
    return (
        "The previous ASO goal-intake response has non-canonical or incomplete executable goal fields.\n"
        "Return a corrected full intake JSON payload using the exact schema keys below. Do not summarize.\n\n"
        "Original user/intake prompt:\n"
        f"{original_prompt}\n\n"
        "Detected schema violations:\n"
        f"{chr(10).join(violation_lines)}\n\n"
        "Canonical executable constraint schema:\n"
        "- GC bounds must be under structured_goal.constraints.gc_content with keys min, max, min_inclusive, max_inclusive, min_percent, max_percent.\n"
        "- Off-target/mapping limits must be structured_goal.constraints.max_binding_sites.\n"
        "- Homopolymer limits must be structured_goal.constraints.homopolymers.per_base_max, max_run, and/or avoid_sequences.\n"
        "- Region overlap constraints must use aso_overlap_requirement and minimum_overlap_bp exactly.\n\n"
        "- A binding design program with explicit_user_region must name an executable target_region or a concrete region constraint. If the user specified a feature-relative window, preserve its exact numeric mature-RNA upstream/downstream bounds in flanks on that program. Do not invent a feature or window.\n\n"
        "Canonical splice_isoform_objectives item schema:\n"
        "- Use keys: objective_scope, isoform_label, transcript_id, reference_accession, exon_label, exon_labels, desired_abundance, desired_effect, direction, role, rationale, notes, aggregate_class.\n"
        "- objective_scope must be one of: specific_transcript, specific_isoform, aggregate_class, default_exon_context.\n"
        "- Use specific_transcript when an explicit transcript_id/reference_accession/artifact defines the isoform. Do not invent transcript IDs.\n"
        "- Use specific_isoform when the user names one concrete isoform/construct but no transcript ID is known yet.\n"
        "- Use aggregate_class for qualitative groups of isoforms/transcripts. Encode the group as aggregate_class instead of only in isoform_label/rationale.\n"
        "- aggregate_class must be one of: {basis:'exon_presence', exon_label:int|str, presence:'included'|'excluded'}, {basis:'role', role:'beneficial'|'pathogenic'|'context'}, or {basis:'residual_other_isoforms'}.\n"
        "- Use default_exon_context for exon-only splice objectives where the user specified an exon/effect but did not specify an isoform/transcript; downstream resolution will choose the default transcript context.\n"
        "- Do not add custom keys such as target_class, isoform_class, transcript_class, aggregate_basis, aggregate_presence, or exon_presence.\n\n"
        "Raw payload to repair:\n"
        f"{json.dumps(raw_payload, ensure_ascii=False, indent=2, default=str)}"
    )


async def _repair_goal_schema_if_needed(prompt: str, raw_payload: Dict[str, Any]) -> Dict[str, Any]:
    if not _goal_schema_repair_enabled() or not isinstance(raw_payload, dict):
        return raw_payload
    current = raw_payload
    attempts = _goal_schema_repair_max_attempts()
    for _attempt in range(attempts):
        violations = _find_goal_schema_key_violations(current)
        if not violations:
            return current
        try:
            repaired = await Runner.run(
                goal_schema_repair_agent,
                input=_build_goal_schema_repair_prompt(prompt, current, violations),
                max_steps=2,
            )
            repaired_payload = _parse_agent_json(repaired.final_output)
        except Exception:
            return current
        if not isinstance(repaired_payload, dict):
            return current
        current = repaired_payload
    remaining = _find_goal_schema_key_violations(current)
    blocking_remaining = [
        item for item in remaining
        if item.get("category") in {"splice_isoform_objective", "binding_feature_region"}
    ]
    if blocking_remaining:
        blocked = deepcopy(current)
        blocked["status"] = "need_clarification"
        blocked["questions"] = ([
            "Please specify the feature or region to target for the binding-only ASO design."
        ] if any(item.get("category") == "binding_feature_region" for item in blocking_remaining) else [
            "Please specify whether each splice isoform objective without an explicit transcript is a specific isoform, an aggregate isoform class, or an exon-only objective that should use the default transcript context."
        ])
        blocked["schema_repair_errors"] = blocking_remaining[:20]
        return blocked
    return current


def _normalize_requested_accessibility_provenance(
    structured_goal: Optional[Dict[str, Any]], request_text: Any,
) -> None:
    """Do not turn an inferred optional metric into a mandatory user obligation."""
    if not isinstance(structured_goal, dict):
        return
    quote = structured_goal.get("target_accessibility_request_quote")
    if structured_goal.get("target_accessibility") is True and isinstance(quote, str):
        quote = quote.strip()
        if quote and quote.casefold() in str(request_text or "").casefold():
            structured_goal["target_accessibility_request_quote"] = quote
            return
    structured_goal.pop("target_accessibility", None)
    structured_goal.pop("target_accessibility_request_quote", None)


def _normalize_intake_output(intake_out: Dict[str, Any], request_text: Any = "") -> Dict[str, Any]:
    if isinstance(intake_out, dict):
        _normalize_binding_site_schemas_in_intake(intake_out)
        structured_goal = intake_out.get("structured_goal") if isinstance(intake_out.get("structured_goal"), dict) else None
        _apply_region_overlap_hints_from_request_text(structured_goal, request_text)
    normalized = _apply_intake_guards(intake_out)
    _remove_unquoted_user_transcript_lock(normalized, request_text)
    structured_goal = normalized.get("structured_goal") if isinstance(normalized.get("structured_goal"), dict) else None
    if structured_goal is not None:
        _normalize_requested_accessibility_provenance(structured_goal, request_text)
        _normalize_binding_site_schemas_in_goal(structured_goal)
        _normalize_splice_isoform_objectives_in_goal(structured_goal)
        _normalize_isoform_scope_source_in_goal(structured_goal)
        _normalize_steric_targeting_policy_in_goal(structured_goal)
        _apply_explicit_transcript_lock_from_request_text(structured_goal, request_text)
        _apply_region_overlap_hints_from_request_text(structured_goal, request_text)
        _normalize_region_constraints_in_goal(structured_goal)
        _normalize_design_programs_in_goal(structured_goal)
        _apply_requested_co_skip_events_from_text(structured_goal, request_text)
        _apply_explicit_transcript_lock_from_request_text(structured_goal, request_text)
        _normalize_design_programs_in_goal(structured_goal)
        _synthesize_default_gapmer_program_if_needed(structured_goal)
        _supplement_splice_context_from_exon_targets(structured_goal)
    _normalize_envelope_design_programs(normalized.get("request_envelope"))
    _normalize_envelope_user_transcript_locks(normalized.get("request_envelope"), request_text)
    return normalized


_BINDING_CONSTRAINT_REPAIR_ALLOWED_FIELDS = {
    "minimum_overlap_bp",
    "intent",
    "target_region",
    "flanks",
    "target_scope",
    "run_splice_router",
    "run_splice_eval",
    "aso_overlap_requirement",
    "rbp_binding",
    "rbp_region_operator",
    "mirna_binding",
    "motif_tiling",
    "region_constraints",
}


def _binding_constraint_repair_enabled() -> bool:
    raw = str(os.environ.get("ASO_BINDING_CONSTRAINT_REPAIR", "1")).strip().lower()
    return raw not in {"0", "false", "no", "off", "disabled"}


def _goal_has_binding_execution_scope(structured_goal: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    intent = str(structured_goal.get("intent") or "").strip().lower()
    if intent == "binding":
        return True
    target_region = _normalize_target_region(structured_goal.get("target_region"))
    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return True
    for program in _iter_design_programs(structured_goal):
        program_intent = str(program.get("intent") or "").strip().lower()
        if program_intent == "binding":
            return True
        program_region = _normalize_target_region(program.get("target_region"))
        if program_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
            return True
    return False


def _compact_binding_constraint_repair_intake(intake_out: Dict[str, Any]) -> Dict[str, Any]:
    compact: Dict[str, Any] = {"status": intake_out.get("status")}
    if intake_out.get("questions"):
        compact["questions"] = deepcopy(intake_out.get("questions"))
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out.get("structured_goal"), dict) else {}
    goal_subset: Dict[str, Any] = {}
    for field in (
        "gene_symbol",
        "gene_id",
        "species",
        "target_context",
        "intent",
        "target_region",
        "flanks",
        "target_scope",
        "transcript_id",
        "transcript_lock",
        "run_splice_router",
        "run_splice_eval",
        "aso_overlap_requirement",
        "rbp_binding",
        "mirna_binding",
        "motif_tiling",
        "binding_site_tiling",
        "target_features",
        "region_constraints",
        "objective",
        "notes",
    ):
        value = structured_goal.get(field)
        if value not in (None, "", [], {}):
            goal_subset[field] = deepcopy(value)
    programs: List[Dict[str, Any]] = []
    for program in _iter_design_programs(structured_goal):
        program_subset: Dict[str, Any] = {}
        for field in (
            "program_id",
            "transcript_id",
            "transcript_ids",
            "isoform_label",
            "start",
            "end",
            "coordinate_space",
            "coordinate_convention",
            "label",
            "modality",
            "intent",
            "objective",
            "target_region",
            "flanks",
            "targeting_policy",
            "run_splice_router",
            "run_splice_eval",
            "rbp_binding",
            "mirna_binding",
            "motif_tiling",
            "binding_site_tiling",
            "target_features",
            "region_constraints",
            "notes",
        ):
            value = program.get(field)
            if value not in (None, "", [], {}):
                program_subset[field] = deepcopy(value)
        if program_subset:
            programs.append(program_subset)
    if programs:
        goal_subset["design_programs"] = programs
    if goal_subset:
        compact["structured_goal"] = goal_subset
    return compact


def _build_binding_constraint_repair_prompt(prompt: str, intake_out: Dict[str, Any]) -> str:
    current = json.dumps(
        _compact_binding_constraint_repair_intake(intake_out),
        ensure_ascii=False,
        sort_keys=True,
        default=str,
    )
    return (
        "Validate whether the parsed ASO structured goal omitted executable binding-site constraints.\n\n"
        "Original intake prompt:\n"
        f"{prompt}\n\n"
        "Current normalized intake JSON:\n"
        f"{current}\n\n"
        "If the original prompt explicitly requests a feature region (UTR, coding sequence, or translation start), a numeric mature-RNA window, supported RBP/eCLIP/ENCODE or miRNA/TargetScan sites, or a concrete motif that is missing or malformed in the current goal, return an updated structured_goal_patch using only allowed fields. Relative upstream/downstream distances belong in flanks. Absolute mature-RNA positions belong in reference-bound cdna region_constraints with normalized BED0 bounds; absolute positions must not become flanks. Preserve an allowed outer window and a required covered feature as separate intersected constraints. Do not infer genomic coordinates. Use any_overlap plus minimum_overlap_bp for a minimum partial overlap.\n"
        "Otherwise return {\"status\":\"no_change\"}."
    )


def _binding_constraint_repair_schema() -> Dict[str, Any]:
    from aso_agents.goal_contract import canonical_structured_goal_schema
    fields = canonical_structured_goal_schema()['properties']
    patch = {'type':'object', 'properties':{
        key:deepcopy(fields[key]) for key in _BINDING_CONSTRAINT_REPAIR_ALLOWED_FIELDS if key in fields},
        'additionalProperties':False}
    # A repair is a partial source request, before canonical normalization.
    # Existing source objects may carry their overlap rule inside the source;
    # require the rule there or at the outer level, validating the same enum.
    constraint = patch['properties']['region_constraints']['items']
    constraint['required'] = []
    constraint.setdefault('allOf', []).append({'anyOf':[
        {'required':['aso_overlap_requirement']},
        *[{'required':[key], 'properties':{key:{'required':['aso_overlap_requirement']}}}
          for key in ('rbp_binding', 'mirna_binding', 'motif_tiling')],
    ]})
    patch['properties']['rbp_region_operator'] = {'type':'string','enum':['union','intersect']}
    return {'type':'object','properties':{
        'status':{'type':'string','enum':['no_change','updated','repair','patched']},
        'structured_goal_patch':patch,'ready_after_repair':{'type':'boolean'}},
        'required':['status'],'additionalProperties':False}


def _merge_binding_constraint_repair(
    intake_out: Dict[str, Any],
    repair_out: Dict[str, Any],
) -> Dict[str, Any]:
    if not isinstance(intake_out, dict) or not isinstance(repair_out, dict):
        return intake_out
    if str(repair_out.get("status") or "").strip().lower() not in {"updated", "repair", "patched"}:
        return intake_out
    patch = repair_out.get("structured_goal_patch")
    if not isinstance(patch, dict):
        return intake_out
    from aso_agents.pipeline_tools import _json_schema_validation_errors
    errors = _json_schema_validation_errors(repair_out, _binding_constraint_repair_schema())
    if errors:
        raise ValueError('binding_constraint_repair_contract_invalid: ' + '; '.join(errors))

    merged = deepcopy(intake_out)
    structured_goal = merged.get("structured_goal")
    if not isinstance(structured_goal, dict):
        structured_goal = {}
        merged["structured_goal"] = structured_goal

    for field in _BINDING_CONSTRAINT_REPAIR_ALLOWED_FIELDS:
        if field not in patch:
            continue
        value = patch.get(field)
        if value in (None, "", [], {}):
            continue
        if field == "region_constraints":
            existing = structured_goal.get("region_constraints")
            constraints = list(existing) if isinstance(existing, list) else []
            seen = {
                json.dumps(item, sort_keys=True, default=str)
                for item in constraints
                if isinstance(item, dict)
            }
            for item in value if isinstance(value, list) else [value]:
                if not isinstance(item, dict):
                    continue
                fingerprint = json.dumps(item, sort_keys=True, default=str)
                if fingerprint in seen:
                    continue
                constraints.append(deepcopy(item))
                seen.add(fingerprint)
            if constraints:
                structured_goal["region_constraints"] = constraints
            continue
        if field == "flanks":
            if not isinstance(value, dict):
                continue
            window = {
                key: numeric for key in ("up", "down")
                if (numeric := _coerce_nonnegative_int(value.get(key))) is not None
            }
            if window:
                structured_goal[field] = window
            continue
        structured_goal[field] = deepcopy(value)

    # A single explicit binding program is the same physical target as its
    # parent goal. Keep its executable scope aligned with the repaired goal;
    # multi-program requests can have different regions and are never copied.
    programs = structured_goal.get("design_programs")
    if isinstance(programs, list) and len(programs) == 1 and isinstance(programs[0], dict):
        program = programs[0]
        if (str(program.get("intent") or structured_goal.get("intent") or "").strip().lower() == "binding"
                and str(program.get("targeting_policy") or "").strip().lower() == "explicit_user_region"):
            if not _normalize_target_region(program.get("target_region")):
                region = _normalize_target_region(structured_goal.get("target_region"))
                if region:
                    program["target_region"] = region
            if not isinstance(program.get("flanks"), dict) and isinstance(structured_goal.get("flanks"), dict):
                program["flanks"] = deepcopy(structured_goal["flanks"])

    if (
        str(merged.get("status") or "").strip().lower() != "ready"
        and structured_goal
        and _coerce_bool(repair_out.get("ready_after_repair")) is True
    ):
        merged["status"] = "ready"
        merged.pop("questions", None)
        merged.pop("reason", None)
    return _normalize_intake_output(merged)


async def _repair_binding_site_constraints_if_needed(prompt: str, intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if not _binding_constraint_repair_enabled():
        return intake_out
    structured_goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not _goal_has_binding_execution_scope(structured_goal):
        return intake_out
    try:
        from aso_agents.pipeline_tools import _run_schema_validated_agent_once, _agent_with_strict_output_schema
        schema = _binding_constraint_repair_schema()
        agent = _agent_with_strict_output_schema(binding_site_constraint_repair_agent,
            schema_name='aso_binding_constraint_patch', schema=schema)
        repair_out = await _run_schema_validated_agent_once(
            agent=agent, prompt=_build_binding_constraint_repair_prompt(prompt, intake_out),
            schema=schema, error_prefix='binding_constraint_repair')
    except Exception:
        return intake_out
    return _merge_binding_constraint_repair(intake_out, repair_out)


async def _recover_explicit_physical_site_scope(prompt: str, intake_out: Dict[str, Any]) -> Dict[str, Any]:
    """Recover a quoted location restriction as an executable design field."""
    goal = intake_out.get("structured_goal") if isinstance(intake_out, dict) else None
    if not isinstance(goal, dict):
        return intake_out
    programs = goal.get("design_programs")
    if not isinstance(programs, list) or not programs or not all(isinstance(p, dict) for p in programs):
        return intake_out
    if any(_normalize_target_region(p.get("target_region")) for p in programs):
        return intake_out
    if len(programs) > 1:
        # Intake may duplicate one panel objective into per-molecule programs.
        # A global site restriction applies to every copy only when the copies
        # have the same objective and no separately declared physical site.
        # Distinct tasks and independently scoped programs remain untouched.
        signatures = {
            tuple(str(p.get(key) or "").strip().casefold() for key in
                  ("objective", "target_type", "modality", "intent", "gene_symbol", "species", "transcript_id"))
            for p in programs
        }
        if len(signatures) != 1 or any(p.get("region_constraints") for p in programs):
            return intake_out
    try:
        response = await Runner.run(physical_site_scope_agent, input=prompt, max_steps=2)
        finding = _parse_agent_json(response.final_output)
    except Exception:
        return intake_out
    feature = _normalize_target_region(finding.get("feature_region"))
    quote = str(finding.get("evidence_quote") or "").strip()
    if feature not in {"cds", "utr5", "utr3", "utrs", "translation_start"}:
        return intake_out
    if not quote or quote.casefold() not in prompt.casefold():
        return intake_out
    existing = _normalize_target_region(goal.get("target_region"))
    if existing and existing != feature:
        return intake_out
    result = deepcopy(intake_out)
    repaired_goal = result["structured_goal"]
    repaired_goal["target_region"] = feature
    for program in repaired_goal["design_programs"]:
        program["target_region"] = feature
    return _normalize_intake_output(result, request_text=prompt)


def _goal_intake_runtime_capabilities() -> List[Dict[str, str]]:
    """Declare resolver boundaries that do not require user-authored facts."""

    return canonical_resolution_capability_catalog()


def _goal_intake_clarification_review_schema(question_count: int) -> Dict[str, Any]:
    bounded_count = max(0, int(question_count))
    index_items: Dict[str, Any] = {"type": "integer"}
    if bounded_count:
        index_items["minimum"] = 0
        index_items["maximum"] = bounded_count - 1
    return {
        "type": "object",
        "properties": {
            "blocking_question_indexes": {
                "type": "array",
                "maxItems": bounded_count,
                "uniqueItems": True,
                "items": index_items,
            },
            "additional_blocking_questions": {
                "type": "array",
                "maxItems": 8,
                "items": {
                    "type": "object",
                    "properties": {
                        "missing_field": {"type": "string", "minLength": 1},
                        "question": {"type": "string", "minLength": 1},
                        "reason": {"type": "string", "minLength": 1},
                    },
                    "required": ["missing_field", "question", "reason"],
                    "additionalProperties": False,
                },
            },
            "reason": {"type": ["string", "null"]},
        },
        "required": [
            "blocking_question_indexes",
            "additional_blocking_questions",
            "reason",
        ],
        "additionalProperties": False,
    }


async def _review_goal_intake_clarifications_if_needed(
    prompt: str,
    intake_out: Dict[str, Any],
) -> Dict[str, Any]:
    if not isinstance(intake_out, dict):
        return intake_out
    intake_status = str(intake_out.get("status") or "").strip().lower()
    if intake_status not in {"ready", "need_clarification"}:
        return intake_out
    raw_questions = intake_out.get("questions")
    questions = (
        [str(item).strip() for item in raw_questions if str(item).strip()]
        if isinstance(raw_questions, list)
        else []
    )
    review_prompt = json.dumps(
        {
            "request_evidence": str(prompt or ""),
            "current_intake": _compact_binding_constraint_repair_intake(intake_out),
            "declared_platform_capabilities": _goal_intake_runtime_capabilities(),
            "proposed_questions": [
                {"question_index": index, "question": question}
                for index, question in enumerate(questions)
            ],
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )
    review_schema = _goal_intake_clarification_review_schema(len(questions))
    review_agent = Agent(
        name=goal_intake_clarification_review_agent.name,
        instructions=goal_intake_clarification_review_agent.instructions,
        tools=goal_intake_clarification_review_agent.tools,
        model=goal_intake_clarification_review_agent.model,
        log_tool_calls=goal_intake_clarification_review_agent.log_tool_calls,
        model_settings=dataclass_replace(
            goal_intake_clarification_review_agent.model_settings,
            extra_body=strict_json_text_format(
                "aso_goal_intake_clarification_review",
                review_schema,
            ),
        ),
    )
    try:
        review = await Runner.run(
            review_agent,
            input=review_prompt,
            max_steps=2,
        )
        reviewed = _parse_agent_json(review.final_output)
    except Exception:
        return intake_out
    raw_indexes = reviewed.get("blocking_question_indexes")
    if not isinstance(raw_indexes, list):
        return intake_out
    raw_additional = reviewed.get("additional_blocking_questions", [])
    if not isinstance(raw_additional, list):
        return intake_out
    retained_indexes = {
        item
        for item in raw_indexes
        if isinstance(item, int)
        and not isinstance(item, bool)
        and 0 <= item < len(questions)
    }
    filtered = deepcopy(intake_out)
    retained = [
        question for index, question in enumerate(questions) if index in retained_indexes
    ]
    additional: List[str] = []
    for item in raw_additional:
        if not isinstance(item, dict):
            return intake_out
        missing_field = str(item.get("missing_field") or "").strip()
        question = str(item.get("question") or "").strip()
        item_reason = str(item.get("reason") or "").strip()
        if not missing_field or not question or not item_reason:
            return intake_out
        additional.append(question)
    complete_questions: List[str] = []
    seen_questions: set[str] = set()
    for question in retained + additional:
        normalized_question = question.strip().casefold()
        if not normalized_question or normalized_question in seen_questions:
            continue
        seen_questions.add(normalized_question)
        complete_questions.append(question)
    if complete_questions:
        filtered["status"] = "need_clarification"
        filtered["questions"] = complete_questions
        reason = str(reviewed.get("reason") or "").strip()
        if reason:
            filtered["reason"] = reason
        return filtered
    if not isinstance(filtered.get("structured_goal"), dict) or not filtered["structured_goal"]:
        return intake_out
    filtered["status"] = "ready"
    filtered["questions"] = []
    filtered.pop("reason", None)
    return filtered


def _repair_binding_site_constraints_sync(prompt: str, intake_out: Dict[str, Any]) -> Dict[str, Any]:
    if not provider_credentials_available():
        return intake_out
    try:
        return asyncio.run(_repair_binding_site_constraints_if_needed(prompt, intake_out))
    except RuntimeError:
        loop = asyncio.new_event_loop()
        try:
            return loop.run_until_complete(_repair_binding_site_constraints_if_needed(prompt, intake_out))
        except Exception:
            return intake_out
        finally:
            loop.close()
    except Exception:
        return intake_out


async def _run_goal_intake_agent_once(prompt: str) -> Dict[str, Any]:
    intake = await Runner.run(goal_intake_agent, input=prompt, max_steps=4)
    raw_payload = _parse_agent_json(intake.final_output)
    repaired_payload = await _repair_goal_schema_if_needed(prompt, raw_payload)
    normalized = _normalize_intake_output(repaired_payload, request_text=prompt)
    repaired = await _repair_binding_site_constraints_if_needed(prompt, normalized)
    repaired = await _recover_explicit_physical_site_scope(prompt, repaired)
    reviewed = await _review_goal_intake_clarifications_if_needed(prompt, repaired)
    return _normalize_intake_output(reviewed, request_text=prompt)


def _quoted_request_obligation(item: Any, source_text: str) -> bool:
    if not isinstance(item, dict):
        return False
    quote = item.get("quote")
    return isinstance(quote, str) and bool(quote.strip()) and quote.strip().casefold() in source_text.casefold()


def _quoted_translation_window(value: Any, source_text: str) -> Optional[Dict[str, Any]]:
    """Accept relative start-codon offsets only with a matching user quote."""
    if not _quoted_request_obligation(value, source_text):
        return None
    if _normalize_target_region(value.get("feature")) != "translation_start":
        return None
    upstream = _coerce_nonnegative_int(value.get("upstream_nt"))
    downstream = _coerce_nonnegative_int(value.get("downstream_nt"))
    if upstream is None or downstream is None:
        return None
    quote = str(value["quote"])
    numbers = set()
    digits = ""
    for character in quote + " ":
        if character.isdigit():
            digits += character
        elif digits:
            numbers.add(int(digits))
            digits = ""
    if upstream not in numbers or downstream not in numbers:
        return None
    return {"up": upstream, "down": downstream, "request_quote": quote}


def _remove_unattested_absolute_start_windows(goal: Dict[str, Any], source_text: str) -> bool:
    """Do not treat model-supplied genomic coordinates as user intervals.

    A request-relative feature window is resolved from the annotated transcript.
    Absolute interval rows survive when their endpoints are present in the
    user's text, or when a separate source is declared for those coordinates.
    """
    refs = goal.get("artifact_refs")
    if isinstance(refs, list) and any(
        not isinstance(ref, dict)
        or str(ref.get("artifact_type") or "").strip().lower()
            not in {"reference_annotation", "reference_genome", "transcript_annotation"}
        for ref in refs
    ):
        return False
    source = source_text.replace(",", "").casefold()

    def attested(start: Any, end: Any, chrom: Any) -> bool:
        try:
            left, right = int(start), int(end)
        except (TypeError, ValueError):
            return False
        chromosome = str(chrom or "").casefold().removeprefix("chr")
        return bool(chromosome and ("chr" + chromosome in source or chromosome + ":" in source)
                    and (str(left) in source or str(left + 1) in source)
                    and str(right) in source)

    changed = False
    for container in [goal, *(item for item in goal.get("design_programs") or [] if isinstance(item, dict))]:
        constraints = container.get("region_constraints")
        if not isinstance(constraints, list):
            continue
        retained = []
        for constraint in constraints:
            if not isinstance(constraint, dict):
                retained.append(constraint)
                continue
            intervals = constraint.get("intervals_bed0_half_open")
            source_kind = str(constraint.get("source") or "").casefold()
            if (constraint.get("source_type") != "explicit_rows"
                    or constraint.get("coordinate_space") != "genomic"
                    or source_kind not in {"", "user_request"}
                    or not isinstance(intervals, list) or not intervals):
                retained.append(constraint)
                continue
            if any(isinstance(row, dict) and attested(row.get("start"), row.get("end"), row.get("chrom"))
                   for row in intervals):
                retained.append(constraint)
            else:
                changed = True
        if len(retained) != len(constraints):
            if retained:
                container["region_constraints"] = retained
            else:
                container.pop("region_constraints", None)
    targets = goal.get("evaluation_targets")
    if isinstance(targets, list):
        for target in targets:
            if not isinstance(target, dict) or target.get("target_type") != "region":
                continue
            if attested(target.get("start"), target.get("end"), target.get("chrom")):
                continue
            for field in ("chrom", "start", "end", "strand", "position"):
                if field in target:
                    target.pop(field)
                    changed = True
    return changed


def _remove_unattested_splice_windows_for_start(goal: Dict[str, Any], source_text: str) -> bool:
    """Discard inferred splice anchors when a quoted AUG window owns the target.

    A splice-relative interval is a distinct biological feature. Keep one only
    when its own request quote is present in the user's evidence; an annotation
    artifact or a model-authored label is not evidence that the user requested
    an exon boundary. This leaves explicitly requested combined constraints
    intact while letting the annotated translation start define the window.
    """
    if _normalize_target_region(goal.get("target_region")) != "translation_start":
        return False
    changed = False
    for container in [goal, *(item for item in goal.get("design_programs") or [] if isinstance(item, dict))]:
        constraints = container.get("region_constraints")
        if not isinstance(constraints, list):
            continue
        retained = []
        for constraint in constraints:
            if not isinstance(constraint, dict) or constraint.get("source_type") != "splice_relative_window":
                retained.append(constraint)
                continue
            quote = next((constraint.get(field) for field in ("request_quote", "quote", "source_quote")
                          if isinstance(constraint.get(field), str) and constraint[field].strip()), None)
            if quote and quote.strip().casefold() in source_text.casefold():
                retained.append(constraint)
            else:
                changed = True
        if len(retained) != len(constraints):
            if retained:
                container["region_constraints"] = retained
            else:
                container.pop("region_constraints", None)
    return changed


def _reconcile_redundant_inline_observations(
    rows: List[Dict[str, Any]], expected: int, request_text: str,
) -> Optional[List[Dict[str, Any]]]:
    """Remove only parser copies disproved by a quoted user count.

    Equal molecules can be intentionally repeated. Preserve file rows and any
    repeated molecule whose sequence is repeated in the original request.
    Failure to reach the attested count leaves all observations untouched.
    """
    if expected < 1 or expected >= len(rows):
        return None
    result = deepcopy(rows)
    identity_fields = ("name", "sequence", "chemistry", "platform", "notes")
    text = str(request_text or "").upper()
    while len(result) > expected:
        removable = None
        for index in range(len(result) - 1, -1, -1):
            row = result[index]
            if not isinstance(row, dict) or row.get("source_file") or row.get("source_row"):
                continue
            sequence = str(row.get("sequence") or "").upper()
            if not sequence:
                continue
            key = tuple(row.get(field) for field in identity_fields)
            matches = [i for i, item in enumerate(result)
                       if isinstance(item, dict) and not item.get("source_file")
                       and tuple(item.get(field) for field in identity_fields) == key]
            if len(matches) > max(1, text.count(sequence)) and matches[0] != index:
                removable = (index, matches[0])
                break
        if removable is None:
            return None
        duplicate_index, source_index = removable
        duplicate = result.pop(duplicate_index)
        if source_index > duplicate_index:
            source_index -= 1
        result[source_index].setdefault("input_reconciliation", []).append({
            "kind": "parser_duplicate_inline_observation",
            "basis": "identical parsed identity exceeds both the user-attested count and literal request occurrences",
            "parsed_row": duplicate,
        })
    return result


async def _audit_supplied_observation_count(
    intake_out: Dict[str, Any], user_request: str, qa_history: List[Dict[str, str]],
) -> Dict[str, Any]:
    """Use independent quoted evidence only when a parsed inline row repeats."""
    envelope = intake_out.get("request_envelope")
    tasks = envelope.get("tasks") if isinstance(envelope, dict) else None
    if not isinstance(tasks, list) or len(tasks) != 1 or not isinstance(tasks[0], dict):
        return intake_out
    task = tasks[0]
    if str(task.get("task_type") or "").strip().lower() != "evaluate_existing_aso_set":
        return intake_out
    context = task.get("context")
    rows = context.get("provided_asos") if isinstance(context, dict) else None
    if not isinstance(rows, list) or len(rows) < 2:
        return intake_out
    identity_fields = ("name", "sequence", "chemistry", "platform", "notes")
    identities = [json.dumps([row.get(field) for field in identity_fields], sort_keys=True, default=str)
                  for row in rows if isinstance(row, dict) and not row.get("source_file")]
    if len(identities) == len(set(identities)):
        return intake_out
    from aso_agents.request_obligation_agent import request_obligation_agent
    prompt = json.dumps({"task_type": "evaluate_existing_aso_set", "original_request": user_request,
                         "clarification_history": qa_history}, ensure_ascii=False)
    try:
        response = await Runner.run(request_obligation_agent, input=prompt, max_steps=4)
        audit = _parse_agent_json(response.final_output)
    except Exception as exc:
        intake_out["supplied_observation_audit"] = {"status": "unavailable", "error_type": type(exc).__name__}
        return intake_out
    count = audit.get("supplied_observation_count") if isinstance(audit, dict) else None
    source_text = "\n".join([user_request, *(str(item.get("answer") or "") for item in qa_history
                                                  if isinstance(item, dict))])
    number = _coerce_positive_int(count.get("count")) if _quoted_request_obligation(count, source_text) else None
    reconciled = (_reconcile_redundant_inline_observations(rows, number, user_request)
                  if number is not None else None)
    if reconciled is not None:
        context["provided_asos"] = reconciled
    intake_out["supplied_observation_audit"] = {
        "status": "reconciled" if reconciled is not None else "unresolved",
        "attested_count": number, "parsed_count": len(rows),
        "retained_count": len(reconciled) if reconciled is not None else len(rows),
        "quote": count.get("quote") if number is not None else None,
    }
    return intake_out


async def _audit_request_obligations(
    intake_out: Dict[str, Any], user_request: str, qa_history: List[Dict[str, str]],
) -> Dict[str, Any]:
    """Reconcile executable constraints against independent, quoted user evidence."""
    if not isinstance(intake_out, dict) or intake_out.get("status") != "ready":
        return intake_out
    goal = intake_out.get("structured_goal")
    if not isinstance(goal, dict):
        return intake_out
    envelope = intake_out.get("request_envelope")
    if isinstance(envelope, dict):
        tasks = envelope.get("tasks")
        design_tasks = [task for task in tasks or [] if isinstance(task, dict)
                        and str(task.get("task_type") or "").strip().lower() == "design_new_asos"]
        # Supporting analysis/report tasks do not create additional design
        # scopes. A global design obligation still has exactly one recipient.
        if isinstance(tasks, list) and tasks and len(design_tasks) != 1:
            return await _audit_supplied_observation_count(intake_out, user_request, qa_history)
    elif not isinstance(goal.get("design_programs"), list):
        return intake_out
    from aso_agents.request_obligation_agent import request_obligation_agent
    answers = [str(item.get("answer") or "") for item in qa_history if isinstance(item, dict)]
    source_text = "\n".join([user_request, *answers])
    prompt = json.dumps({"original_request": user_request, "clarification_history": qa_history}, ensure_ascii=False)
    try:
        response = await Runner.run(request_obligation_agent, input=prompt, max_steps=4)
        audit = _parse_agent_json(response.final_output)
    except Exception as exc:
        intake_out["request_obligation_audit"] = {"status": "unavailable", "error_type": type(exc).__name__}
        _normalize_requested_accessibility_provenance(goal, source_text)
        return intake_out
    if not isinstance(audit, dict):
        intake_out["request_obligation_audit"] = {"status": "invalid_response"}
        _normalize_requested_accessibility_provenance(goal, source_text)
        return intake_out

    from aso_agents.request_evidence_repair import repair_audit_quotes
    audit, quote_repair = await repair_audit_quotes(
        audit, source_text, {'original_request': user_request, 'clarification_history': qa_history},
        Runner.run, _parse_agent_json)
    if quote_repair['status'] == 'unresolved':
        intake_out['status'] = 'need_clarification'
        intake_out['questions'] = ['Please restate the design requirement whose supporting text could not be verified.']
        intake_out['request_obligation_audit'] = {'status': 'unresolved', 'quote_repair': quote_repair}
        _normalize_requested_accessibility_provenance(goal, source_text)
        return intake_out

    synchronized_fields = {"target_accessibility", "target_accessibility_request_quote"}
    count = audit.get("candidate_count")
    per_site = audit.get('per_site_count')
    per_site_valid = (isinstance(per_site, dict) and _quoted_request_obligation(per_site, source_text)
                      and _coerce_positive_int(per_site.get('count'))
                      and per_site.get('kind') in {'exact', 'minimum', 'maximum'})
    if _quoted_request_obligation(count, source_text):
        number = _coerce_positive_int(count.get("count"))
        scope = count.get("scope")
        kind = count.get("kind")
        if number and scope == "global" and kind in {"exact", "minimum", "maximum"}:
            synchronized_fields.update({"candidate_minimum", "candidate_limit",
                                        "candidate_limit_per_site", "min_asos_per_site"})
            if kind != "maximum":
                goal["candidate_minimum"] = number
            if kind in {"exact", "maximum"}:
                goal["candidate_limit"] = number
            else:
                goal.pop("candidate_limit", None)
            if not per_site_valid:
                goal.pop("candidate_limit_per_site", None)
                goal.pop("min_asos_per_site", None)
        elif number and scope == "per_site" and kind in {"exact", "minimum"}:
            synchronized_fields.update({"candidate_limit_per_site", "min_asos_per_site"})
            goal["min_asos_per_site"] = number
            if kind == 'exact':
                goal["candidate_limit_per_site"] = number
            else:
                goal.pop('candidate_limit_per_site', None)

    if per_site_valid:
        number = int(per_site['count'])
        synchronized_fields.update({'candidate_limit_per_site', 'min_asos_per_site'})
        if per_site['kind'] != 'maximum':
            goal['min_asos_per_site'] = number
        if per_site['kind'] != 'minimum':
            goal['candidate_limit_per_site'] = number
        else:
            goal.pop('candidate_limit_per_site', None)

    feature = audit.get("target_feature")
    if _quoted_request_obligation(feature, source_text) and feature.get("applies_to_all_candidates") is True:
        region = _normalize_target_region(feature.get("feature"))
        if region in {"cds", "utr3", "utr5", "utrs", "translation_start"}:
            synchronized_fields.add("target_region")
            goal["target_region"] = region
            for program in goal.get("design_programs") or []:
                if isinstance(program, dict):
                    program["target_region"] = region

    window = _quoted_translation_window(audit.get("target_window"), source_text)
    if window and goal.get("target_region") == "translation_start":
        synchronized_fields.update({"flanks", "region_constraints", "evaluation_targets", "design_programs"})
        goal["flanks"] = {"up": window["up"], "down": window["down"]}
        for program in goal.get("design_programs") or []:
            if isinstance(program, dict) and _normalize_target_region(program.get("target_region")) == "translation_start":
                program["flanks"] = deepcopy(goal["flanks"])
        _remove_unattested_absolute_start_windows(goal, source_text)
        _remove_unattested_splice_windows_for_start(goal, source_text)

    accessibility = audit.get("target_accessibility")
    if _quoted_request_obligation(accessibility, source_text) and accessibility.get("required") is True:
        goal["target_accessibility"] = True
        goal["target_accessibility_request_quote"] = accessibility["quote"].strip()
    else:
        goal.pop("target_accessibility", None)
        goal.pop("target_accessibility_request_quote", None)

    diversity = audit.get("candidate_site_diversity")
    if _quoted_request_obligation(diversity, source_text) and diversity.get("required") is True:
        synchronized_fields.add("candidate_selection_policy")
        if diversity.get("hard_nonoverlap") is True:
            goal["candidate_selection_policy"] = "nonoverlapping_target_sites"
        elif goal.get("candidate_selection_policy") != "nonoverlapping_target_sites":
            goal["candidate_selection_policy"] = "diverse_target_sites"

    spacing = audit.get("candidate_genomic_spacing")
    if (_quoted_request_obligation(spacing, source_text)
            and spacing.get("applies_to_all_candidates") is True
            and type(spacing.get("minimum_gap_nt")) is int
            and spacing["minimum_gap_nt"] >= 0):
        synchronized_fields.update({"candidate_minimum_genomic_gap_nt", "candidate_selection_policy"})
        goal["candidate_minimum_genomic_gap_nt"] = spacing["minimum_gap_nt"]
        goal["candidate_selection_policy"] = "nonoverlapping_target_sites"

    events = []
    for event in audit.get("conditional_exon_skip_events") or []:
        if not _quoted_request_obligation(event, source_text):
            continue
        exon = _coerce_positive_int(event.get("exon_label"))
        if exon is None:
            continue
        transcript_id = event.get("transcript_id")
        events.append({"exon_label": exon,
                       "transcript_id": str(transcript_id).strip() if transcript_id else None,
                       "request_quote": event["quote"].strip()})
    if events:
        synchronized_fields.add("conditional_exon_skip_events")
        goal["conditional_exon_skip_events"] = events
    from aso_agents.quoted_program_obligations import apply_program_obligations
    program_obligations = apply_program_obligations(goal, audit, source_text)
    if program_obligations['status'] == 'applied':
        synchronized_fields.add('design_programs')
    elif program_obligations['status'] == 'unresolved':
        intake_out['status'] = 'need_clarification'
        intake_out['questions'] = [
            'Please identify which design program or transcript set each requested count or binding constraint applies to.'
        ]
    _normalize_design_programs_in_goal(goal)
    if "design_programs" in intake_out and "design_programs" in goal:
        intake_out["design_programs"] = deepcopy(goal["design_programs"])
    for field in synchronized_fields:
        if field in goal:
            intake_out[field] = deepcopy(goal[field])
        else:
            intake_out.pop(field, None)
    envelope = intake_out.get("request_envelope")
    tasks = envelope.get("tasks") if isinstance(envelope, dict) else None
    design_tasks = [task for task in tasks or [] if isinstance(task, dict)
                    and str(task.get("task_type") or "").strip().lower() == "design_new_asos"]
    if len(design_tasks) == 1:
        task = design_tasks[0]
        context = task.get("context") if isinstance(task.get("context"), dict) else None
        containers = [envelope, envelope.get("default_context"), task, context,
                      context.get("structured_goal") if isinstance(context, dict) else None]
        for container in containers:
            if not isinstance(container, dict):
                continue
            for field in synchronized_fields:
                if field in goal:
                    container[field] = deepcopy(goal[field])
                else:
                    container.pop(field, None)
            if "target_region" in synchronized_fields and goal.get("target_region") in {"cds", "utr3", "utr5", "utrs", "translation_start"}:
                for program in container.get("design_programs") or []:
                    if isinstance(program, dict):
                        program["target_region"] = goal["target_region"]
            _normalize_design_programs_in_goal(container)
    intake_out["request_obligation_audit"] = {
        "status": "unresolved" if program_obligations['status'] == 'unresolved' else "accepted",
        "candidate_count": count if _quoted_request_obligation(count, source_text) else None,
        "per_site_count": per_site if per_site_valid else None,
        "candidate_site_diversity": diversity if _quoted_request_obligation(diversity, source_text) else None,
        "candidate_genomic_spacing": spacing if _quoted_request_obligation(spacing, source_text) else None,
        "target_feature": feature if _quoted_request_obligation(feature, source_text) else None,
        "target_window": window,
        "target_accessibility": accessibility if _quoted_request_obligation(accessibility, source_text) else None,
        "conditional_exon_skip_events": events,
        "program_obligations": program_obligations,
        "quote_repair": quote_repair,
    }
    return intake_out


def _coerce_positive_int(value: Any) -> Optional[int]:
    """Best-effort conversion of mixed inputs (e.g., '15 nt') into a positive integer."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            num = int(round(float(value)))
        except Exception:
            return None
        return num if num > 0 else None
    text = str(value).strip()
    if not text:
        return None
    digits: List[str] = []
    for ch in text:
        if ch.isdigit():
            digits.append(ch)
        elif digits:
            break
    if not digits:
        return None
    candidate = int("".join(digits))
    return candidate if candidate > 0 else None


def _normalize_exon_label_collection(value: Any) -> List[int]:
    from aso_agents.feature_identity import exon_number
    values = value if isinstance(value, list) else [value]
    normalized: List[int] = []
    seen: Set[int] = set()
    for item in values:
        exon_label = exon_number(item)
        if exon_label is None or exon_label in seen:
            continue
        seen.add(exon_label)
        normalized.append(exon_label)
    return normalized


def _coerce_standard_exon_constraint_label(value: Any) -> Optional[int]:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            parsed = int(round(float(value)))
        except Exception:
            return None
        return parsed if parsed > 0 else None
    text = str(value).strip()
    if not text:
        return None
    if re.search(r"\d+[A-Za-z]", text):
        return None
    match = re.search(r"\bexons?\s*#?\s*(\d+)\b", text, flags=re.IGNORECASE)
    if not match and re.fullmatch(r"#?\s*(\d+)(?:\s*\([^)]*\))?", text):
        match = re.search(r"\d+", text)
    if not match:
        return None
    try:
        parsed = int(match.group(1) if match.lastindex else match.group(0))
    except Exception:
        return None
    return parsed if parsed > 0 else None


def _region_constraint_exon_label(entry: Dict[str, Any]) -> Optional[int]:
    if not isinstance(entry, dict):
        return None
    containers = [entry]
    for nested_key in ("region", "target_region", "region_definition", "target"):
        nested = entry.get(nested_key)
        if isinstance(nested, dict):
            containers.append(nested)
    for container in containers:
        for key in (
            "exon_label",
            "target_exon",
            "exon",
            "exon_number",
            "exon_index",
            "target_exon_label",
        ):
            exon_label = _coerce_standard_exon_constraint_label(container.get(key))
            if exon_label is not None:
                return exon_label
    return None


def _is_exon_region_constraint_hint(source_type_hint: str) -> bool:
    hint = str(source_type_hint or "").strip().lower().replace("-", "_").replace(" ", "_")
    return hint in {
        "exon",
        "exons",
        "target_exon",
        "target_exons",
        "transcript_exon",
        "exon_region",
        "exonic_region",
        "exon_constraint",
    }


def _normalize_region_coordinate_space(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "genome": "genomic",
        "genomic_dna": "genomic",
        "dna": "genomic",
        "bed": "genomic",
        "premrna": "genomic",
        "pre_mrna": "genomic",
        "transcript": "cdna",
        "transcriptome": "cdna",
        "rna": "cdna",
        "mrna": "cdna",
        "mature_mrna": "cdna",
        "spliced_transcript": "cdna",
        "cdna_space": "cdna",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"genomic", "cdna"} else ""


def _normalize_constraint_rows_payload(
    rows: Any, *, coordinate_space: str, coordinate_convention: Optional[str] = None,
) -> List[List[Any]]:
    normalized: List[List[Any]] = []
    for idx, row in enumerate(rows if isinstance(rows, list) else [], start=1):
        if isinstance(row, list):
            if len(row) < 3:
                continue
            try:
                start0 = int(row[1])
                end_val = int(row[2])
                if coordinate_convention == "one_based_inclusive":
                    start0 -= 1
            except Exception:
                continue
            if start0 < 0 or end_val <= start0:
                continue
            chrom_val = str(row[0] or "").strip()
            if not chrom_val:
                continue
            label_val = str(row[3] or f"{coordinate_space}_region_{idx}") if len(row) > 3 else f"{coordinate_space}_region_{idx}"
            score_val = row[4] if len(row) > 4 else 0
            strand_val = row[5] if len(row) > 5 else "."
            normalized.append([chrom_val, start0, end_val, label_val, score_val, strand_val])
            continue
        if not isinstance(row, dict):
            continue
        chrom_val = row.get("chrom")
        if chrom_val is None:
            chrom_val = row.get("transcript_id") or row.get("isoform_label") or row.get("name")
        chrom_text = str(chrom_val or "").strip()
        if not chrom_text:
            continue
        start0_raw = row.get("start0")
        if start0_raw is None and row.get("start") is not None:
            try:
                start0_raw = max(0, int(row.get("start")) - 1)
            except Exception:
                start0_raw = None
        end_raw = row.get("end")
        try:
            start0 = int(start0_raw)
            end_val = int(end_raw)
        except Exception:
            continue
        if end_val <= start0:
            continue
        label_val = str(
            row.get("label")
            or row.get("name")
            or row.get("id")
            or f"{coordinate_space}_region_{idx}"
        ).strip()
        score_val = row.get("score", 0)
        strand_val = row.get("strand", ".")
        normalized.append([chrom_text, start0, end_val, label_val, score_val, strand_val])
    return normalized


def _normalize_region_rows(rows: Any) -> List[List[Any]]:
    return _normalize_constraint_rows_payload(rows, coordinate_space="genomic")


def _dedupe_region_rows(rows: Any) -> List[List[Any]]:
    deduped: List[List[Any]] = []
    seen: Set[Tuple[str, int, int, str]] = set()
    for row in _normalize_region_rows(rows):
        strand = str(row[5] or ".").strip() if len(row) > 5 else "."
        key = (str(row[0] or "").strip(), int(row[1]), int(row[2]), strand)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(row)
    return deduped


def _canonicalize_overlap_keys(request: Dict[str, Any]) -> Optional[str]:
    if not isinstance(request, dict):
        return None
    overlap_requirement = _normalize_aso_overlap_requirement(
        request.get("aso_overlap_requirement")
        or request.get("overlap_requirement")
        or request.get("tile_overlap_requirement")
        or request.get("overlap_rule")
    )
    for alias in ("overlap_requirement", "tile_overlap_requirement", "overlap_rule"):
        request.pop(alias, None)
    if overlap_requirement:
        request["aso_overlap_requirement"] = overlap_requirement
    else:
        request.pop("aso_overlap_requirement", None)
    return overlap_requirement


def _normalize_splice_anchor_site(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "3ss": "acceptor",
        "3_splice_site": "acceptor",
        "three_prime_splice_site": "acceptor",
        "acceptor_site": "acceptor",
        "splice_acceptor": "acceptor",
        "5ss": "donor",
        "5_splice_site": "donor",
        "five_prime_splice_site": "donor",
        "donor_site": "donor",
        "splice_donor": "donor",
    }
    text = aliases.get(text, text)
    return text if text in {"acceptor", "donor"} else ""


def _coerce_relative_offset(value: Any) -> Optional[int]:
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    try:
        return int(value)
    except Exception:
        pass
    text = str(value).strip().lower()
    if not text:
        return None
    text = text.replace("nt", "").replace("bp", "").strip()
    match = re.search(r"[+-]?\d+", text)
    if not match:
        return None
    try:
        return int(match.group(0))
    except Exception:
        return None


def _coerce_relative_range(value: Any) -> Optional[Tuple[int, int]]:
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        start = _coerce_relative_offset(value[0])
        end = _coerce_relative_offset(value[1])
        if start is not None and end is not None:
            return (start, end) if start <= end else (end, start)
    if isinstance(value, dict):
        start = _coerce_relative_offset(
            value.get("start")
            or value.get("start_nt")
            or value.get("relative_start_nt")
            or value.get("from_nt")
        )
        end = _coerce_relative_offset(
            value.get("end")
            or value.get("end_nt")
            or value.get("relative_end_nt")
            or value.get("to_nt")
        )
        if start is not None and end is not None:
            return (start, end) if start <= end else (end, start)
    text = str(value or "").strip().lower()
    if text:
        nums = [_coerce_relative_offset(match.group(0)) for match in re.finditer(r"[+-]?\d+", text)]
        nums = [num for num in nums if num is not None]
        if len(nums) >= 2:
            start, end = int(nums[0]), int(nums[1])
            return (start, end) if start <= end else (end, start)
    return None


def _nested_dict_value(*objects: Any, keys: Tuple[str, ...]) -> Any:
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        for key in keys:
            value = obj.get(key)
            if value not in (None, "", [], {}):
                return value
    return None


def _splice_relative_window_from_mapping(entry: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(entry, dict):
        return None
    motif_entry = entry.get("motif_tiling") if isinstance(entry.get("motif_tiling"), dict) else {}
    window = None
    for key in (
        "splice_relative_window",
        "relative_splice_window",
        "relative_window",
        "splice_window",
        "junction_window",
        "window",
        "fallback_window",
        "region_hint",
    ):
        if isinstance(entry.get(key), dict):
            window = dict(entry.get(key) or {})
            break
        if isinstance(motif_entry, dict) and isinstance(motif_entry.get(key), dict):
            window = dict(motif_entry.get(key) or {})
            break
    if window is None:
        window = {}

    anchor = (
        window.get("relative_to")
        if isinstance(window.get("relative_to"), dict)
        else window.get("anchor")
        if isinstance(window.get("anchor"), dict)
        else entry.get("relative_to")
        if isinstance(entry.get("relative_to"), dict)
        else entry.get("anchor")
        if isinstance(entry.get("anchor"), dict)
        else motif_entry.get("relative_to")
        if isinstance(motif_entry, dict) and isinstance(motif_entry.get("relative_to"), dict)
        else motif_entry.get("anchor")
        if isinstance(motif_entry, dict) and isinstance(motif_entry.get("anchor"), dict)
        else {}
    )
    if not isinstance(anchor, dict):
        anchor = {}

    site = _normalize_splice_anchor_site(
        _nested_dict_value(
            window,
            anchor,
            motif_entry,
            entry,
            keys=("splice_site", "site", "anchor_site", "junction_site", "site_kind"),
        )
    )
    exon_label = _coerce_standard_exon_constraint_label(
        _nested_dict_value(
            window,
            anchor,
            motif_entry,
            entry,
            keys=("exon_label", "junction_exon_label", "target_exon", "exon", "exon_number"),
        )
    )
    transcript_id = str(
        _nested_dict_value(
            window,
            anchor,
            motif_entry,
            entry,
            keys=(
                "reference_transcript_id",
                "exon_numbering_transcript_id",
                "transcript_id",
                "isoform_transcript_id",
            ),
        )
        or ""
    ).strip()

    rel_start = _coerce_relative_offset(
        _nested_dict_value(
            window,
            entry,
            keys=(
                "relative_start_nt",
                "start_relative_to_splice_site_nt",
                "start_offset_nt",
                "offset_start_nt",
            ),
        )
    )
    rel_end = _coerce_relative_offset(
        _nested_dict_value(
            window,
            entry,
            keys=(
                "relative_end_nt",
                "end_relative_to_splice_site_nt",
                "end_offset_nt",
                "offset_end_nt",
            ),
        )
    )

    if rel_start is None or rel_end is None:
        upstream_nt = _coerce_positive_int(
        _nested_dict_value(window, motif_entry, entry, keys=("upstream_nt", "upstream_bases", "upstream_bp"))
        )
        downstream_nt = _coerce_positive_int(
            _nested_dict_value(window, motif_entry, entry, keys=("downstream_nt", "downstream_bases", "downstream_bp"))
        )
        if upstream_nt is not None or downstream_nt is not None:
            rel_start = -(upstream_nt or 0)
            rel_end = max(0, (downstream_nt or 0) - 1)

    if rel_start is None or rel_end is None:
        donor_downstream_range = _coerce_relative_range(
            _nested_dict_value(window, motif_entry, entry, keys=("intron_downstream_range_nt", "downstream_intron_range_nt"))
        )
        donor_downstream_nt = _coerce_positive_int(
            _nested_dict_value(window, motif_entry, entry, keys=("downstream_intron_nt", "intron_downstream_nt"))
        )
        donor_start = _coerce_relative_offset(
            _nested_dict_value(
                window,
                motif_entry,
                entry,
                keys=("downstream_intron_start_relative_to_donor", "donor_downstream_start_nt"),
            )
        )
        if donor_downstream_range is not None:
            site = site or "donor"
            rel_start, rel_end = donor_downstream_range
        elif donor_downstream_nt is not None and (site == "donor" or donor_start is not None):
            site = site or "donor"
            rel_start = donor_start if donor_start is not None else 1
            rel_end = rel_start + donor_downstream_nt - 1

    if rel_start is None or rel_end is None:
        acceptor_upstream_range = _coerce_relative_range(
            _nested_dict_value(window, motif_entry, entry, keys=("intron_upstream_range_nt", "upstream_intron_range_nt"))
        )
        acceptor_upstream_nt = _coerce_positive_int(
            _nested_dict_value(window, motif_entry, entry, keys=("upstream_intron_nt", "intron_upstream_nt"))
        )
        exon_downstream_nt = _coerce_positive_int(
            _nested_dict_value(
                window,
                motif_entry,
                entry,
                keys=("downstream_exon_nt", "exon_downstream_nt", "first_exon_nt", "exon_nt"),
            )
        )
        if acceptor_upstream_range is not None:
            site = site or "acceptor"
            upstream_min, upstream_max = acceptor_upstream_range
            rel_start = -max(abs(upstream_min), abs(upstream_max))
            rel_end = -min(abs(upstream_min), abs(upstream_max))
        elif acceptor_upstream_nt is not None and (site == "acceptor" or exon_downstream_nt is not None):
            site = site or "acceptor"
            rel_start = -acceptor_upstream_nt
            rel_end = max(0, (exon_downstream_nt or 1) - 1)

    if rel_start is None or rel_end is None:
        exon_upstream_nt = _coerce_positive_int(
            _nested_dict_value(
                window,
                motif_entry,
                entry,
                keys=("upstream_exon_nt", "exon_upstream_nt", "last_exon_nt", "exon_nt"),
            )
        )
        intron_downstream_nt = _coerce_positive_int(
            _nested_dict_value(window, motif_entry, entry, keys=("downstream_intron_nt", "intron_downstream_nt"))
        )
        if exon_upstream_nt is not None and (site == "donor" or intron_downstream_nt is not None):
            site = site or "donor"
            rel_start = -(exon_upstream_nt - 1)
            rel_end = intron_downstream_nt or 0

    if not site or exon_label is None or rel_start is None or rel_end is None:
        return None
    if rel_start > rel_end:
        rel_start, rel_end = rel_end, rel_start

    normalized = {
        "exon_label": exon_label,
        "anchor_site": site,
        "relative_start_nt": int(rel_start),
        "relative_end_nt": int(rel_end),
    }
    if transcript_id:
        normalized["reference_transcript_id"] = transcript_id
    if (
        window.get("feature_name")
        or entry.get("motif_name")
        or window.get("motif_name")
        or motif_entry.get("motif_name")
        or entry.get("name")
    ):
        motif_name = str(
            window.get("feature_name")
            or entry.get("motif_name")
            or window.get("motif_name")
            or motif_entry.get("motif_name")
            or entry.get("name")
            or ""
        ).strip()
        if motif_name:
            normalized["feature_name"] = motif_name
    return normalized


def _splice_relative_window_from_constraint_text(entry: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(entry, dict):
        return None
    text = " ".join(
        str(entry.get(key) or "")
        for key in ("label", "name", "notes", "description", "objective")
    )
    if not text.strip():
        return None
    lowered = text.lower()
    exon_label = _coerce_standard_exon_constraint_label(entry.get("exon_label"))
    if exon_label is None:
        exon_match = re.search(r"\bexon\s*([0-9]+)\b", lowered, flags=re.IGNORECASE)
        if exon_match:
            exon_label = _coerce_standard_exon_constraint_label(exon_match.group(1))
    if exon_label is None:
        return None

    site = ""
    rel_start: Optional[int] = None
    rel_end: Optional[int] = None
    acceptor = re.search(
        r"(?P<up>\d+)\s*(?:nt|bp)?\s+upstream(?:\s+in\s+intron)?(?:.*?)first\s+(?P<down>\d+)\s*(?:nt|bp)?\s+(?:of\s+)?exon",
        lowered,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not acceptor:
        acceptor = re.search(
            r"\bacceptor\b[^.;]{0,180}?\bfrom\s+(?P<up>\d+)\s*(?:nt|bp)?\s+upstream\s+of\s+(?:the\s+)?"
            r"(?:exon\s+[0-9]+(?:\s+\w+)?\s+)?(?:start|acceptor)(?:[^.;]{0,120}?)\bthrough\s+"
            r"(?P<down>\d+)\s*(?:nt|bp)?\s+(?:into|within|inside)\s+(?:the\s+)?(?:exon\b|exon\s+[0-9]+)",
            lowered,
            flags=re.IGNORECASE | re.DOTALL,
        )
    if not acceptor:
        acceptor = re.search(
            r"\bacceptor\b[^.;]{0,180}?(?P<up>\d+)\s*(?:nt|bp)?\s+upstream\s+of\s+(?:the\s+)?"
            r"(?:exon\s+[0-9]+(?:\s+\w+)?\s+)?(?:start|acceptor)(?:[^.;]{0,120}?)"
            r"(?P<down>\d+)\s*(?:nt|bp)?\s+(?:into|within|inside)\s+(?:the\s+)?(?:exon\b|exon\s+[0-9]+)",
            lowered,
            flags=re.IGNORECASE | re.DOTALL,
        )
    if acceptor or "acceptor" in lowered:
        if acceptor:
            site = "acceptor"
            rel_start = -int(acceptor.group("up"))
            rel_end = int(acceptor.group("down")) - 1

    donor = re.search(
        r"last\s+(?P<up>\d+)\s*(?:nt|bp)?\s+(?:of\s+)?exon(?:.*?)"
        r"(?P<down>\d+)\s*(?:nt|bp)?\s+downstream(?:\s+into\s+intron|\s+in\s+intron)?",
        lowered,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not donor:
        donor = re.search(
            r"\bdonor\b[^.;]{0,180}?\bfrom\s+(?P<up>\d+)\s*(?:nt|bp)?\s+upstream\s+of\s+(?:the\s+)?"
            r"(?:exon\s+[0-9]+(?:\s+\w+)?\s+)?(?:end|donor)(?:[^.;]{0,120}?)\bthrough\s+"
            r"(?P<down>\d+)\s*(?:nt|bp)?\s+downstream",
            lowered,
            flags=re.IGNORECASE | re.DOTALL,
        )
    if not donor:
        donor = re.search(
            r"\bdonor\b[^.;]{0,180}?(?P<up>\d+)\s*(?:nt|bp)?\s+upstream\s+of\s+(?:the\s+)?"
            r"(?:exon\s+[0-9]+(?:\s+\w+)?\s+)?(?:end|donor)(?:[^.;]{0,120}?)"
            r"(?P<down>\d+)\s*(?:nt|bp)?\s+downstream",
            lowered,
            flags=re.IGNORECASE | re.DOTALL,
        )
    if donor:
        site = "donor"
        rel_start = -(int(donor.group("up")) - 1)
        rel_end = int(donor.group("down"))
    elif "donor" in lowered and rel_start is None:
        donor_plus = re.search(
            r"donor\s*\+?\s*(?P<start>\d+)\s*(?:\.{2,}|to|-)\s*\+?\s*(?P<end>\d+)",
            lowered,
            flags=re.IGNORECASE,
        )
        if not donor_plus:
            donor_plus = re.search(
                r"(?:iss[-\s]?n1|silencer|enhancer|motif)[^.;]{0,180}?(?:from\s+)?\+?(?P<start>\d+)\s*"
                r"(?:\.{2,}|to|-)\s*\+?(?P<end>\d+)\s*(?:nt|bp)?\s+downstream\s+of\s+(?:the\s+)?"
                r"(?:exon\s+[0-9]+(?:\s+\w+)?\s+)?donor",
                lowered,
                flags=re.IGNORECASE | re.DOTALL,
            )
        if donor_plus:
            site = "donor"
            rel_start = int(donor_plus.group("start"))
            rel_end = int(donor_plus.group("end"))

    if not site:
        site = "acceptor" if "acceptor" in lowered else "donor" if "donor" in lowered else ""
    if not site or rel_start is None or rel_end is None:
        return None
    transcript_id = str(
        entry.get("reference_transcript_id")
        or entry.get("exon_numbering_transcript_id")
        or entry.get("transcript_id")
        or ""
    ).strip()
    normalized = {
        "exon_label": exon_label,
        "anchor_site": site,
        "relative_start_nt": int(rel_start),
        "relative_end_nt": int(rel_end),
    }
    if transcript_id:
        normalized["reference_transcript_id"] = transcript_id
    feature_candidates: List[str] = []
    for pattern in (
        r"\b([A-Za-z][A-Za-z0-9]*-[A-Za-z0-9-]+)\b[^.;]{0,100}\b(?:motif|silencer|enhancer)\b",
        r"\b(?:motif|silencer|enhancer)\b[^.;]{0,100}\b([A-Za-z][A-Za-z0-9]*-[A-Za-z0-9-]+)\b",
    ):
        for feature_match in re.finditer(pattern, text, flags=re.IGNORECASE):
            feature_candidates.append(str(feature_match.group(1) or "").strip())
    ignored_feature_names = {
        "splice-site",
        "donor-proximal",
        "acceptor-proximal",
        "full-length",
    }
    feature_candidates = [
        item
        for item in feature_candidates
        if item and item.lower() not in ignored_feature_names
    ]
    if feature_candidates:
        feature_candidates.sort(
            key=lambda item: (
                not bool(re.search(r"\d", item)),
                item.lower(),
            )
        )
        normalized["feature_name"] = feature_candidates[0]
    elif any(token in lowered for token in ("motif", "silencer", "enhancer", "regulatory")):
        normalized["feature_name"] = "named_regulatory_site"
    return normalized


def _normalize_region_constraints(
    value: Any, *, context: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    from aso_agents.region_overlap import normalize_constraint_operator
    if not isinstance(value, list):
        return []
    normalized: List[Dict[str, Any]] = []
    for idx, entry in enumerate(value, start=1):
        if not isinstance(entry, dict):
            continue
        window = entry.get("splice_relative_window")
        if (isinstance(window, dict) and isinstance(context, dict)
                and not any(obj.get(key) not in (None, "", [], {})
                            for obj in (window, entry)
                            for key in ("exon_label", "junction_exon_label", "target_exon", "exon", "exon_number"))):
            # A typed relative window can inherit its containing scope's one
            # explicit exon. Do not infer a window from an outcome, prose or
            # sibling program, and do not choose among multiple exon labels.
            labels = list(context.get("exon_labels") or []) if isinstance(context.get("exon_labels"), list) else []
            if context.get("exon_label") not in (None, "", [], {}):
                labels.append(context["exon_label"])
            resolved = [_coerce_standard_exon_constraint_label(label) for label in labels]
            if resolved and all(label is not None for label in resolved) and len(set(resolved)) == 1:
                entry = deepcopy(entry)
                entry["splice_relative_window"]["exon_label"] = resolved[0]
        norm: Dict[str, Any] = {}
        constraint_id = str(entry.get("constraint_id") or entry.get("id") or f"constraint_{idx:02d}").strip()
        norm["constraint_id"] = constraint_id
        label = str(entry.get("label") or entry.get("name") or entry.get("constraint_name") or constraint_id).strip()
        if label:
            norm["label"] = label
        operator = normalize_constraint_operator(entry.get("operator") or entry.get("region_operator"))
        if operator:
            norm["operator"] = operator
        overlap_requirement = _normalize_aso_overlap_requirement(
            entry.get("aso_overlap_requirement")
            or entry.get("overlap_requirement")
            or entry.get("tile_overlap_requirement")
        )

        source_type = ""
        source_type_hint = str(
            entry.get("source_type")
            or entry.get("constraint_type")
            or entry.get("constraint_kind")
            or entry.get("source")
            or entry.get("type")
            or entry.get("kind")
            or ""
        ).strip().lower().replace("-", "_").replace(" ", "_")
        rows_payload: Any = None
        interval_rows_payload = None
        for interval_key in (
            "intervals_bed0_half_open",
            "bed_intervals",
            "bed0_intervals",
            "genomic_intervals",
            "intervals",
        ):
            if isinstance(entry.get(interval_key), list):
                interval_rows_payload = deepcopy(entry.get(interval_key))
                break
        coordinate_space = _normalize_region_coordinate_space(entry.get("coordinate_space"))
        splice_relative_window = _splice_relative_window_from_mapping(entry)
        if not splice_relative_window:
            splice_relative_window = _splice_relative_window_from_constraint_text(entry)
        rbp_binding = entry.get("rbp_binding")
        motif_tiling = entry.get("motif_tiling")
        mirna_binding = entry.get("mirna_binding") or entry.get("miRNA_binding")
        if source_type_hint in {"transcript_feature", "reference_feature"}:
            from aso_agents.transcript_features import normalize_feature_name
            if interval_rows_payload is not None or entry.get("rows") is not None:
                raise ValueError("transcript_feature_conflicting_explicit_intervals")
            source_type = "transcript_feature"
            coordinate_space = "cdna"
            norm["feature_name"] = normalize_feature_name(entry.get("feature_name"))
            for key in ("reference_transcript_id", "transcript_id", "isoform_label"):
                if entry.get(key):
                    norm[key] = deepcopy(entry[key])
        elif source_type_hint in {
            "user_provided_bed_intervals",
            "user_provided_intervals",
            "explicit_bed_intervals",
            "explicit_intervals",
            "bed_intervals",
            "bed",
            "user_bed",
            "genomic_interval_set",
            "interval_set",
            "genomic_intervals",
            "intervals",
        } or (interval_rows_payload is not None and not any(isinstance(entry.get(key), dict) for key in ("rbp_binding", "mirna_binding", "miRNA_binding", "motif_tiling"))):
            source_type = "explicit_rows"
            # BED describes the interval convention, not its reference space.
            # Preserve an explicit transcript coordinate contract across intake
            # normalization and late binding repairs.
            coordinate_space = coordinate_space or "genomic"
        elif (
            source_type_hint
            in {
                "splice_relative_window",
                "relative_splice_window",
                "splice_window",
                "junction_window",
                "relative_window",
                "donor_window",
                "acceptor_window",
            }
            and splice_relative_window
        ):
            source_type = "splice_relative_window"
            norm["splice_relative_window"] = splice_relative_window
            if splice_relative_window.get("exon_label") is not None:
                norm["exon_label"] = splice_relative_window.get("exon_label")
                if splice_relative_window.get("reference_transcript_id"):
                    norm["exon_numbering_transcript_id"] = splice_relative_window.get("reference_transcript_id")
                for key in ("reference_transcript_id", "transcript_id", "exon_numbering_transcript_id"):
                    if entry.get(key) not in (None, "", [], {}) and norm.get(key) is None:
                        norm[key] = deepcopy(entry.get(key))
                overlap_requirement = overlap_requirement or (
                    "any_overlap" if splice_relative_window.get("feature_name") else "full_containment"
                )
        elif source_type_hint in {"rbp_binding", "rbp", "encode_rbp", "eclip"} or isinstance(rbp_binding, dict) or isinstance(entry.get("rbp"), str):
            source_type = "rbp_binding"
            request = dict(rbp_binding) if isinstance(rbp_binding, dict) else {}
            if isinstance(entry.get("rbp"), str) and not request.get("rbp"):
                request["rbp"] = str(entry.get("rbp")).strip()
            if entry.get("assay") is not None and request.get("assay") is None:
                request["assay"] = entry.get("assay")
            if entry.get("biosample_hint") is not None and request.get("biosample_hint") is None:
                request["biosample_hint"] = entry.get("biosample_hint")
            nested_overlap = _canonicalize_overlap_keys(request)
            overlap_requirement = overlap_requirement or nested_overlap
            if request.get("rbp"):
                norm["rbp_binding"] = request
            else:
                source_type = ""
        elif (
            isinstance(mirna_binding, dict)
            or entry.get("mirnas") is not None
            or entry.get("miRNAs") is not None
            or entry.get("mirna_family_or_id") is not None
            or entry.get("miRNA_family_or_id") is not None
            or source_type_hint in {"mirna_binding", "targetscan_mirna", "mirna", "targetscan"}
        ):
            source_type = "mirna_binding"
            request = dict(mirna_binding) if isinstance(mirna_binding, dict) else {}
            for key in (
                "mirnas",
                "miRNAs",
                "mirna_family_or_id",
                "miRNA_family_or_id",
                "source",
                "database",
                "target_level",
                "operator",
                "max_sites",
                "transcript_id",
                "species_taxon_id",
                "release",
                "include_nonconserved",
                "min_pct",
                "site_types",
            ):
                if entry.get(key) is not None and request.get(key) is None:
                    request[key] = deepcopy(entry.get(key))
            nested_overlap = _canonicalize_overlap_keys(request)
            overlap_requirement = overlap_requirement or nested_overlap or "any_overlap"
            normalized_request = _normalize_mirna_binding_request(request, {})
            if isinstance(normalized_request, dict):
                _canonicalize_overlap_keys(normalized_request)
            if normalized_request:
                norm["mirna_binding"] = normalized_request
            else:
                source_type = ""
        elif isinstance(motif_tiling, dict) or entry.get("motifs") is not None:
            request = dict(motif_tiling) if isinstance(motif_tiling, dict) else {}
            motif_probe = {"motif_tiling": deepcopy(request)}
            if entry.get("motifs") is not None and request.get("motifs") is None:
                motif_probe["motif_tiling"]["motifs"] = deepcopy(entry.get("motifs"))
            motif_request = _extract_motif_tiling_request(motif_probe)
            if splice_relative_window and not motif_request:
                source_type = "splice_relative_window"
                norm["splice_relative_window"] = splice_relative_window
                if splice_relative_window.get("exon_label") is not None:
                    norm["exon_label"] = splice_relative_window.get("exon_label")
                if splice_relative_window.get("reference_transcript_id"):
                    norm["exon_numbering_transcript_id"] = splice_relative_window.get("reference_transcript_id")
                overlap_requirement = overlap_requirement or "any_overlap"
            else:
                source_type = "motif_tiling"
                request = dict(motif_tiling) if isinstance(motif_tiling, dict) else {}
                if entry.get("motifs") is not None and request.get("motifs") is None:
                    request["motifs"] = deepcopy(entry.get("motifs"))
                if entry.get("target_level") is not None and request.get("target_level") is None:
                    request["target_level"] = entry.get("target_level")
                if entry.get("operator") is not None and request.get("operator") is None:
                    request["operator"] = entry.get("operator")
                if entry.get("max_hits") is not None and request.get("max_hits") is None:
                    request["max_hits"] = entry.get("max_hits")
                if entry.get("strand_mode") is not None and request.get("strand_mode") is None:
                    request["strand_mode"] = entry.get("strand_mode")
                nested_overlap = _canonicalize_overlap_keys(request)
                overlap_requirement = overlap_requirement or nested_overlap
                norm["motif_tiling"] = request
        else:
            exon_label = _region_constraint_exon_label(entry)
            # A canonical nested splice-relative window is self-identifying: its
            # anchor, exon, and offsets provide the execution schema without a
            # redundant outer source_type or exon_label. Binding-source payloads
            # have already been handled above, so retaining it here cannot turn a
            # supported RBP/miRNA/motif request into a plain relative window.
            if splice_relative_window:
                source_type = "splice_relative_window"
                norm["splice_relative_window"] = splice_relative_window
                if splice_relative_window.get("exon_label") is not None:
                    norm["exon_label"] = splice_relative_window.get("exon_label")
                if splice_relative_window.get("reference_transcript_id"):
                    norm["exon_numbering_transcript_id"] = splice_relative_window.get("reference_transcript_id")
                overlap_requirement = overlap_requirement or (
                    "any_overlap" if splice_relative_window.get("feature_name") else "full_containment"
                )
            elif _is_exon_region_constraint_hint(source_type_hint) or exon_label is not None:
                source_type = "exon"
                if exon_label is not None:
                    norm["exon_label"] = exon_label
                else:
                    source_type = ""
                for key in (
                    "transcript_id",
                    "exon_numbering_transcript_id",
                    "isoform_label",
                    "gene_symbol",
                ):
                    if entry.get(key) not in (None, "", [], {}):
                        norm[key] = deepcopy(entry.get(key))
                overlap_requirement = overlap_requirement or "full_containment"
            elif entry.get("genomic_rows") is not None:
                source_type = "explicit_rows"
                coordinate_space = "genomic"
                rows_payload = entry.get("genomic_rows")
            elif entry.get("cdna_rows") is not None:
                source_type = "explicit_rows"
                coordinate_space = "cdna"
                rows_payload = entry.get("cdna_rows")
            elif entry.get("rows") is not None:
                source_type = "explicit_rows"
                rows_payload = entry.get("rows")
            elif entry.get("bed_rows") is not None:
                source_type = "explicit_rows"
                rows_payload = entry.get("bed_rows")
        if not source_type:
            continue
        norm["source_type"] = source_type
        if overlap_requirement:
            norm["aso_overlap_requirement"] = overlap_requirement
            if source_type == "rbp_binding" and isinstance(norm.get("rbp_binding"), dict):
                norm["rbp_binding"] = dict(norm["rbp_binding"])
                norm["rbp_binding"]["aso_overlap_requirement"] = overlap_requirement
            if source_type == "motif_tiling" and isinstance(norm.get("motif_tiling"), dict):
                norm["motif_tiling"] = dict(norm["motif_tiling"])
                norm["motif_tiling"]["aso_overlap_requirement"] = overlap_requirement
            if source_type == "mirna_binding" and isinstance(norm.get("mirna_binding"), dict):
                norm["mirna_binding"] = dict(norm["mirna_binding"])
                norm["mirna_binding"]["aso_overlap_requirement"] = overlap_requirement
        if source_type == "explicit_rows":
            if not coordinate_space:
                coordinate_space = "genomic"
            rows_norm = _normalize_constraint_rows_payload(
                rows_payload, coordinate_space=coordinate_space,
                coordinate_convention=entry.get("coordinate_convention"),
            )
            if entry.get("coordinate_convention") == "one_based_inclusive":
                norm["coordinate_convention"] = "bed0_half_open"
            if not rows_norm and interval_rows_payload is None:
                continue
            norm["coordinate_space"] = coordinate_space
            if rows_norm:
                norm["rows"] = rows_norm
        elif coordinate_space:
            norm["coordinate_space"] = coordinate_space
        if interval_rows_payload is not None:
            norm["intervals_bed0_half_open"] = interval_rows_payload
        min_overlap = _coerce_positive_int(
            entry.get("min_overlap_bp")
            or entry.get("minimum_overlap_bp")
            or entry.get("min_overlap")
            or entry.get("minimum_overlap")
        )
        if min_overlap is not None:
            norm["minimum_overlap_bp"] = min_overlap
        for passthrough_key in (
            "allow_coordinate_conversion",
            "strand",
            "genome_build",
            "coordinate_convention",
            "score",
            "source",
        ):
            if passthrough_key not in norm and entry.get(passthrough_key) not in (None, "", [], {}):
                norm[passthrough_key] = deepcopy(entry.get(passthrough_key))
        if entry.get("notes") is not None:
            norm["notes"] = entry.get("notes")
        normalized.append(norm)
    return normalized


def _normalize_region_constraints_in_goal(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    binding_site_constraints = (
        structured_goal.get("binding_site_constraints")
        if isinstance(structured_goal.get("binding_site_constraints"), dict)
        else {}
    )
    default_overlap_requirement = _normalize_aso_overlap_requirement(
        structured_goal.get("aso_overlap_requirement")
        or structured_goal.get("overlap_requirement")
        or structured_goal.get("tile_overlap_requirement")
        or binding_site_constraints.get("aso_overlap_requirement")
        or binding_site_constraints.get("overlap_requirement")
        or binding_site_constraints.get("tile_overlap_requirement")
    )
    default_min_overlap_bp = _coerce_positive_int(
        structured_goal.get("minimum_overlap_bp")
        or structured_goal.get("min_overlap_bp")
        or binding_site_constraints.get("minimum_overlap_bp")
        or binding_site_constraints.get("min_overlap_bp")
        or binding_site_constraints.get("minimum_overlap")
    )
    if default_overlap_requirement:
        structured_goal["aso_overlap_requirement"] = default_overlap_requirement
    if default_min_overlap_bp is not None:
        structured_goal["minimum_overlap_bp"] = default_min_overlap_bp
    for alias in ("overlap_requirement", "tile_overlap_requirement", "min_overlap_bp", "min_overlap", "minimum_overlap"):
        structured_goal.pop(alias, None)
    if binding_site_constraints:
        structured_goal.pop("binding_site_constraints", None)
    def _empty_explicit_placeholder(entry: Dict[str, Any]) -> bool:
        return (
            entry.get("source_type") == "explicit_rows"
            and entry.get("intervals_bed0_half_open") == []
            and not entry.get("rows")
        )

    top_level = _normalize_region_constraints(structured_goal.get("region_constraints"), context=structured_goal)
    # The empty interval can be evidence for a typed-exon recovery when no
    # region was resolved. Once concrete region rows exist, it has no target
    # content and must not act as a second, empty filter over those rows.
    raw_programs = structured_goal.get("design_programs")
    programs_with_rows = (
        isinstance(raw_programs, list)
        and bool(raw_programs)
        and all(
            isinstance(program, dict) and bool(_normalize_region_rows(program.get("region_rows")))
            for program in raw_programs
        )
    )
    if _normalize_region_rows(structured_goal.get("region_rows")) or programs_with_rows:
        top_level = [entry for entry in top_level if not _empty_explicit_placeholder(entry)]
    if default_overlap_requirement:
        patched_top_level: List[Dict[str, Any]] = []
        for entry in top_level:
            if not isinstance(entry, dict):
                continue
            patched = dict(entry)
            if not _normalize_aso_overlap_requirement(patched.get("aso_overlap_requirement")):
                patched["aso_overlap_requirement"] = default_overlap_requirement
            entry_min_overlap = _coerce_positive_int(
                patched.get("minimum_overlap_bp")
                or patched.get("min_overlap_bp")
                or patched.get("min_overlap")
                or patched.get("minimum_overlap")
            )
            if entry_min_overlap is not None:
                patched["minimum_overlap_bp"] = entry_min_overlap
            if default_min_overlap_bp is not None and entry_min_overlap is None:
                patched["minimum_overlap_bp"] = default_min_overlap_bp
            for alias in ("min_overlap_bp", "min_overlap", "minimum_overlap", "overlap_requirement", "tile_overlap_requirement"):
                patched.pop(alias, None)
            if isinstance(patched.get("mirna_binding"), dict):
                patched["mirna_binding"] = dict(patched["mirna_binding"])
                _canonicalize_overlap_keys(patched["mirna_binding"])
                patched["mirna_binding"]["aso_overlap_requirement"] = patched["aso_overlap_requirement"]
            patched_top_level.append(patched)
        top_level = patched_top_level
    if top_level:
        structured_goal["region_constraints"] = top_level
    else:
        structured_goal.pop("region_constraints", None)

    if not isinstance(raw_programs, list):
        return
    for program in raw_programs:
        if not isinstance(program, dict):
            continue
        program_constraints = _normalize_region_constraints(program.get("region_constraints"), context=program)
        if _normalize_region_rows(program.get("region_rows")):
            program_constraints = [
                entry for entry in program_constraints if not _empty_explicit_placeholder(entry)
            ]
        program_overlap_requirement = _normalize_aso_overlap_requirement(
            program.get("aso_overlap_requirement")
            or program.get("overlap_requirement")
            or program.get("tile_overlap_requirement")
        ) or default_overlap_requirement
        for alias in (
            "aso_overlap_requirement",
            "overlap_requirement",
            "tile_overlap_requirement",
            "min_overlap_bp",
            "min_overlap",
            "minimum_overlap",
            "minimum_overlap_bp",
        ):
            program.pop(alias, None)
        if program_overlap_requirement:
            patched_program_constraints: List[Dict[str, Any]] = []
            for entry in program_constraints:
                if not isinstance(entry, dict):
                    continue
                patched = dict(entry)
                if not _normalize_aso_overlap_requirement(patched.get("aso_overlap_requirement")):
                    patched["aso_overlap_requirement"] = program_overlap_requirement
                entry_min_overlap = _coerce_positive_int(
                    patched.get("minimum_overlap_bp")
                    or patched.get("min_overlap_bp")
                    or patched.get("min_overlap")
                    or patched.get("minimum_overlap")
                )
                if entry_min_overlap is not None:
                    patched["minimum_overlap_bp"] = entry_min_overlap
                if default_min_overlap_bp is not None and entry_min_overlap is None:
                    patched["minimum_overlap_bp"] = default_min_overlap_bp
                for alias in ("min_overlap_bp", "min_overlap", "minimum_overlap", "overlap_requirement", "tile_overlap_requirement"):
                    patched.pop(alias, None)
                if isinstance(patched.get("mirna_binding"), dict):
                    patched["mirna_binding"] = dict(patched["mirna_binding"])
                    _canonicalize_overlap_keys(patched["mirna_binding"])
                    patched["mirna_binding"]["aso_overlap_requirement"] = patched["aso_overlap_requirement"]
                patched_program_constraints.append(patched)
            program_constraints = patched_program_constraints
        if program_constraints:
            program["region_constraints"] = program_constraints
        else:
            program.pop("region_constraints", None)


def _derive_tile_length_from_goal(goal: Optional[Dict[str, Any]], chemistry: Any) -> Optional[int]:
    """Infer the desired tiling length from user constraints or chemistry guidance."""

    def _gather(obj: Optional[Dict[str, Any]], keys: Tuple[str, ...]) -> List[Any]:
        if not isinstance(obj, dict):
            return []
        return [obj.get(key) for key in keys if key in obj]

    candidates: List[Any] = []
    if isinstance(goal, dict):
        candidates.extend(_gather(goal, ("tile_len", "tile_length")))
        candidates.extend(_gather(goal.get("constraints"), ("tile_len", "tile_length", "length_nt", "length", "aso_length")))
        candidates.extend(_gather(goal.get("parameter_constraints"), ("tile_len", "tile_length", "length_nt", "length")))
    if isinstance(chemistry, dict):
        candidates.append(chemistry.get("length"))
        recommendation = chemistry.get("recommendation")
        if isinstance(recommendation, dict):
            candidates.extend(
                _gather(
                    recommendation,
                    ("tile_len", "tile_length", "length", "length_nt", "recommended_length"),
                )
            )
    for value in candidates:
        length = _coerce_positive_int(value)
        if length is not None:
            return length
    return None


def _chemistry_mentions_steric(value: Any) -> bool:
    def _iter_strings(obj: Any) -> List[str]:
        if isinstance(obj, str):
            return [obj]
        if isinstance(obj, dict):
            strings: List[str] = []
            for key in ("chemistry", "CHEMISTRY", "platform", "mode", "name"):
                val = obj.get(key)
                if isinstance(val, str):
                    strings.append(val)
            recommendation = obj.get("recommendation")
            if isinstance(recommendation, dict):
                strings.extend(_iter_strings(recommendation))
            return strings
        if isinstance(obj, list):
            strings = []
            for item in obj:
                strings.extend(_iter_strings(item))
            return strings
        return []

    for text in _iter_strings(value):
        if "steric" in text.lower():
            return True
    return False


def _extract_chemistry_label(value: Any) -> Optional[str]:
    from aso_chemistry import require_native_linkage_identity
    require_native_linkage_identity(value)
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        direct = value.get("CHEMISTRY") or value.get("chemistry") or value.get("profile") or value.get("name")
        if isinstance(direct, str) and direct.strip():
            return direct
        recommendation = value.get("recommendation")
        if isinstance(recommendation, dict):
            return _extract_chemistry_label(recommendation)
    return None


def _normalize_chemistry_label(label: Optional[str], tile_len: Optional[int] = None) -> Optional[str]:
    from aso_chemistry import chemistry_label
    return chemistry_label(label)


def _chemistry_platform_for_label(label: Optional[str]) -> Optional[str]:
    from aso_chemistry import gapmer_architecture, STERIC_SUGARS
    normalized = _normalize_chemistry_label(label)
    if gapmer_architecture(normalized):
        return "gapmer"
    if normalized in STERIC_SUGARS:
        return "steric_blocker"
    return None


def _chemistry_length_for_label(label: Optional[str]) -> Optional[int]:
    from aso_chemistry import gapmer_architecture, STERIC_SUGARS
    normalized = _normalize_chemistry_label(label)
    architecture = gapmer_architecture(normalized)
    if architecture:
        return architecture.length
    if normalized in {*STERIC_SUGARS, "unspecified"}:
        return 20
    return None


def _normalize_requested_chemistry(value: Any) -> Optional[Dict[str, Any]]:
    from aso_chemistry import canonical_chemistry_configuration
    recommendation = canonical_chemistry_configuration(value)
    if not recommendation:
        return None
    payload = {"recommendation": recommendation}
    if isinstance(value, dict) and isinstance(value.get("chemical_requirements"), list):
        payload["chemical_requirements"] = deepcopy(value["chemical_requirements"])
    return payload


def _resolve_gapmer_chemistry(structured_goal: Optional[Dict[str, Any]], tile_len: Optional[int] = None) -> str:
    from aso_chemistry import require_native_linkage_identity
    require_native_linkage_identity(structured_goal, tile_len)
    if not isinstance(structured_goal, dict):
        structured_goal = {}
    if structured_goal.get("chemistry_policy") == "leave_unspecified":
        from aso_agents.pipeline_tools import _unselected_chemistry_payload
        _unselected_chemistry_payload(structured_goal)
        return "unspecified"
    raw_chemistry = structured_goal.get("chemistry")
    chem_label = _extract_chemistry_label(raw_chemistry)
    chem_label = _normalize_chemistry_label(chem_label, tile_len=tile_len)
    if not chem_label:
        constraints = structured_goal.get("constraints")
        if isinstance(constraints, dict):
            raw_chemistry = raw_chemistry or constraints.get("chemistry")
            chem_label = _normalize_chemistry_label(_extract_chemistry_label(raw_chemistry), tile_len=tile_len)
    if chem_label:
        from aso_chemistry import gapmer_architecture, require_modality_chemistry, require_chemistry_length
        if tile_len is not None:
            require_chemistry_length(chem_label, tile_len)
        if gapmer_architecture(chem_label):
            require_modality_chemistry("gapmer", chem_label)
        return chem_label
    if raw_chemistry:
        raise ValueError("Explicit chemistry is unresolved; preserve the request and resolve its architecture before tiling.")
    if tile_len == 16:
        return "3-10-3"
    if tile_len == 20:
        return "5-10-5"
    return "steric-hindrance"


def _variant_in_chemistry_gap(chemistry: str, position_1based: int) -> bool:
    from aso_chemistry import gapmer_architecture
    architecture = gapmer_architecture(chemistry)
    return bool(architecture and architecture.in_gap(position_1based))


def _apply_modification(n: str, mod_type: str = "2MOEr", p: int = 0, linker: str = "") -> str:
    if mod_type == "2MOEr":
        return f"/i2MOEr{n}/{linker}" if p == 0 else f"/{p}2MOEr{n}/{linker}"
    if mod_type == "iMe-dC":
        return f"/iMe-d{n}/{linker}" if p == 0 else f"/{p}iMe-d{n}/{linker}"
    raise ValueError(f"Modification type not recognized: {mod_type}")


def _apply_idt_configuration(aso: str, chemistry: str) -> str:
    """Encode the supported fully phosphorothioate MOE/DNA architectures."""
    if not aso:
        return ""
    from aso_chemistry import encode_idt_oligo
    return encode_idt_oligo(aso, chemistry)


def _format_idt_and_synthesis(seq: str, chemistry: str) -> Tuple[str, str, Optional[str]]:
    if not seq:
        return "", "", None
    synthesis = str(Seq(seq).reverse_complement())
    try:
        idt = _apply_idt_configuration(synthesis, chemistry)
        return idt, synthesis, None
    except Exception as exc:
        return "", synthesis, f"chemistry_failed:{chemistry}:{exc}"


def _should_skip_gapmer_tiling(structured_goal: Optional[Dict[str, Any]]) -> Tuple[bool, Optional[str]]:
    if not isinstance(structured_goal, dict):
        return False, None
    constraints = structured_goal.get("constraints")
    if isinstance(constraints, dict):
        if constraints.get("disallow_gapmers") is True:
            return True, "constraints.disallow_gapmers=true"
        if constraints.get("avoid_gapmers") is True:
            return True, "constraints.avoid_gapmers=true"
    if structured_goal.get("disallow_gapmers") is True:
        return True, "disallow_gapmers=true"
    if structured_goal.get("avoid_gapmers") is True:
        return True, "avoid_gapmers=true"
    return False, None


def _coerce_non_negative_int(value: Any) -> Optional[int]:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            num = int(round(float(value)))
        except Exception:
            return None
        return num if num >= 0 else None
    text = str(value).strip()
    if not text:
        return None
    word_values = {
        "zero": 0,
        "one": 1,
        "single": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
        "six": 6,
        "seven": 7,
        "eight": 8,
        "nine": 9,
        "ten": 10,
    }
    lowered = text.lower()
    if lowered in word_values:
        return word_values[lowered]
    digits: List[str] = []
    for ch in text.replace(",", ""):
        if ch.isdigit():
            digits.append(ch)
        elif digits:
            break
    if not digits:
        return None
    num = int("".join(digits))
    return num if num >= 0 else None


ALLOW_ALL_HOMOPOLYMER_MAX_RUN = 9_999_999


def _allows_homopolymer_runs(structured_goal: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(structured_goal, dict):
        return False

    def _check(block: Any) -> bool:
        if not isinstance(block, dict):
            return False
        for key in (
            "allow_homopolymer_runs",
            "allow_homopolymers",
            "allow_homopolymer",
            "allow_all_homopolymers",
        ):
            if _coerce_bool(block.get(key)) is True:
                return True
        return False

    if _check(structured_goal):
        return True
    constraints_block = structured_goal.get("constraints")
    if _check(constraints_block):
        return True
    return False


def _apply_allow_all_homopolymers(structured_goal: Optional[Dict[str, Any]], parameter_constraints: Optional[Dict[str, Any]] = None) -> None:
    if not isinstance(structured_goal, dict):
        return
    max_run = ALLOW_ALL_HOMOPOLYMER_MAX_RUN
    per_base_limits = {base: max_run for base in ("A", "C", "G", "T")}

    structured_goal["homopolymer_max_run"] = max_run
    structured_goal["homopolymer_limits"] = per_base_limits
    homo_block = structured_goal.setdefault("homopolymers", {})
    homo_block["per_base_max"] = per_base_limits
    homo_block["max_run"] = max_run
    homo_block["avoid_sequences"] = []

    param_block = structured_goal.get("parameter_constraints")
    if isinstance(param_block, dict):
        param_block["homopolymer_max_run"] = max_run
        param_homo = param_block.setdefault("homopolymers", {})
        param_homo["per_base_max"] = per_base_limits
        param_homo["max_run"] = max_run
        param_homo["avoid_sequences"] = []
        param_block["allow_homopolymer_runs"] = True

    constraints_block = structured_goal.get("constraints")
    if isinstance(constraints_block, dict):
        constraints_block["homopolymer_max_run"] = max_run
        constraints_block["allow_homopolymer_runs"] = True
        constraints_homo = constraints_block.setdefault("homopolymers", {})
        constraints_homo["per_base_max"] = per_base_limits
        constraints_homo["max_run"] = max_run
        constraints_homo["avoid_sequences"] = []

    if isinstance(parameter_constraints, dict):
        parameter_constraints["homopolymer_max_run"] = max_run
        param_homo = parameter_constraints.setdefault("homopolymers", {})
        param_homo["per_base_max"] = per_base_limits
        param_homo["max_run"] = max_run
        param_homo["avoid_sequences"] = []
        parameter_constraints["allow_homopolymer_runs"] = True


def _ensure_homopolymer_constraint(structured_goal: Optional[Dict[str, Any]], user_request: str) -> None:
    """Normalize homopolymer limits without prompting the user."""
    if not isinstance(structured_goal, dict):
        return
    if _allows_homopolymer_runs(structured_goal):
        _apply_allow_all_homopolymers(structured_goal)
        return

    _ = user_request  # reserved for future text-based inference
    bases = ("A", "C", "G", "T")
    inferred_limits: Dict[str, int] = {}
    uniform_limits: List[int] = []

    def _merge_limit(base: str, candidate: Any) -> None:
        limit_val = _coerce_non_negative_int(candidate)
        if limit_val is None:
            return
        current = inferred_limits.get(base)
        if current is None or limit_val < current:
            inferred_limits[base] = limit_val

    def _apply_uniform_limit(candidate: Any) -> None:
        limit_val = _coerce_positive_int(candidate)
        if limit_val is None:
            return
        uniform_limits.append(limit_val)

    def _apply_per_base_limits(per_base: Any) -> None:
        if not isinstance(per_base, dict):
            return
        for base, value in per_base.items():
            base_norm = str(base).strip().upper()
            if base_norm in bases:
                _merge_limit(base_norm, value)

    def _apply_avoid_sequences(seqs: Any) -> None:
        if not isinstance(seqs, list):
            return
        for seq in seqs:
            seq_norm = str(seq).strip().upper()
            if not seq_norm or len(set(seq_norm)) != 1:
                continue
            base = seq_norm[0]
            if base not in bases:
                continue
            run_len = len(seq_norm) - 1
            if run_len > 0:
                _merge_limit(base, run_len)

    # Existing normalized constraints should not override explicit intake constraints.
    # Only fall back to parameter_constraints when no raw constraints block is present.
    param_constraints = structured_goal.get("parameter_constraints")
    has_raw_constraints = isinstance(structured_goal.get("constraints"), dict)
    if not has_raw_constraints and isinstance(param_constraints, dict):
        homo_entry = param_constraints.get("homopolymers")
        if isinstance(homo_entry, dict):
            _apply_uniform_limit(homo_entry.get("max_run"))
            _apply_per_base_limits(homo_entry.get("per_base_max"))
            _apply_avoid_sequences(homo_entry.get("avoid_sequences"))
        _apply_uniform_limit(param_constraints.get("homopolymer_max_run"))

    # Top-level homopolymer hints on the structured goal
    _apply_uniform_limit(structured_goal.get("homopolymer_max_run"))
    homo_top = structured_goal.get("homopolymers")
    if isinstance(homo_top, dict):
        _apply_uniform_limit(homo_top.get("max_run"))
        _apply_per_base_limits(homo_top.get("per_base_max"))
        _apply_avoid_sequences(homo_top.get("avoid_sequences"))

    # Constraint block may also carry homopolymer hints
    constraints_block = structured_goal.get("constraints")
    if isinstance(constraints_block, dict):
        homo_obj = constraints_block.get("homopolymers")
        if isinstance(homo_obj, dict):
            _apply_uniform_limit(homo_obj.get("max_run"))
            _apply_per_base_limits(homo_obj.get("per_base_max"))
            _apply_avoid_sequences(homo_obj.get("avoid_sequences"))
        _apply_uniform_limit(constraints_block.get("homopolymer_max_run"))

    # Fill missing bases with defaults, then apply explicit global caps if present.
    final_limits: Dict[str, int] = {base: DEFAULT_HOMOPOLYMER_LIMIT for base in bases}
    for base, value in inferred_limits.items():
        if base in final_limits:
            final_limits[base] = value

    uniform_limit = min(uniform_limits) if uniform_limits else None
    # Per-base limits are authoritative; only apply a uniform cap when no per-base values were found.
    apply_uniform_cap = uniform_limit is not None and not inferred_limits
    if apply_uniform_cap:
        for base in bases:
            final_limits[base] = min(final_limits[base], uniform_limit)

    if apply_uniform_cap:
        structured_goal["homopolymer_max_run"] = uniform_limit
    else:
        structured_goal.pop("homopolymer_max_run", None)
    structured_goal["homopolymer_limits"] = final_limits

    homo_block = structured_goal.setdefault("homopolymers", {})
    homo_block["per_base_max"] = final_limits
    if apply_uniform_cap:
        homo_block["max_run"] = uniform_limit
    else:
        homo_block.pop("max_run", None)

    param_block = structured_goal.setdefault("parameter_constraints", {})
    homo_param = param_block.setdefault("homopolymers", {})
    homo_param["per_base_max"] = final_limits
    if apply_uniform_cap:
        homo_param["max_run"] = uniform_limit
    else:
        homo_param.pop("max_run", None)

    sources = homo_param.setdefault("sources", [])
    if "inferred_default" not in sources:
        sources.append("inferred_default")


def _ensure_off_target_expression_defaults(structured_goal: Optional[Dict[str, Any]]) -> None:
    if not isinstance(structured_goal, dict):
        return
    settings = structured_goal.get("off_target_expression")
    if not isinstance(settings, dict):
        settings = structured_goal.get("cellxgene")
        if not isinstance(settings, dict):
            settings = {}
            structured_goal["off_target_expression"] = settings
    if not any(key in settings for key in ("sample_mode", "sample_strategy", "cell_sample_mode")):
        settings["sample_mode"] = "first"


def _apply_patient_reference_from_variant(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
    run_dir: str,
) -> Optional[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return None
    if structured_goal.get("patient_reference"):
        return structured_goal.get("patient_reference")
    patient_variant = structured_goal.get("patient_variant")
    if not isinstance(patient_variant, dict):
        return None

    chrom_raw = patient_variant.get("chr") or patient_variant.get("chrom") or patient_variant.get("chromosome")
    pos = _coerce_positive_int(patient_variant.get("pos"))
    ref = patient_variant.get("ref")
    alt = patient_variant.get("alt")

    if not chrom_raw or pos is None or not ref or not alt:
        if isinstance(patient_variant, dict) and patient_variant.get("target_is_reference"):
            print("[info] Target allele matches reference; skipping patient reference generation.")
        else:
            print("[warn] patient_variant missing chr/pos/ref/alt; skipping patient reference generation.")
        return None

    species_key = normalize_species(structured_goal.get("species"))
    structured_goal["species"] = species_key
    species_cfg = get_species_config(species_key)
    reference_path = Path(species_cfg.genome_fasta)
    if not reference_path.exists():
        print(f"[warn] Reference FASTA not found at {reference_path}; skipping patient reference generation.")
        return None

    chrom_short, chrom_pref = _normalize_chromosome_label(chrom_raw)
    chrom_use = chrom_pref or chrom_short or str(chrom_raw)
    try:
        fasta = Fasta(str(reference_path), rebuild=False)
        if chrom_pref and chrom_pref in fasta:
            chrom_use = chrom_pref
        elif chrom_short and chrom_short in fasta:
            chrom_use = chrom_short
    except Exception:
        pass

    patient_base_dir = canonical_run_path(run_dir, "patient_reference")
    aggregated_vcf_path = patient_base_dir / "patient_variants.vcf"
    aggregated_fasta_path = patient_base_dir / "patient_reference.fa"
    patient_base_dir.mkdir(parents=True, exist_ok=True)

    sample_name = str(structured_goal.get("gene_symbol") or "patient")
    variant_list = [{
        "chrom": str(chrom_use),
        "pos": int(pos),
        "ref": str(ref).upper(),
        "alt": str(alt).upper(),
    }]

    _write_patient_vcf(variant_list, reference_path, aggregated_vcf_path, sample_name=sample_name)
    _write_patient_reference(reference_path, variant_list, aggregated_fasta_path, sample_name=sample_name)

    patient_reference = {
        "vcf_path": str(aggregated_vcf_path),
        "fasta_path": str(aggregated_fasta_path),
        "variant_count": len(variant_list),
        "matches_reference": False,
    }
    structured_goal["patient_reference"] = patient_reference
    if isinstance(final_payload, dict):
        final_payload["patient_reference"] = patient_reference
    return patient_reference


def _fetch_reference_base(reference_path: Path, chrom: str, pos: int) -> Optional[str]:
    try:
        fasta = Fasta(str(reference_path), rebuild=False)
        seq = str(fasta[chrom][pos - 1 : pos])
        return seq.upper() if seq else None
    except Exception:
        return None


def _resolve_patient_variant_rsid(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
) -> None:
    if not isinstance(structured_goal, dict):
        return
    patient_variant = structured_goal.get("patient_variant")
    if not isinstance(patient_variant, dict):
        return

    if patient_variant.get("chr") and patient_variant.get("pos") and patient_variant.get("ref") and patient_variant.get("alt"):
        return

    rsid = patient_variant.get("rsid")
    if not rsid:
        return
    rsid = str(rsid).strip()
    if not rsid:
        return

    species_key = normalize_species(structured_goal.get("species"))
    structured_goal["species"] = species_key
    species_cfg = get_species_config(species_key)
    ensembl_species = species_cfg.ensembl_species

    url = f"https://rest.ensembl.org/variation/{ensembl_species}/{rsid}"
    try:
        response = requests.get(
            url,
            headers={"Content-Type": "application/json", "Accept": "application/json"},
            timeout=15,
        )
    except Exception as exc:
        print(f"[warn] Failed to resolve {rsid}: {exc}")
        return
    if not response.ok:
        print(f"[warn] Failed to resolve {rsid}: HTTP {response.status_code}")
        return
    try:
        payload = response.json()
    except Exception:
        print(f"[warn] Failed to parse rsID response for {rsid}.")
        return

    mappings = payload.get("mappings") or []
    if not mappings:
        print(f"[warn] No mappings found for {rsid}.")
        return

    preferred_assembly = None
    if species_key == "human":
        preferred_assembly = "GRCh38"
    elif species_key == "mouse":
        preferred_assembly = "GRCm39"

    mapping = None
    if preferred_assembly:
        for entry in mappings:
            if entry.get("assembly_name") == preferred_assembly:
                mapping = entry
                break
    if mapping is None:
        mapping = mappings[0]

    chrom_raw = mapping.get("seq_region_name")
    start = _coerce_positive_int(mapping.get("start"))
    allele_string = mapping.get("allele_string") or payload.get("allele_string")
    if not chrom_raw or start is None or not allele_string:
        print(f"[warn] rsID {rsid} missing mapping details; skipping VCF resolution.")
        return

    reference_path = Path(species_cfg.genome_fasta)
    if not reference_path.exists():
        print(f"[warn] Reference FASTA not found at {reference_path}; skipping rsID resolution.")
        return

    chrom_short, chrom_pref = _normalize_chromosome_label(chrom_raw)
    chrom_use = chrom_pref or chrom_short or str(chrom_raw)
    try:
        fasta = Fasta(str(reference_path), rebuild=False)
        if chrom_pref and chrom_pref in fasta:
            chrom_use = chrom_pref
        elif chrom_short and chrom_short in fasta:
            chrom_use = chrom_short
    except Exception:
        pass

    ref_base = _fetch_reference_base(reference_path, chrom_use, int(start))
    alleles = [a.strip().upper() for a in re.split(r"[\\/|]", str(allele_string)) if a and a != "-"]
    target_allele = patient_variant.get("target_allele")
    constraints = structured_goal.get("constraints")
    if not target_allele and isinstance(constraints, dict):
        allele_specific = constraints.get("allele_specific")
        if isinstance(allele_specific, dict):
            target_allele = allele_specific.get("target_allele")
        if not target_allele:
            targets = constraints.get("allele_specific_targets")
            if isinstance(targets, list) and targets:
                for item in targets:
                    if isinstance(item, dict) and item.get("target_allele"):
                        target_allele = item.get("target_allele")
                        break
    target_allele = str(target_allele).strip().upper() if target_allele else None

    alt = None
    if target_allele:
        if target_allele not in alleles:
            print(
                f"[warn] rsID {rsid} target allele {target_allele} not found in alleles {alleles}; skipping VCF."
            )
            return
        if ref_base and target_allele != ref_base:
            alt = target_allele
        elif ref_base and target_allele == ref_base:
            alt = None
    if alt is None:
        for allele in alleles:
            if not ref_base or allele != ref_base:
                alt = allele
                break

    if target_allele and ref_base and target_allele == ref_base:
        patient_variant["chr"] = chrom_use
        patient_variant["pos"] = int(start)
        patient_variant["ref"] = ref_base
        patient_variant["rsid"] = rsid
        patient_variant["rsid_source"] = "ensembl_variation"
        patient_variant["target_is_reference"] = True
        if mapping.get("assembly_name"):
            patient_variant["assembly"] = mapping.get("assembly_name")
        structured_goal["patient_variant"] = patient_variant
        if isinstance(final_payload, dict):
            final_payload["patient_variant"] = patient_variant
        print(f"[info] rsID {rsid} target allele matches reference; no VCF entry needed.")
        return

    if not ref_base or not alt or alt == ref_base:
        print(f"[warn] rsID {rsid} resolution failed (ref={ref_base}, alt={alt}); skipping.")
        return

    patient_variant["chr"] = chrom_use
    patient_variant["pos"] = int(start)
    patient_variant["ref"] = ref_base
    patient_variant["alt"] = alt
    patient_variant["rsid"] = rsid
    patient_variant["rsid_source"] = "ensembl_variation"
    if mapping.get("assembly_name"):
        patient_variant["assembly"] = mapping.get("assembly_name")

    structured_goal["patient_variant"] = patient_variant
    if isinstance(final_payload, dict):
        final_payload["patient_variant"] = patient_variant


def _ensembl_variant_json(url: str) -> Any:
    """Fetch typed variant evidence from Ensembl with the runtime retry policy."""
    attempts = max(1, _coerce_positive_int(os.environ.get("ENSEMBL_REST_MAX_RETRIES")) or 3)
    timeout = max(5, _coerce_positive_int(os.environ.get("ENSEMBL_REST_TIMEOUT_SECONDS")) or 30)
    last_response: Optional[requests.Response] = None
    last_error: Optional[BaseException] = None
    for attempt in range(attempts):
        try:
            response = requests.get(
                url,
                headers={"Accept": "application/json", "Content-Type": "application/json"},
                timeout=timeout,
                allow_redirects=True,
            )
            last_response = response
        except Exception as exc:
            last_error = exc
            if attempt + 1 < attempts:
                time.sleep(min(4.0, float(2**attempt)))
            continue
        if response.status_code == 429 or response.status_code >= 500:
            last_error = RuntimeError(f"HTTP {response.status_code}")
            if attempt + 1 < attempts:
                time.sleep(min(4.0, float(2**attempt)))
            continue
        if response.status_code == 404:
            return None
        try:
            response.raise_for_status()
            return response.json()
        except Exception as exc:
            raise EnsemblServiceError(
                f"Ensembl variant lookup failed ({response.status_code}): {exc}",
                retryable=False,
                status_code=response.status_code,
            ) from exc
    status_code = last_response.status_code if last_response is not None else None
    detail = f"HTTP {status_code}" if status_code is not None else str(last_error or "connection failure")
    raise EnsemblServiceError(
        f"Ensembl variant lookup is unavailable after {attempts} attempts: {detail}",
        retryable=True,
        status_code=status_code,
    ) from last_error


def _variant_alleles_from_string(value: Any) -> Tuple[Optional[str], Optional[str]]:
    alleles = [str(item).strip().upper() for item in str(value or "").split("/") if str(item).strip()]
    if len(alleles) < 2:
        return None, None
    return alleles[0], alleles[-1]


def _hgvs_coordinate_kind(notation: Any) -> str:
    _accession, separator, expression = str(notation or "").strip().partition(":")
    if not separator:
        return ""
    coordinate = expression.strip().lower()
    if coordinate.startswith(("c.", "n.", "r.")):
        return "cdna"
    if coordinate.startswith(("g.", "m.")):
        return "genomic"
    if coordinate.startswith("p."):
        return "protein"
    return ""


def _hgvs_coordinate_expression(notation: Any) -> str:
    """Return a bare typed HGVS coordinate without pattern matching."""
    text = str(notation or "").strip()
    if not text:
        return ""
    candidates: List[str] = []
    _prefix, separator, suffix = text.rpartition(":")
    if separator:
        candidates.append(suffix)
    candidates.extend(reversed(text.split()))
    for candidate in candidates:
        coordinate = candidate.strip().strip("()[]{};,")
        if coordinate.lower().startswith(("c.", "n.", "r.", "p.", "g.", "m.")):
            return coordinate
    return ""


def _source_backed_hgvs_query(
    structured_goal: Dict[str, Any],
    patient_variant: Dict[str, Any],
    *,
    species_name: str,
) -> Tuple[str, Dict[str, Any]]:
    """Qualify a bare or gene-qualified HGVS coordinate from source evidence."""
    notation = str(patient_variant.get("notation") or "").strip()
    coordinate = _hgvs_coordinate_expression(notation)
    if not coordinate:
        return notation, {}

    prefix, separator, _suffix = notation.rpartition(":")
    gene_symbol = str(
        patient_variant.get("gene_symbol")
        or structured_goal.get("gene_symbol")
        or ""
    ).strip()
    prefix_is_gene = bool(
        separator
        and gene_symbol
        and prefix.strip().casefold() == gene_symbol.casefold()
    )
    if separator and prefix.strip() and not prefix_is_gene:
        return notation, {}

    coordinate_kind = _hgvs_coordinate_kind(f"reference:{coordinate}")
    if coordinate_kind not in {"cdna", "protein"}:
        return "", {
            "status": "unresolved",
            "reason": "patient_variant_hgvs_requires_reference_accession",
        }

    reference = str(
        patient_variant.get("reference_accession")
        or patient_variant.get("transcript_id")
        or ""
    ).strip()
    if not reference:
        lock = structured_goal.get("transcript_lock")
        if isinstance(lock, dict) and str(lock.get("kind") or "").strip() in {
            "explicit_id",
            "reference_accession",
        }:
            reference = str(lock.get("value") or "").strip()
    if reference:
        return f"{reference}:{coordinate}", {
            "status": "resolved",
            "method": "explicit_reference_accession",
            "reference": reference,
        }

    gene_id = str(structured_goal.get("gene_id") or "").strip()
    if gene_id:
        lookup_url = (
            f"https://rest.ensembl.org/lookup/id/{quote(gene_id, safe='_-')}"
            "?expand=1"
        )
    elif gene_symbol:
        lookup_url = (
            "https://rest.ensembl.org/lookup/symbol/"
            f"{quote(species_name, safe='_')}/{quote(gene_symbol, safe='_-')}"
            "?expand=1"
        )
    else:
        return "", {
            "status": "unresolved",
            "reason": "patient_variant_hgvs_gene_identity_missing",
        }
    lookup = _ensembl_variant_json(lookup_url)
    canonical_transcript = (
        str(lookup.get("canonical_transcript") or "").strip().split(".", 1)[0]
        if isinstance(lookup, dict)
        else ""
    )
    if not canonical_transcript:
        return "", {
            "status": "unresolved",
            "reason": "patient_variant_canonical_transcript_unresolved",
            "source_url": lookup_url,
        }
    return f"{canonical_transcript}:{coordinate}", {
        "status": "resolved",
        "method": "ensembl_canonical_transcript",
        "reference": canonical_transcript,
        "source_url": lookup_url,
    }


def _normalize_patient_variant_allele_orientation(patient_variant: Dict[str, Any]) -> str:
    notation_kind = _hgvs_coordinate_kind(patient_variant.get("notation"))
    declared_kind = str(patient_variant.get("kind") or "unknown").strip().lower()
    kind = notation_kind or declared_kind
    if notation_kind:
        patient_variant["kind"] = notation_kind
    if kind not in {"cdna", "genomic"}:
        return kind

    orientation = "genomic" if kind == "genomic" else "transcript"
    patient_variant["allele_orientation"] = orientation
    ref = str(patient_variant.get("ref") or "").strip().upper()
    alt = str(patient_variant.get("alt") or "").strip().upper()
    if kind == "genomic":
        patient_variant["genomic_ref"] = ref
        patient_variant["genomic_alt"] = alt
        return kind

    evidence_by_transcript = patient_variant.get("transcript_consequences")
    evidence_by_transcript = (
        evidence_by_transcript if isinstance(evidence_by_transcript, dict) else {}
    )
    resolved_transcript_id = str(
        patient_variant.get("resolved_transcript_id")
        or patient_variant.get("transcript_id")
        or ""
    ).strip().split(".", 1)[0]
    evidence = evidence_by_transcript.get(resolved_transcript_id)
    if not isinstance(evidence, dict) and len(evidence_by_transcript) == 1:
        evidence = next(iter(evidence_by_transcript.values()))
    strand_value = evidence.get("strand") if isinstance(evidence, dict) else None
    if str(strand_value).strip() in {"-", "-1"}:
        patient_variant["genomic_ref"] = str(Seq(ref).complement()) if ref else ""
        patient_variant["genomic_alt"] = str(Seq(alt).complement()) if alt else ""
    elif strand_value not in (None, ""):
        patient_variant["genomic_ref"] = ref
        patient_variant["genomic_alt"] = alt
    return kind


def _matching_refseq_transcript_from_vep(
    accession: str,
    transcript_ids: List[str],
) -> Optional[Dict[str, Any]]:
    accession_text = str(accession or "").strip()
    if not accession_text:
        return None
    accession_base, separator, accession_version = accession_text.partition(".")
    for transcript_id in transcript_ids:
        tx = str(transcript_id or "").strip().split(".", 1)[0]
        if not tx:
            continue
        url = (
            f"https://rest.ensembl.org/xrefs/id/{quote(tx, safe='_-')}"
            "?external_db=RefSeq_mRNA"
        )
        rows = _ensembl_variant_json(url)
        for row in rows if isinstance(rows, list) else []:
            if not isinstance(row, dict):
                continue
            display_id = str(row.get("display_id") or "").strip()
            primary_id = str(row.get("primary_id") or "").strip()
            display_base, display_separator, display_version = display_id.partition(".")
            if accession_base.upper() not in {
                display_base.upper(),
                primary_id.split(".", 1)[0].upper(),
            }:
                continue
            if separator and display_separator and accession_version != display_version:
                continue
            return {
                "transcript_id": tx,
                "reference_accession": accession_text,
                "method": "ensembl_vep_refseq_xref",
                "confidence": "high",
                "source_url": url,
                "xref": deepcopy(row),
            }
    return None


def _resolve_patient_variant_context(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Resolve one typed sequence-context variant to genomic/transcript evidence."""
    if not isinstance(structured_goal, dict):
        return {}
    patient_variant = structured_goal.get("patient_variant")
    if not isinstance(patient_variant, dict):
        return {}
    _normalize_patient_variant_allele_orientation(patient_variant)
    existing = patient_variant.get("resolution")
    if isinstance(existing, dict) and existing.get("status") == "resolved":
        if isinstance(final_payload, dict):
            final_payload["patient_variant"] = deepcopy(patient_variant)
        return deepcopy(existing)

    species_key = normalize_species(structured_goal.get("species") or "human")
    species_cfg = get_species_config(species_key)
    species_name = str(species_cfg.ensembl_species)
    notation = str(patient_variant.get("notation") or "").strip()
    kind = _normalize_patient_variant_allele_orientation(patient_variant)
    chrom = str(patient_variant.get("chr") or "").strip()
    position = _coerce_positive_int(patient_variant.get("pos"))
    ref = str(patient_variant.get("ref") or "").strip().upper()
    alt = str(patient_variant.get("alt") or patient_variant.get("target_allele") or "").strip().upper()

    hgvs_query_resolution: Dict[str, Any] = {}
    if kind == "genomic" and chrom and position is not None and alt:
        chrom_short, _chrom_pref = _normalize_chromosome_label(chrom)
        region_chrom = chrom_short or chrom
        region = f"{region_chrom}:{position}-{position}:1"
        url = (
            f"https://rest.ensembl.org/vep/{quote(species_name, safe='_')}/region/"
            f"{quote(region, safe=':-_')}/{quote(alt, safe='')}"
        )
    elif notation:
        hgvs_query, hgvs_query_resolution = _source_backed_hgvs_query(
            structured_goal,
            patient_variant,
            species_name=species_name,
        )
        if not hgvs_query:
            return {
                "status": "unresolved",
                "reason": str(
                    hgvs_query_resolution.get("reason")
                    or "patient_variant_hgvs_reference_unresolved"
                ),
                "hgvs_query_resolution": hgvs_query_resolution,
            }
        url = (
            f"https://rest.ensembl.org/vep/{quote(species_name, safe='_')}/hgvs/"
            f"{quote(hgvs_query, safe=':._-')}"
        )
    else:
        return {"status": "unresolved", "reason": "patient_variant_identity_incomplete"}

    try:
        response = _ensembl_variant_json(url)
    except EnsemblServiceError as exc:
        status_code = getattr(exc, "status_code", None)
        if (
            isinstance(status_code, int)
            and 400 <= status_code < 500
            and status_code != 429
        ):
            return {
                "status": "unresolved",
                "reason": "patient_variant_not_resolved_by_ensembl_vep",
                "source_url": url,
            }
        raise
    records = response if isinstance(response, list) else []
    record = records[0] if records and isinstance(records[0], dict) else None
    if not isinstance(record, dict):
        return {
            "status": "unresolved",
            "reason": "patient_variant_not_resolved_by_ensembl_vep",
            "source_url": url,
        }

    resolved_ref, resolved_alt = _variant_alleles_from_string(record.get("allele_string"))
    if ref and resolved_ref and ref != resolved_ref:
        return {
            "status": "conflict",
            "reason": "patient_variant_reference_allele_conflicts_with_ensembl",
            "expected_ref": ref,
            "resolved_ref": resolved_ref,
            "source_url": url,
        }
    if alt and resolved_alt and alt != resolved_alt:
        return {
            "status": "conflict",
            "reason": "patient_variant_target_allele_conflicts_with_ensembl",
            "expected_alt": alt,
            "resolved_alt": resolved_alt,
            "source_url": url,
        }
    ref = ref or str(resolved_ref or "").upper()
    alt = alt or str(resolved_alt or "").upper()

    consequences = [
        item
        for item in (record.get("transcript_consequences") or [])
        if isinstance(item, dict)
    ]
    requested_gene = str(
        patient_variant.get("gene_symbol") or structured_goal.get("gene_symbol") or ""
    ).strip()
    gene_consequences = [
        item
        for item in consequences
        if not requested_gene
        or str(item.get("gene_symbol") or "").strip().upper() == requested_gene.upper()
    ]
    protein_coding = [
        item
        for item in gene_consequences
        if str(item.get("biotype") or "").strip().lower() == "protein_coding"
    ]
    if protein_coding:
        gene_consequences = protein_coding

    gene_pairs = {
        (
            str(item.get("gene_id") or "").strip(),
            str(item.get("gene_symbol") or "").strip(),
        )
        for item in gene_consequences
        if str(item.get("gene_id") or "").strip()
        and str(item.get("gene_symbol") or "").strip()
    }
    if len(gene_pairs) != 1:
        return {
            "status": "unresolved",
            "reason": "patient_variant_gene_mapping_ambiguous",
            "candidate_genes": [
                {"gene_id": gene_id, "gene_symbol": gene_symbol}
                for gene_id, gene_symbol in sorted(gene_pairs)
            ],
            "source_url": url,
        }
    gene_id, gene_symbol = next(iter(gene_pairs))

    resolved_chrom = str(record.get("seq_region_name") or chrom).strip()
    resolved_position = _coerce_positive_int(record.get("start")) or position
    assembly = str(record.get("assembly_name") or patient_variant.get("genome_build") or "").strip()
    transcript_evidence: Dict[str, Dict[str, Any]] = {}
    transcript_ids: List[str] = []
    for item in gene_consequences:
        transcript_id = str(item.get("transcript_id") or "").strip().split(".", 1)[0]
        if not transcript_id:
            continue
        if transcript_id not in transcript_ids:
            transcript_ids.append(transcript_id)
        transcript_evidence[transcript_id] = {
            key: deepcopy(item.get(key))
            for key in (
                "amino_acids",
                "biotype",
                "cdna_end",
                "cdna_start",
                "cds_end",
                "cds_start",
                "codons",
                "consequence_terms",
                "gene_id",
                "gene_symbol",
                "protein_end",
                "protein_start",
                "strand",
                "transcript_id",
                "variant_allele",
            )
            if item.get(key) not in (None, "", [], {})
        }

    reference_accession = str(patient_variant.get("reference_accession") or "").strip()
    if not reference_accession:
        lock = structured_goal.get("transcript_lock")
        if isinstance(lock, dict) and str(lock.get("kind") or "").strip() == "reference_accession":
            reference_accession = str(lock.get("value") or "").strip()
    accession_resolution = (
        _matching_refseq_transcript_from_vep(reference_accession, transcript_ids)
        if reference_accession
        else None
    )
    preferred_transcript_id = ""
    if isinstance(accession_resolution, dict):
        resolved_transcript_id = str(accession_resolution.get("transcript_id") or "").strip()
        if resolved_transcript_id:
            preferred_transcript_id = resolved_transcript_id.split(".", 1)[0]
            structured_goal["transcript_policy"] = "user_locked"
            structured_goal["transcript_lock"] = {
                "kind": "explicit_id",
                "value": resolved_transcript_id,
                "note": (
                    f"Resolved user-supplied reference accession {reference_accession} "
                    "through an exact Ensembl RefSeq mRNA cross-reference."
                ),
            }
            patient_variant["reference_accession"] = reference_accession
            patient_variant["transcript_id"] = resolved_transcript_id

    if not preferred_transcript_id:
        transcript_lock = structured_goal.get("transcript_lock")
        if isinstance(transcript_lock, dict):
            lock_kind = str(transcript_lock.get("kind") or "").strip().lower()
            lock_value = str(transcript_lock.get("value") or "").strip().split(".", 1)[0]
            if lock_kind == "explicit_id" and lock_value in transcript_evidence:
                preferred_transcript_id = lock_value

    canonical_resolution: Dict[str, Any] = {}
    if not preferred_transcript_id:
        canonical_url = (
            f"https://rest.ensembl.org/lookup/id/{quote(gene_id, safe='_-')}"
        )
        canonical_payload = _ensembl_variant_json(canonical_url)
        if isinstance(canonical_payload, dict):
            canonical_id = str(
                canonical_payload.get("canonical_transcript") or ""
            ).strip().split(".", 1)[0]
            if canonical_id in transcript_evidence:
                preferred_transcript_id = canonical_id
                canonical_resolution = {
                    "transcript_id": canonical_id,
                    "method": "ensembl_canonical_transcript",
                    "confidence": "high",
                    "source_url": canonical_url,
                }

    if preferred_transcript_id and preferred_transcript_id in transcript_evidence:
        transcript_evidence = {
            preferred_transcript_id: transcript_evidence[preferred_transcript_id]
        }
        patient_variant["resolved_transcript_id"] = preferred_transcript_id
    else:
        return {
            "status": "unresolved",
            "reason": "patient_variant_transcript_mapping_unresolved",
            "source_url": url,
        }

    chrom_short, chrom_pref = _normalize_chromosome_label(resolved_chrom)
    patient_variant["chr"] = chrom_pref or chrom_short or resolved_chrom
    if resolved_position is not None:
        patient_variant["pos"] = int(resolved_position)
    patient_variant["ref"] = ref
    patient_variant["alt"] = alt
    patient_variant["target_allele"] = str(
        patient_variant.get("target_allele") or alt
    ).strip().upper()
    patient_variant["non_target_allele"] = str(
        patient_variant.get("non_target_allele") or ref
    ).strip().upper()
    patient_variant["gene_symbol"] = gene_symbol
    patient_variant["genome_build"] = assembly
    patient_variant["transcript_consequences"] = transcript_evidence
    _normalize_patient_variant_allele_orientation(patient_variant)
    resolution = {
        "status": "resolved",
        "source": "ensembl_vep",
        "source_url": url,
        "assembly_name": assembly,
        "gene_id": gene_id,
        "gene_symbol": gene_symbol,
        "chrom": patient_variant.get("chr"),
        "pos": patient_variant.get("pos"),
        "transcript_count": len(transcript_evidence),
        "resolved_transcript_id": preferred_transcript_id,
    }
    if hgvs_query_resolution:
        resolution["hgvs_query_resolution"] = deepcopy(hgvs_query_resolution)
    if isinstance(accession_resolution, dict):
        resolution["reference_accession_resolution"] = deepcopy(accession_resolution)
    elif canonical_resolution:
        resolution["transcript_resolution"] = deepcopy(canonical_resolution)
    patient_variant["resolution"] = resolution
    structured_goal["patient_variant"] = patient_variant
    structured_goal["gene_id"] = gene_id
    structured_goal["gene_symbol"] = gene_symbol
    if isinstance(final_payload, dict):
        final_payload["patient_variant"] = deepcopy(patient_variant)
        final_payload["gene_id"] = gene_id
        final_payload["gene_symbol"] = gene_symbol
        if isinstance(accession_resolution, dict):
            final_payload["transcript_policy"] = structured_goal.get("transcript_policy")
            final_payload["transcript_lock"] = deepcopy(structured_goal.get("transcript_lock"))
    return deepcopy(resolution)


def _infer_num_mismatches(structured_goal: Dict[str, Any], user_request: str) -> Optional[int]:
    try:
        payload = json.dumps(
            {"user_request": user_request, "structured_goal": structured_goal},
            ensure_ascii=False,
        )
        result = asyncio.run(Runner.run(num_mismatch_agent, input=payload, max_steps=4))
        output: Any = result.final_output
        if isinstance(output, str):
            try:
                output = json.loads(output)
            except Exception:
                return None
        if isinstance(output, dict):
            value = output.get("num_mismatches")
            mismatch_val = _coerce_non_negative_int(value)
            if mismatch_val is not None:
                return mismatch_val
    except Exception as exc:
        print(f"[warn] Failed to interpret mismatch constraint: {exc}")
    return None


def _confidence_requires_confirmation(confidence: Optional[str]) -> bool:
    if confidence is None:
        return True
    normalized = str(confidence).strip().lower()
    if not normalized:
        return True
    return normalized in LOW_CONFIDENCE_LEVELS


def _transcript_match_requires_confirmation(
    *,
    method: Optional[str],
    confidence: Optional[str],
    explicit_flag: Any = None,
) -> bool:
    if explicit_flag is not None:
        return bool(explicit_flag)
    normalized_method = str(method or "").strip().lower()
    if normalized_method in {"direct_id", "user_provided", "preseeded", "interactive"}:
        return False
    if normalized_method in {"web_search", "web_search_primary", "llm_web_search", "fallback", "override"}:
        return True
    return _confidence_requires_confirmation(confidence)


def _prompt_yes_no(question: str, default: bool = True) -> bool:
    suffix = " [Y/n]: " if default else " [y/N]: "
    while True:
        response = input(question + suffix).strip().lower()
        if not response:
            return default
        if response in {"y", "yes"}:
            return True
        if response in {"n", "no"}:
            return False
        print("Please answer with 'y' or 'n'.")


_ENSEMBL_GENE_RE = re.compile(r"^ENS[A-Z]*G\d+(?:\.\d+)?$", re.IGNORECASE)


def _looks_like_ensembl_gene_id(value: str) -> bool:
    return bool(_ENSEMBL_GENE_RE.match(value.strip()))


def _normalize_ensembl_gene_id(value: str) -> str:
    return value.strip().split(".", 1)[0]


def _strip_ensembl_version(value: Optional[str]) -> str:
    if not value:
        return ""
    return str(value).strip().split(".", 1)[0]


def _resolve_gene_id(
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    *,
    allow_interactive: bool = True,
) -> Optional[str]:
    gene_symbol = structured_goal.get("gene_symbol")
    if not gene_symbol:
        return None
    species = normalize_species(structured_goal.get("species"))
    structured_goal["species"] = species

    def _first_cached_gene_id() -> Optional[str]:
        candidates: List[Any] = [
            structured_goal.get("gene_id"),
            final_payload.get("gene_id"),
        ]
        for resolution_payload in (
            structured_goal.get("gene_id_resolution"),
            final_payload.get("gene_id_resolution"),
        ):
            if isinstance(resolution_payload, dict):
                candidates.append(resolution_payload.get("gene_id"))
                candidates.append(resolution_payload.get("candidate_gene_id"))
        for value in candidates:
            if not isinstance(value, str) or not value.strip():
                continue
            normalized = _normalize_ensembl_gene_id(value)
            if _looks_like_ensembl_gene_id(normalized):
                return normalized
        return None

    def _cached_resolution_metadata() -> Dict[str, Any]:
        for resolution_payload in (
            structured_goal.get("gene_id_resolution"),
            final_payload.get("gene_id_resolution"),
        ):
            if isinstance(resolution_payload, dict):
                return deepcopy(resolution_payload)
        return {}

    existing_gene_id = _first_cached_gene_id()
    candidate_payload: Optional[Dict[str, Any]] = None
    candidate_gene_id: Optional[str] = None
    symbol_override = False
    resolution_method = None

    if isinstance(existing_gene_id, str) and existing_gene_id.strip():
        candidate_gene_id = _normalize_ensembl_gene_id(existing_gene_id)
        cached_resolution = _cached_resolution_metadata()
        candidate_payload = {
            "gene_id": candidate_gene_id,
            "display_name": cached_resolution.get("display_name")
            or cached_resolution.get("gene_symbol_resolved")
            or final_payload.get("gene_symbol")
            or structured_goal.get("gene_symbol"),
            "description": cached_resolution.get("description"),
        }
        resolution_method = "cached_gene_id"
    elif _looks_like_ensembl_gene_id(str(gene_symbol)):
        candidate_gene_id = _normalize_ensembl_gene_id(str(gene_symbol))
        candidate_payload = lookup_gene_by_id(candidate_gene_id)
        symbol_override = True
        resolution_method = "symbol_was_gene_id"
    else:
        candidate_payload = lookup_gene_id(str(gene_symbol), species=species)
        if not candidate_payload or candidate_payload.get("error") or not candidate_payload.get("gene_id"):
            from aso_agents.reference_decisions import resolve_gene_label
            candidate_payload = resolve_gene_label(str(gene_symbol), species, lookup_gene_id)
            symbol_override = bool(candidate_payload.get("gene_id"))
        candidate_gene_id = candidate_payload.get("gene_id") if isinstance(candidate_payload, dict) else None
        resolution_method = (
            candidate_payload.get("resolution_source")
            if isinstance(candidate_payload, dict) and candidate_payload.get("resolution_source")
            else "symbol_lookup"
        )

    if not candidate_payload or candidate_payload.get("error") or not candidate_gene_id:
        err = candidate_payload.get("error") if isinstance(candidate_payload, dict) else "unknown_error"
        print(f"[warn] Unable to resolve Ensembl gene ID for {gene_symbol!r}: {err}")
        return None

    def _display_gene(payload: Dict[str, Any]) -> None:
        display_name = payload.get("display_name") or payload.get("gene_symbol") or ""
        description = payload.get("description") or ""
        print(f"\nResolved gene '{gene_symbol}' -> Ensembl gene ID {candidate_gene_id}")
        if display_name:
            print(f"  Name: {display_name}")
        if description:
            print(f"  Description: {description}")

    selected_payload = candidate_payload
    selected_gene_id = candidate_gene_id
    user_override = False

    if allow_interactive:
        _display_gene(candidate_payload)
        while True:
            response = input("Use this gene ID? [Y/other/skip]: ").strip().lower()
            if not response or response in {"y", "yes"}:
                break
            if response in {"skip", "omit"}:
                print("[info] Skipping gene ID confirmation; continuing without a locked Ensembl gene ID.")
                return None
            if response in {"other", "list", "choose", "pick"}:
                response = input("Enter Ensembl gene ID (ENSG...): ").strip()
            if not response:
                continue
            candidate_id = _normalize_ensembl_gene_id(response)
            if not _looks_like_ensembl_gene_id(candidate_id):
                print("Please enter a valid Ensembl gene ID (e.g., ENSG...).")
                continue
            override_payload = lookup_gene_by_id(candidate_id)
            if override_payload.get("error"):
                print(f"Gene ID lookup failed: {override_payload.get('error')}")
                continue
            selected_gene_id = candidate_id
            selected_payload = override_payload
            symbol_override = True
            user_override = True
            break

    if symbol_override:
        resolved_symbol = selected_payload.get("display_name")
        if resolved_symbol and resolved_symbol != gene_symbol:
            structured_goal["gene_symbol"] = resolved_symbol

    structured_goal["gene_id"] = selected_gene_id
    final_payload["gene_id"] = selected_gene_id
    if user_override:
        resolution_method = "user_override"
    resolution_info = {
        "gene_symbol_input": gene_symbol,
        "gene_symbol_resolved": structured_goal.get("gene_symbol") or gene_symbol,
        "gene_id": selected_gene_id,
        "method": resolution_method,
        "symbol_override": symbol_override,
        "display_name": selected_payload.get("display_name") if isinstance(selected_payload, dict) else None,
        "description": selected_payload.get("description") if isinstance(selected_payload, dict) else None,
        "label_resolution": selected_payload.get("label_resolution"),
    }
    if candidate_gene_id and candidate_gene_id != selected_gene_id:
        resolution_info["candidate_gene_id"] = candidate_gene_id
    structured_goal["gene_id_resolution"] = resolution_info
    final_payload["gene_id_resolution"] = resolution_info
    return selected_gene_id


async def run_goal_intake_flow(
    user_request: str,
    max_followups: int = 8,
    allow_clarifications: bool = True,
) -> Tuple[Dict[str, Any], List[Dict[str, str]]]:
    """Execute goal intake with clarifications. Returns final payload and Q/A history."""

    intake_out = await _run_goal_intake_agent_once(user_request)

    qa_history: List[Dict[str, str]] = []
    asked_norm_set = set()

    if not allow_clarifications:
        if intake_out.get("status") == "need_clarification":
            raw_questions = intake_out.get("questions", []) or []
            if not isinstance(raw_questions, list):
                raw_questions = [str(raw_questions)]
            followup_prompt = _build_completion_prompt(user_request, qa_history, raw_questions)
            intake_out = await _run_goal_intake_agent_once(followup_prompt)
            if intake_out.get("status") == "need_clarification":
                print("[warn] Intake still needs clarification; proceeding with partial results.")
        return await _audit_request_obligations(intake_out, user_request, qa_history), qa_history

    for _ in range(max_followups):
        if intake_out.get("status") != "need_clarification":
            break

        raw_questions = intake_out.get("questions", []) or []
        if not isinstance(raw_questions, list):
            raw_questions = [str(raw_questions)]

        new_questions: List[str] = []
        for q in raw_questions:
            q_str = q if isinstance(q, str) else str(q)
            q_norm = q_str.strip().lower()
            if q_norm and q_norm not in asked_norm_set:
                asked_norm_set.add(q_norm)
                new_questions.append(q_str)

        if not new_questions:
            break

        defaulted_answers, new_questions = _partition_defaultable_goal_intake_questions(
            new_questions,
            user_request,
        )
        if defaulted_answers:
            qa_history.extend(defaulted_answers)
            if not new_questions:
                followup_prompt = _build_followup_prompt(user_request, qa_history)
                intake_out = await _run_goal_intake_agent_once(followup_prompt)
                continue

        answers = await _prompt_user_for_answers(new_questions)
        for question, answer in zip(new_questions, answers):
            qa_history.append({"question": question, "answer": answer})

        followup_prompt = _build_followup_prompt(user_request, qa_history)
        intake_out = await _run_goal_intake_agent_once(followup_prompt)

    return await _audit_request_obligations(intake_out, user_request, qa_history), qa_history


async def run_goal_intake_step(
    user_request: str,
    qa_history: Optional[List[Dict[str, str]]] = None,
) -> Dict[str, Any]:
    """Run a single intake step using optional clarification history."""
    qa_history = qa_history or []
    if qa_history:
        prompt = _build_followup_prompt(user_request, qa_history)
    else:
        prompt = user_request
    intake_out = await _run_goal_intake_agent_once(prompt)
    if intake_out.get("status") == "need_clarification":
        open_questions = intake_out.get("questions", []) or []
        if not isinstance(open_questions, list):
            open_questions = [str(open_questions)]
        defaulted_answers, unresolved_questions = _partition_defaultable_goal_intake_questions(
            [str(question) for question in open_questions],
            user_request,
        )
        if defaulted_answers:
            qa_history = qa_history + defaulted_answers
            followup_prompt = _build_followup_prompt(user_request, qa_history)
            intake_out = await _run_goal_intake_agent_once(followup_prompt)
            if unresolved_questions and intake_out.get("status") == "ready":
                return await _audit_request_obligations(intake_out, user_request, qa_history)
    if qa_history and intake_out.get("status") == "need_clarification":
        open_questions = intake_out.get("questions", []) or []
        if not isinstance(open_questions, list):
            open_questions = [str(open_questions)]
        completion_prompt = _build_completion_prompt(user_request, qa_history, open_questions)
        completion_out = await _run_goal_intake_agent_once(completion_prompt)
        if completion_out.get("status") == "ready":
            intake_out = completion_out
    return await _audit_request_obligations(intake_out, user_request, qa_history)


def _make_run_dir(structured_goal: Optional[Dict[str, Any]]) -> str:
    gene = None
    if isinstance(structured_goal, dict):
        gene = structured_goal.get("gene_symbol") or structured_goal.get("gene_id")
    safe_gene = re.sub(r"[^A-Za-z0-9]+", "_", str(gene or "").strip()).strip("_").upper() or "GOAL"
    run_id = f"goal_{int(time.time())}_{safe_gene}"
    from aso_agents.paths import runs_root
    run_dir = str(runs_root() / run_id)
    os.makedirs(run_dir, exist_ok=True)
    return run_dir


def _format_goal_intake_summary(final_payload: Any) -> str:
    if not isinstance(final_payload, dict):
        return "GOAL INTAKE SUMMARY\n(no structured goal output)"
    structured_goal = final_payload.get("structured_goal")
    status = final_payload.get("status")
    lines = ["GOAL INTAKE SUMMARY"]
    if status:
        lines.append(f"Status: {status}")
    if not isinstance(structured_goal, dict):
        lines.append("No structured goal output.")
        return "\n".join(lines)

    def _add(label: str, value: Any) -> None:
        if value is None:
            return
        text = str(value).strip()
        if not text:
            return
        lines.append(f"{label}: {text}")

    _add("Gene", structured_goal.get("gene_symbol"))
    _add("Gene ID", structured_goal.get("gene_id"))
    _add("Species", structured_goal.get("species"))
    _add("Intent", structured_goal.get("intent"))
    _add("Isoform scope source", structured_goal.get("isoform_scope_source"))
    _add("Target region", structured_goal.get("target_region"))
    _add("Mechanism", structured_goal.get("mechanism"))
    _add("Chemistry", structured_goal.get("chemistry"))

    isoform_objectives = structured_goal.get("splice_isoform_objectives") or []
    if isinstance(isoform_objectives, list) and isoform_objectives:
        iso_lines = []
        for obj in isoform_objectives:
            if not isinstance(obj, dict):
                continue
            label = obj.get("isoform_label") or obj.get("label") or "isoform"
            direction = obj.get("direction") or obj.get("goal") or obj.get("intent")
            if direction:
                iso_lines.append(f"{label} ({direction})")
            else:
                iso_lines.append(str(label))
        if iso_lines:
            lines.append("Isoform objectives: " + ", ".join(iso_lines))

    design_programs = structured_goal.get("design_programs") or []
    if isinstance(design_programs, list) and design_programs:
        program_lines = []
        for program in design_programs:
            if not isinstance(program, dict):
                continue
            label = program.get("label") or program.get("program_id") or "program"
            modality = program.get("modality")
            objective = program.get("objective")
            parts = [str(label)]
            if modality:
                parts.append(str(modality))
            if objective:
                parts.append(str(objective))
            program_lines.append(" / ".join(parts))
        if program_lines:
            lines.append("Design programs: " + "; ".join(program_lines))

    constraints = structured_goal.get("constraints")
    if isinstance(constraints, dict) and constraints:
        summary = []
        for key in ("tile_len", "length", "length_nt", "gc_min", "gc_max"):
            if key in constraints:
                summary.append(f"{key}={constraints.get(key)}")
        if summary:
            lines.append("Constraints: " + ", ".join(summary))

    assumptions = structured_goal.get("assumptions")
    if assumptions:
        lines.append(f"Assumptions: {assumptions}")

    return "\n".join(lines)


def _write_steric_bed(rows: List[List[Any]], run_dir: str) -> Optional[str]:
    if not rows:
        return None
    bed_path = canonical_run_path(run_dir, "steric_regions.bed")
    try:
        ensure_run_parent(bed_path)
        with open(bed_path, "w", encoding="utf-8") as handle:
            for row in rows:
                handle.write("\t".join(map(str, row)) + "\n")
        print(f"[info] Steric BED written to {bed_path}")
        return bed_path
    except Exception as exc:
        print(f"[warn] Failed to write steric BED: {exc}")
        return None


def _persist_outputs(
    run_dir: str,
    user_request: str,
    final_payload: Dict[str, Any],
    qa_history: List[Dict[str, str]],
) -> None:
    def _normalize_embedded_goal(container: Any, key: str = "structured_goal") -> None:
        if not isinstance(container, dict):
            return
        embedded = container.get(key)
        if not isinstance(embedded, dict) or not embedded:
            return
        try:
            normalized_goal = apply_parameter_constraints_to_goal(deepcopy(embedded), user_request)
            _normalize_requested_accessibility_provenance(normalized_goal, user_request)
            _normalize_region_constraints_in_goal(normalized_goal)
            container[key] = normalized_goal
        except Exception:
            pass

    def _normalize_envelope(envelope: Any) -> None:
        if not isinstance(envelope, dict):
            return
        _normalize_embedded_goal(envelope)
        default_context = envelope.get("default_context")
        if isinstance(default_context, dict):
            _normalize_embedded_goal(default_context)
        task_context = envelope.get("task_context")
        if isinstance(task_context, dict):
            _normalize_embedded_goal(task_context)
        tasks = envelope.get("tasks")
        if isinstance(tasks, list):
            for task in tasks:
                if not isinstance(task, dict):
                    continue
                _normalize_embedded_goal(task)
                context = task.get("context")
                if isinstance(context, dict):
                    _normalize_embedded_goal(context)
        _normalize_envelope_design_programs(envelope)

    if isinstance(final_payload, dict) and isinstance(final_payload.get("structured_goal"), dict):
        try:
            normalized_goal = apply_parameter_constraints_to_goal(
                deepcopy(final_payload.get("structured_goal") or {}),
                user_request,
            )
            _normalize_requested_accessibility_provenance(normalized_goal, user_request)
            _normalize_region_constraints_in_goal(normalized_goal)
            final_payload["structured_goal"] = normalized_goal
        except Exception as exc:
            print(f"[warn] Parameter constraint normalization before persistence failed: {exc}")
    if isinstance(final_payload, dict):
        _normalize_envelope(final_payload.get("request_envelope"))
        structured_goal = final_payload.get("structured_goal") if isinstance(final_payload.get("structured_goal"), dict) else {}
        envelope = final_payload.get("request_envelope") if isinstance(final_payload.get("request_envelope"), dict) else {}
        task_goal: Dict[str, Any] = {}
        tasks = envelope.get("tasks") if isinstance(envelope.get("tasks"), list) else []
        if len(tasks) == 1 and isinstance(tasks[0], dict):
            task_context = tasks[0].get("context") if isinstance(tasks[0].get("context"), dict) else {}
            if isinstance(task_context.get("structured_goal"), dict):
                task_goal = task_context.get("structured_goal") or {}
        if isinstance(structured_goal, dict) and task_goal:
            promoted = False
            for field in (
                "region_constraints",
                "aso_overlap_requirement",
                "minimum_overlap_bp",
                "target_region",
                "intent",
            ):
                if structured_goal.get(field) in (None, "", [], {}) and task_goal.get(field) not in (None, "", [], {}):
                    structured_goal[field] = deepcopy(task_goal.get(field))
                    promoted = True
            if promoted:
                try:
                    normalized_goal = apply_parameter_constraints_to_goal(structured_goal, user_request)
                    _normalize_region_constraints_in_goal(normalized_goal)
                    final_payload["structured_goal"] = normalized_goal
                except Exception:
                    final_payload["structured_goal"] = structured_goal

    request_path = str(canonical_run_path(run_dir, "request.txt"))
    with open(request_path, "w", encoding="utf-8") as handle:
        handle.write(user_request.strip() + "\n")

    artifact = {
        "request": user_request,
        "final_payload": final_payload,
        "qa_history": qa_history,
    }
    artifact_path = canonical_run_path(run_dir, "goal_intake.json")
    ensure_run_parent(artifact_path)
    with open(artifact_path, "w", encoding="utf-8") as handle:
        json.dump(artifact, handle, ensure_ascii=False, indent=2)

    structured_goal = final_payload.get("structured_goal") if isinstance(final_payload, dict) else None
    if isinstance(structured_goal, dict):
        structured_path = canonical_run_path(run_dir, "structured_goal.json")
        ensure_run_parent(structured_path)
        with open(structured_path, "w", encoding="utf-8") as handle:
            json.dump(structured_goal, handle, ensure_ascii=False, indent=2)
    write_layout_manifest(run_dir)


def _auto_export_genbank(run_dir: str) -> Optional[Path]:
    run_path = Path(run_dir)
    structured_path = resolve_run_path(run_path, "structured_goal.json")
    summary_path = resolve_run_path(run_path, "strategy_router_summary.json")
    generated_path = resolve_run_path(run_path, "generated_aso_set.json")

    if not structured_path.exists():
        return None
    if not summary_path.exists() and not generated_path.exists():
        print("[info] Skipping GenBank export; neither routed nor generated ASO candidates were found.")
        return None
    if not _export_asos_to_genbank:
        detail = ""
        if _GENBANK_EXPORT_IMPORT_ERROR is not None:
            detail = f": {type(_GENBANK_EXPORT_IMPORT_ERROR).__name__}: {_GENBANK_EXPORT_IMPORT_ERROR}"
        print(f"[warn] GenBank export skipped; exporter import failed{detail}")
        return None

    output_path = canonical_run_path(run_path, "snapgene", "aso_export.gb")
    try:
        result = _export_asos_to_genbank(run_path, output_path)
    except FileNotFoundError as exc:
        print(f"[warn] GenBank export skipped: {exc}")
        return None
    except Exception as exc:
        print(f"[warn] GenBank export failed: {exc}")
        return None

    print(f"[info] GenBank export saved to {result}")
    return result


def _safe_int(value: Any) -> Optional[int]:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _safe_float(value: Any) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _parse_bool(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if value is None:
        return None
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "y"}:
        return True
    if text in {"false", "0", "no", "n"}:
        return False
    return None


def _normalize_strand(value: Any) -> Optional[str]:
    if value in {"+", "-"}:
        return value
    if value == 1:
        return "+"
    if value == -1:
        return "-"
    return None


def _parse_site_label(label: Optional[str]) -> Tuple[Optional[str], Optional[int]]:
    if not label:
        return None, None
    match = re.match(r"(?P<kind>[A-Za-z_]+)@(?P<pos>\d+)", label)
    if match:
        return match.group("kind"), int(match.group("pos"))
    match = re.match(r"(?P<kind>[A-Za-z_]+)(?P<pos>\d+)", label)
    if match:
        return match.group("kind"), int(match.group("pos"))
    return None, None


def _load_json_path(path: Path) -> Optional[Dict[str, Any]]:
    try:
        with path.open("r", encoding="utf-8") as handle:
            data = json.load(handle)
    except Exception:
        return None
    return data if isinstance(data, dict) else None


def _normalize_safeguards(safeguards: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for guard in safeguards or []:
        if not isinstance(guard, dict):
            continue
        label = guard.get("label")
        if not label or label in seen:
            continue
        if guard.get("max_increase") is not None:
            direction = "increase"
        elif guard.get("max_decrease") is not None:
            direction = "decrease"
        else:
            direction = "neutral"
        normalized.append(
            {
                "label": label,
                "direction": direction,
                "max_abs_delta": guard.get("max_abs_delta"),
                "max_increase": guard.get("max_increase"),
                "max_decrease": guard.get("max_decrease"),
                "note": guard.get("note"),
            }
        )
        seen.add(label)
    return normalized


def _compute_mean_splice_delta(aso: Dict[str, Any]) -> Optional[float]:
    """Compute mean of delta_deletion and delta_replacement for an ASO.

    Returns None if neither value is available. Returns the single value
    if only one is available. Returns the mean if both are available.
    """
    del_val = aso.get("selected_delta_deletion")
    rep_val = aso.get("selected_delta_replacement")

    # Try to parse as floats
    del_float: Optional[float] = None
    rep_float: Optional[float] = None

    if del_val is not None:
        if isinstance(del_val, (int, float)):
            del_float = float(del_val)
        elif isinstance(del_val, str):
            try:
                del_float = float(del_val)
            except (ValueError, TypeError):
                pass

    if rep_val is not None:
        if isinstance(rep_val, (int, float)):
            rep_float = float(rep_val)
        elif isinstance(rep_val, str):
            try:
                rep_float = float(rep_val)
            except (ValueError, TypeError):
                pass

    if del_float is not None and not math.isfinite(del_float):
        del_float = None
    if rep_float is not None and not math.isfinite(rep_float):
        rep_float = None
    if del_float is None and rep_float is None:
        return None
    if del_float is None:
        return rep_float
    if rep_float is None:
        return del_float
    return (del_float + rep_float) / 2


def _route_goal_primary_labels(goal: Dict[str, Any]) -> List[str]:
    labels: List[str] = []
    primary_targets = goal.get("primary_targets") if isinstance(goal, dict) else None
    if not isinstance(primary_targets, list):
        return labels
    for item in primary_targets:
        if isinstance(item, str):
            label = item.strip()
        elif isinstance(item, dict):
            label = str(item.get("label") or item.get("site_label") or "").strip()
        else:
            label = ""
        if label and label not in labels:
            labels.append(label)
    return labels


def _compact_route_goal_for_html(goal: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(goal, dict):
        return None
    compact: Dict[str, Any] = {}
    for key in (
        "rank",
        "goal_label",
        "primary_effect",
        "rationale",
        "ranking_confidence",
        "ranking_model",
        "routing_selection_source",
        "observed_max_abs_delta",
        "observed_mean_effect",
        "observed_support",
        "count",
        "threshold_used",
        "output_path",
        "csv_path",
        "excel_path",
        "job_id",
        "job_label",
        "notes",
        "selection_mode",
        "threshold_pass_count",
        "fallback_selection_used",
        "fallback_positive_count",
        "warning",
    ):
        value = goal.get(key)
        if value not in (None, "", [], {}):
            compact[key] = value
    primary_labels = _route_goal_primary_labels(goal)
    if primary_labels:
        compact["primary_targets"] = primary_labels
    count_value = _safe_int(goal.get("count"))
    if count_value is not None:
        compact["status"] = "no_candidates_found" if count_value <= 0 else "candidates_found"
        if count_value <= 0 and not compact.get("warning"):
            compact["warning"] = "No ASO candidates met the routing threshold for this route."
    return compact


def _compact_strategy_routing_for_html(strategy_routing: Any) -> Dict[str, Any]:
    if not isinstance(strategy_routing, dict):
        return {}
    compact: Dict[str, Any] = {}
    from aso_agents.ranking_contracts import scoped_strategy_routing_plan
    planner_plan = scoped_strategy_routing_plan(strategy_routing.get("planner_plan"))
    if isinstance(planner_plan, dict):
        compact_plan = {
            key: planner_plan.get(key)
            for key in ("plan_summary", "job_count", "goal_count", "max_steps")
            if planner_plan.get(key) not in (None, "", [], {})
        }
        ranking = planner_plan.get("ranking")
        if isinstance(ranking, dict):
            compact_ranking = {
                key: ranking.get(key)
                for key in ("mode", "model", "summary", "candidate_count", "scope", "job_rankings")
                if ranking.get(key) not in (None, "", [], {})
            }
            if compact_ranking:
                compact_plan["ranking"] = compact_ranking
        if compact_plan:
            compact["planner_plan"] = compact_plan
    goals = strategy_routing.get("goals")
    if isinstance(goals, list):
        compact_goals = [
            goal_payload
            for goal_payload in (_compact_route_goal_for_html(goal) for goal in goals[:120])
            if isinstance(goal_payload, dict)
        ]
        if compact_goals:
            compact["goals"] = compact_goals
            compact["goal_count"] = len(compact_goals)
    output_dir = str(strategy_routing.get("output_dir") or "").strip()
    if output_dir:
        compact["output_dir"] = output_dir
    meta = strategy_routing.get("meta")
    if isinstance(meta, dict):
        compact_meta = {
            key: meta.get(key)
            for key in ("llm_ranked_routes", "ranking_model", "job_count")
            if meta.get(key) not in (None, "", [], {})
        }
        if compact_meta:
            compact["meta"] = compact_meta
    return compact


def _reported_candidate_intervals(
    row: Dict[str, Any], *, output_space: str,
) -> List[Tuple[str, int, int]]:
    """Keep recorded alignment blocks and original source-reference labels."""
    if output_space == "cdna":
        reference = row.get("Chrom") if row.get("Chrom") is not None else row.get("chrom")
        reference = str(reference or "").strip()
        if not reference:
            return []
        # The overlap engine normalizes chromosome aliases. A report must not
        # turn a transcript/sequence identifier into an invented chromosome.
        return [(reference, start, end) for _, start, end in
                _tile_row_overlap_intervals(row, output_space="cdna")]
    segments = row.get("Genomic_segments")
    if isinstance(segments, list):
        segments = json.dumps(segments)
    if segments:
        recorded = _tile_row_overlap_intervals(
            {"Genomic_segments": segments}, output_space="genomic")
        if recorded:
            # Do not fill introns with a separately recorded bounding span.
            return recorded
    return _tile_row_overlap_intervals(row, output_space="genomic")


def _collect_route_data(run_dir: str) -> Dict[str, Dict[str, Any]]:
    route_paths: List[Path] = []
    seen_paths: Set[str] = set()

    def _add_route_path(path: Path) -> None:
        key = str(path.expanduser())
        if key in seen_paths or not path.exists() or not path.is_file():
            return
        seen_paths.add(key)
        route_paths.append(path)

    top_routes_dir = resolve_run_path(run_dir, "strategy_routes")
    if top_routes_dir.exists():
        for route_path in sorted(top_routes_dir.glob("*.route.json")):
            _add_route_path(route_path)

    steric_jobs_dir = resolve_run_path(run_dir, "steric_jobs")
    if steric_jobs_dir.exists():
        for job_dir in sorted(steric_jobs_dir.iterdir()):
            if not job_dir.is_dir():
                continue
            for route_path in sorted((job_dir / "strategy_routes").glob("*.route.json")):
                _add_route_path(route_path)

    summary_path = resolve_run_path(run_dir, "strategy_router_summary.json")
    summary_payload = _load_json_path(summary_path) if summary_path.exists() else None
    route_goal_details: Dict[str, Dict[str, Any]] = {}
    if isinstance(summary_payload, dict):
        for goal in summary_payload.get("goals") or []:
            if not isinstance(goal, dict):
                continue
            output_path = str(goal.get("output_path") or "").strip()
            if output_path:
                _add_route_path(Path(output_path))
            compact_goal = _compact_route_goal_for_html(goal)
            if not isinstance(compact_goal, dict):
                continue
            rank_value = _safe_int(compact_goal.get("rank"))
            for label in _route_goal_primary_labels(goal):
                existing = route_goal_details.get(label)
                existing_rank = _safe_int(existing.get("route_rank")) if isinstance(existing, dict) else None
                if existing_rank is not None and rank_value is not None and existing_rank <= rank_value:
                    continue
                route_goal_details[label] = {
                    "route_rank": rank_value,
                    "route_goal_label": compact_goal.get("goal_label"),
                    "route_rationale": compact_goal.get("rationale"),
                    "route_confidence": compact_goal.get("ranking_confidence"),
                    "route_candidate_count": compact_goal.get("count"),
                    "route_threshold_used": compact_goal.get("threshold_used"),
                }

    if not route_paths:
        return {
            label: {"direction": None, "safeguards": [], "asos": [], **details}
            for label, details in route_goal_details.items()
        }

    route_data: Dict[str, Dict[str, Any]] = {}
    for route_path in sorted(route_paths):
        data = _load_json_path(route_path)
        if not data:
            continue

        primary_targets = data.get("primary_targets") or []
        route_target_labels: List[str] = []
        for target in primary_targets:
            if not isinstance(target, dict):
                continue
            label = target.get("label")
            if not label:
                continue
            route_target_labels.append(label)
            entry = route_data.setdefault(label, {"direction": None, "safeguards": [], "asos": []})
            if not entry.get("direction"):
                entry["direction"] = target.get("direction")

        safeguards = _normalize_safeguards(data.get("safeguards") or [])
        if safeguards:
            for label in route_target_labels:
                entry = route_data.setdefault(label, {"direction": None, "safeguards": [], "asos": []})
                existing = {guard["label"] for guard in entry["safeguards"]}
                for guard in safeguards:
                    if guard["label"] not in existing:
                        entry["safeguards"].append(guard)
                        existing.add(guard["label"])

        rows = data.get("rows") or []
        for row in rows:
            if not isinstance(row, dict):
                continue
            label = row.get("selected_label") or row.get("shared_context_label")
            if not label:
                continue
            entry = route_data.setdefault(label, {"direction": None, "safeguards": [], "asos": []})
            if not entry.get("direction"):
                entry["direction"] = row.get("selected_direction")
            passed = _parse_bool(row.get("safeguards_passed"))
            if passed is False:
                continue
            aso = {
                "sequence": row.get("Sequence"),
                **generated_sequence_fields(row),
                **report_recommendation_fields(row),
                "chrom": row.get("Chrom") or row.get("chrom"),
                "binding_intervals_bed0_half_open": _reported_candidate_intervals(row, output_space="genomic"),
                "source_intervals_bed0_half_open": _reported_candidate_intervals(row, output_space="cdna"),
                "off_target_exact_count_unit": exact_count_unit(row),
                "start": _safe_int(row.get("Start")),
                "end": _safe_int(row.get("End")),
                "strand": row.get("Strand"),
                "score": _safe_float(row.get("Score")),
                "gc": _safe_float(row.get("GC")),
                "times_mapped": _safe_int(row.get("Times_mapped")),
                "repeat_risk_class": row.get("repeat_risk_class"),
                "repeat_splice_eval_status": row.get("repeat_splice_eval_status"),
                "repeat_max_abs_delta": _safe_float(row.get("repeat_max_abs_delta")),
                "repeat_hit_count_exact": _safe_int(row.get("repeat_hit_count_exact")),
                "repeat_hit_count_same_transcript": _safe_int(row.get("repeat_hit_count_same_transcript")),
                "repeat_hit_count_same_gene": _safe_int(row.get("repeat_hit_count_same_gene")),
                "repeat_hit_loci": row.get("repeat_hit_loci"),
                "repeat_high_risk_sites": row.get("repeat_high_risk_sites"),
                "repeat_risk_reason": row.get("repeat_risk_reason"),
                "off_target_genes": row.get("Off_target_genes"),
                "off_target_ratio": _safe_float(row.get("Off_target_expression_ratio")),
                "off_target_exact_count": _safe_int(row.get("Off_target_exact_count")),
                "off_target_1mm_count": _safe_int(row.get("Off_target_1mm_count")),
                "off_target_2mm_count": _safe_int(row.get("Off_target_2mm_count")),
                "off_target_3mm_count": _safe_int(row.get("Off_target_3mm_count")),
                "off_target_expression_weighted_risk": _safe_float(row.get("Off_target_expression_weighted_risk")),
                "selected_delta_deletion": row.get("selected_delta_deletion"),
                "selected_delta_replacement": row.get("selected_delta_replacement"),
                "chemistry_idt": row.get("IDT"),
                "chemistry_synthesis": row.get("Synthesis"),
            }
            aso["mean_splice_delta"] = _compute_mean_splice_delta(aso)
            entry["asos"].append(aso)

    for entry in route_data.values():
        entry["asos"].sort(
            key=lambda item: recommendation_sort_key(item, entry.get("direction")), reverse=True)
        entry["asos"] = entry["asos"][:12]
    for label, details in route_goal_details.items():
        entry = route_data.setdefault(label, {"direction": None, "safeguards": [], "asos": []})
        for key, value in details.items():
            if value not in (None, "", [], {}):
                entry[key] = value
    return route_data


def _load_ranked_asos_csv(csv_path: Path) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    try:
        with csv_path.open("r", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            for row in reader:
                start = _safe_int(
                    row.get("Start")
                    or row.get("start")
                    or row.get("start_bp")
                    or row.get("Genomic_span_start")
                    or row.get("Genomic_start")
                )
                end = _safe_int(
                    row.get("End")
                    or row.get("end")
                    or row.get("end_bp")
                    or row.get("Genomic_span_end")
                    or row.get("Genomic_end")
                )
                if start is None or end is None:
                    continue
                if start > end:
                    start, end = end, start
                aso = {
                    "sequence": row.get("Sequence") or row.get("sequence"),
                    **generated_sequence_fields(row),
                    **report_recommendation_fields(row),
                    "chrom": row.get("Chrom") or row.get("chrom"),
                    "binding_intervals_bed0_half_open": _reported_candidate_intervals(row, output_space="genomic"),
                    "source_intervals_bed0_half_open": _reported_candidate_intervals(row, output_space="cdna"),
                    "off_target_exact_count_unit": exact_count_unit(row),
                    "start": start,
                    "end": end,
                    "strand": row.get("Strand") or row.get("strand"),
                    "score": _safe_float(
                        row.get("Score")
                        or row.get("score")
                        or row.get("tile_score")
                        or row.get("isoform_uniqueness_score")
                    ),
                    "gc": _safe_float(row.get("GC") or row.get("gc_fraction")),
                    "times_mapped": _safe_int(row.get("Times_mapped") or row.get("times_mapped")),
                    "repeat_risk_class": row.get("repeat_risk_class"),
                    "repeat_splice_eval_status": row.get("repeat_splice_eval_status"),
                    "repeat_max_abs_delta": _safe_float(row.get("repeat_max_abs_delta")),
                    "repeat_hit_count_exact": _safe_int(row.get("repeat_hit_count_exact")),
                    "repeat_hit_count_same_transcript": _safe_int(row.get("repeat_hit_count_same_transcript")),
                    "repeat_hit_count_same_gene": _safe_int(row.get("repeat_hit_count_same_gene")),
                    "repeat_hit_loci": row.get("repeat_hit_loci"),
                    "repeat_high_risk_sites": row.get("repeat_high_risk_sites"),
                    "repeat_risk_reason": row.get("repeat_risk_reason"),
                    "off_target_genes": row.get("Off_target_genes") or row.get("off_target_genes"),
                    "off_target_ratio": _safe_float(row.get("Off_target_expression_ratio")),
                    "off_target_exact_count": _safe_int(row.get("Off_target_exact_count") or row.get("off_target_exact_count")),
                    "off_target_1mm_count": _safe_int(row.get("Off_target_1mm_count") or row.get("off_target_1mm_count")),
                    "off_target_2mm_count": _safe_int(row.get("Off_target_2mm_count") or row.get("off_target_2mm_count")),
                    "off_target_3mm_count": _safe_int(row.get("Off_target_3mm_count") or row.get("off_target_3mm_count")),
                    "off_target_expression_weighted_risk": _safe_float(
                        row.get("Off_target_expression_weighted_risk") or row.get("off_target_expression_weighted_risk")
                    ),
                    "selected_delta_deletion": (
                        row.get("selected_delta_deletion")
                        or row.get("primary_delta_deletion")
                        or row.get("delta_deletion")
                    ),
                    "selected_delta_replacement": (
                        row.get("selected_delta_replacement")
                        or row.get("primary_delta_replacement")
                        or row.get("delta_replacement")
                    ),
                    "chemistry_idt": row.get("IDT") or row.get("chemistry_idt"),
                    "chemistry_synthesis": row.get("Synthesis") or row.get("chemistry_synthesis"),
                }
                aso["mean_splice_delta"] = _compute_mean_splice_delta(aso)
                rows.append(aso)
    except Exception:
        return []
    return rows


def _collect_ranked_asos(
    structured_goal: Dict[str, Any],
    run_dir: str,
    results_key: str = "tiling_results",
    tiling_dir_name: str = "tiling",
) -> List[Dict[str, Any]]:
    csv_path: Optional[str] = None
    results = structured_goal.get(results_key) if isinstance(structured_goal, dict) else None
    other_key = "tiling_results" if results_key == "gapmer_tiling_results" else "gapmer_tiling_results"
    if not results and isinstance(structured_goal, dict) and structured_goal.get(other_key):
        return []  # Only the other modality ran; shared exports are not a second branch.
    if isinstance(results, dict):
        csv_path = results.get("uniqueness_csv")
    if csv_path and os.path.exists(csv_path):
        rows = _load_ranked_asos_csv(Path(csv_path))
        if rows:
            return rows
    tiling_dir = resolve_run_path(run_dir, tiling_dir_name)
    search_dirs = [tiling_dir, resolve_run_path(run_dir, "generated_aso_set.json").parent]
    for search_dir in search_dirs:
        if not search_dir.exists() or not search_dir.is_dir():
            continue
        ranked_candidates = sorted(search_dir.glob("*uniqueness_ranked.csv"))
        for candidate in ranked_candidates:
            # The shared candidates directory contains exports from both
            # modalities. A gapmer-only run must not also appear as steric.
            other_prefix = "steric_" if results_key == "gapmer_tiling_results" else "gapmer_"
            if candidate.name.startswith(other_prefix):
                continue
            rows = _load_ranked_asos_csv(candidate)
            if rows:
                return rows
    if results_key == "tiling_results" and tiling_dir_name == "tiling":
        route_data = _collect_route_data(run_dir)
        if route_data:
            unique_rows: List[Dict[str, Any]] = []
            seen_asos: Set[Tuple[str, int, int, str]] = set()
            for entry in route_data.values():
                if not isinstance(entry, dict):
                    continue
                for aso in entry.get("asos") or []:
                    if not isinstance(aso, dict):
                        continue
                    sequence = str(aso.get("sequence") or "").strip()
                    start = _safe_int(aso.get("start"))
                    end = _safe_int(aso.get("end"))
                    strand = str(aso.get("strand") or "").strip()
                    if not sequence or start is None or end is None:
                        continue
                    key = (sequence, start, end, strand)
                    if key in seen_asos:
                        continue
                    seen_asos.add(key)
                    unique_rows.append(dict(aso))
            if unique_rows:
                return unique_rows
    return []


def _overlaps(start_a: int, end_a: int, start_b: int, end_b: int) -> bool:
    return start_a <= end_b and end_a >= start_b


def _build_bed_targets_from_rows(
    rows: Optional[List[List[Any]]],
    ranked_asos: List[Dict[str, Any]],
    default_direction: str,
    output_type: str,
) -> List[Dict[str, Any]]:
    if not rows:
        return []

    targets: List[Dict[str, Any]] = []
    for idx, row in enumerate(rows, 1):
        if not isinstance(row, (list, tuple)) or len(row) < 3:
            continue
        chrom = row[0]
        start = _safe_int(row[1])
        end = _safe_int(row[2])
        if start is None or end is None:
            continue
        if start > end:
            start, end = end, start
        label = row[3] if len(row) > 3 and row[3] else None
        if not label:
            label = f"{chrom}:{start}-{end}"
        position = int((start + end) / 2)
        strand = _normalize_strand(row[5]) if len(row) > 5 else None

        def belongs_to_region(aso: Dict[str, Any]) -> bool:
            from aso_agents.region_overlap import candidate_matches_regions
            candidate_strand = _normalize_strand(aso.get("strand"))
            if strand in {"+", "-"} and candidate_strand != strand:
                return False
            intervals = list(aso.get("binding_intervals_bed0_half_open") or [])
            genomic_refs = {_normalize_overlap_chromosome(block[0]) for block in intervals}
            # A transcript-space interval may complement genomic blocks. A
            # same-reference bounding span must never replace those blocks.
            intervals.extend(block for block in aso.get("source_intervals_bed0_half_open") or []
                             if _normalize_overlap_chromosome(block[0]) not in genomic_refs)
            if not intervals:
                intervals = _reported_candidate_intervals(aso, output_space="genomic")
            return candidate_matches_regions(intervals, [[chrom, start, end]], "any_overlap")

        hit_asos = [
            aso
            for aso in ranked_asos
            if belongs_to_region(aso)
        ]

        hit_asos.sort(key=lambda item: recommendation_sort_key(item, default_direction), reverse=True)
        hit_asos = hit_asos[:12]

        targets.append(
            {
                "label": label,
                "site_kind": "region",
                "direction": default_direction,
                "position": position,
                "region_start": start,
                "region_end": end,
                "chrom": chrom,
                "strand": strand,
                "coordinate_system": "bed0_half_open",
                "recommended_asos": hit_asos,
                "safeguards": [],
                "output_types": [output_type],
                "recommended_asos_by_type": {output_type: hit_asos},
                "safeguards_by_type": {output_type: []},
            }
        )
    return targets


def _build_bed_targets(
    structured_goal: Dict[str, Any],
    ranked_asos: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    steric_bed = structured_goal.get("steric_bed") if isinstance(structured_goal, dict) else None
    rows = steric_bed.get("rows") if isinstance(steric_bed, dict) else None
    if not rows:
        return []

    intent = structured_goal.get("intent") if isinstance(structured_goal, dict) else None
    default_direction = intent or "binding"
    return _build_bed_targets_from_rows(rows, ranked_asos, default_direction, "steric_tiling")


def _build_gene_structure(structured_goal: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(structured_goal, dict):
        return {}
    scope = structured_goal.get("target_scope") or structured_goal.get("isoform_scope")
    scope_norm = scope.strip().lower() if isinstance(scope, str) else ""
    gene_wide = scope_norm in {"gene_wide", "all_isoforms", "all"}
    focused_isoforms = structured_goal.get("isoform_transcripts")
    all_isoforms = structured_goal.get("all_transcripts_full")
    isoform_objectives = structured_goal.get("splice_isoform_objectives")
    scope_source = str(structured_goal.get("isoform_scope_source") or "").strip().lower()
    prefers_focused_isoforms = (
        isinstance(focused_isoforms, dict)
        and bool(focused_isoforms)
        and (
            isinstance(isoform_objectives, list)
            and bool(isoform_objectives)
            or scope_source in {"user_specified", "explicit_splice_target_multi_objective"}
        )
    )
    if prefers_focused_isoforms:
        isoforms = focused_isoforms
    elif gene_wide:
        isoforms = all_isoforms
        if not isinstance(isoforms, dict) or not isoforms:
            isoforms = focused_isoforms
    else:
        isoforms = focused_isoforms
        if not isinstance(isoforms, dict) or not isoforms:
            isoforms = all_isoforms
    if not isinstance(isoforms, dict) or not isoforms:
        return {}

    transcripts: List[Dict[str, Any]] = []
    gene_start: Optional[int] = None
    gene_end: Optional[int] = None
    chrom: Optional[str] = None
    strand: Optional[str] = None

    for transcript_id, info in isoforms.items():
        if not isinstance(info, dict):
            continue
        meta = info.get("metadata") or {}
        display = meta.get("display_name") or transcript_id
        exons: List[Dict[str, Any]] = []
        for exon in info.get("exons_tx") or []:
            if not isinstance(exon, dict):
                continue
            start = _safe_int(exon.get("start"))
            end = _safe_int(exon.get("end"))
            if start is None or end is None:
                continue
            if start > end:
                start, end = end, start
            exons.append(
                {
                    "start": start,
                    "end": end,
                    "index": exon.get("index"),
                    "contains_coding": bool(exon.get("contains_coding")),
                }
            )
            gene_start = start if gene_start is None else min(gene_start, start)
            gene_end = end if gene_end is None else max(gene_end, end)
        if exons:
            transcripts.append(
                {
                    "id": transcript_id,
                    "display_name": display,
                    "exons": exons,
                }
            )
        if chrom is None:
            chrom = info.get("chrom") or meta.get("seq_region_name")
        if strand is None:
            strand = _normalize_strand(info.get("strand") or meta.get("strand"))

    if gene_start is None or gene_end is None:
        return {}
    return {
        "chrom": chrom,
        "strand": strand,
        "start": gene_start,
        "end": gene_end,
        "transcripts": transcripts,
    }


def _format_exon_suffix(exon_indices: Dict[str, Any]) -> str:
    """Format exon indices into a display suffix like '(Exon 7)' or '(Exons 5-8)'.

    Args:
        exon_indices: Dict mapping isoform labels to exon indices, e.g. {"ENST00001": 7, "ENST00002": 7}

    Returns:
        Formatted string like '(Exon 7)', '(Exons 5, 7)', '(Exons 5-8)', or '' if no valid indices
    """
    if not exon_indices or not isinstance(exon_indices, dict):
        return ""

    indices: List[int] = []
    for val in exon_indices.values():
        try:
            idx = int(val)
            if idx not in indices:
                indices.append(idx)
        except (TypeError, ValueError):
            continue

    if not indices:
        return ""

    indices.sort()

    if len(indices) == 1:
        return f" (Exon {indices[0]})"

    # Check if indices are consecutive
    if indices == list(range(indices[0], indices[-1] + 1)):
        return f" (Exons {indices[0]}-{indices[-1]})"

    # Non-consecutive: list them
    if len(indices) <= 3:
        return f" (Exons {', '.join(str(i) for i in indices)})"

    # Many non-consecutive: show range with note
    return f" (Exons {indices[0]}-{indices[-1]})"


def _target_rank_value(target: Dict[str, Any]) -> Optional[int]:
    if not isinstance(target, dict):
        return None
    for key in ("route_rank", "synthetic_target_rank", "target_rank", "rank"):
        value = _safe_int(target.get(key))
        if value is not None:
            return value
    return None


def _target_sort_key(target: Dict[str, Any]) -> Tuple[int, int, int, str]:
    rank = _target_rank_value(target)
    position = _safe_int(target.get("position"))
    label = str(target.get("label") or "")
    return (
        0 if rank is not None else 1,
        rank if rank is not None else 0,
        position if position is not None else 0,
        label,
    )


def _build_targets(
    structured_goal: Dict[str, Any],
    route_data: Dict[str, Dict[str, Any]],
    ranked_asos: List[Dict[str, Any]],
    gapmer_ranked_asos: Optional[List[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    targets: Dict[str, Dict[str, Any]] = {}
    site_plan = structured_goal.get("splice_site_plan") if isinstance(structured_goal, dict) else None
    gapmer_ranked_asos = gapmer_ranked_asos or []
    intent = (structured_goal.get("intent") or "").strip().lower() if isinstance(structured_goal, dict) else ""
    include_steric_targets = intent == "binding"
    route_labels = set(route_data.keys()) if route_data else set()

    def _add_output_type(target: Dict[str, Any], output_type: Optional[str]) -> None:
        if not output_type:
            return
        output_types = target.setdefault("output_types", [])
        if output_type not in output_types:
            output_types.append(output_type)

    def _merge_asos_by_type(
        target: Dict[str, Any],
        output_type: Optional[str],
        asos: Optional[List[Dict[str, Any]]],
    ) -> None:
        key = output_type or "other"
        asos_by_type = target.setdefault("recommended_asos_by_type", {})
        asos_by_type.setdefault(key, [])
        if asos:
            asos_by_type[key].extend(asos)

    def _merge_safeguards_by_type(
        target: Dict[str, Any],
        output_type: Optional[str],
        safeguards: Optional[List[Dict[str, Any]]],
    ) -> None:
        key = output_type or "other"
        safeguards_by_type = target.setdefault("safeguards_by_type", {})
        safeguards_by_type.setdefault(key, [])
        if not safeguards:
            return
        existing = {
            guard.get("label")
            for guard in safeguards_by_type[key]
            if isinstance(guard, dict) and guard.get("label")
        }
        for guard in safeguards:
            if not isinstance(guard, dict):
                continue
            label = guard.get("label")
            if label in existing:
                continue
            safeguards_by_type[key].append(guard)
            if label:
                existing.add(label)

    def _merge_target_entry(entry: Dict[str, Any]) -> None:
        label = entry.get("label")
        if not label:
            return
        # Display labels are not physical identities. Repeated BED labels at
        # different loci must remain distinct in both data and UI selection.
        def geometry_key(target: Dict[str, Any]) -> Tuple[Any, ...]:
            return tuple(target.get(key) for key in (
                "site_kind", "chrom", "strand", "position", "region_start",
                "region_end", "coordinate_system", "reference_build",
            ))
        original_label = label
        collision = targets.get(label)
        if collision is not None and geometry_key(collision) != geometry_key(entry):
            suffix = f"{entry.get('chrom') or '?'}:{entry.get('region_start')}-{entry.get('region_end')}"
            if entry.get("strand"):
                suffix += " " + str(entry["strand"])
            label = f"{original_label} [{suffix}]"
            number = 2
            while label in targets and geometry_key(targets[label]) != geometry_key(entry):
                label = f"{original_label} [{suffix}; {number}]"
                number += 1
            entry = dict(entry, source_label=original_label, label=label)
        output_types = entry.get("output_types") or []
        if not output_types and entry.get("output_type"):
            output_types = [entry.get("output_type")]
        existing = targets.get(label)
        if existing:
            for output_type in output_types:
                _add_output_type(existing, output_type)
            for output_type, asos in (entry.get("recommended_asos_by_type") or {}).items():
                _merge_asos_by_type(existing, output_type, asos)
            for output_type, safeguards in (entry.get("safeguards_by_type") or {}).items():
                _merge_safeguards_by_type(existing, output_type, safeguards)
            for key, value in entry.items():
                if key in {
                    "recommended_asos",
                    "safeguards",
                    "recommended_asos_by_type",
                    "safeguards_by_type",
                    "output_types",
                    "output_type",
                }:
                    continue
                if existing.get(key) is None:
                    existing[key] = value
        else:
            targets[label] = entry
            for output_type in output_types:
                _add_output_type(targets[label], output_type)
            if "recommended_asos_by_type" not in entry:
                for output_type in output_types:
                    _merge_asos_by_type(targets[label], output_type, entry.get("recommended_asos") or [])
            if "safeguards_by_type" not in entry:
                for output_type in output_types:
                    _merge_safeguards_by_type(targets[label], output_type, entry.get("safeguards") or [])

    from aso_agents.splice_reference_scope import splice_site_reference_scope
    for site in site_plan or []:
        if not isinstance(site, dict):
            continue
        position = _safe_int(site.get("position"))
        site_kind = site.get("site")
        label = site.get("label") or (f"{site_kind}@{position}" if site_kind and position else None)
        if not label:
            continue
        if route_labels and label not in route_labels:
            continue
        target = targets.setdefault(label, {"label": label})
        target.update(
            {
                "position": position,
                "site_kind": site_kind,
                "direction": site.get("delta_direction") or site.get("direction"),
                "present_in": site.get("present_in") or [],
                "absent_in": site.get("absent_in") or [],
                "exon_indices": site.get("exon_indices") or {},
                "selected_design_uniqueness": site.get("uniqueness"),
                "uniqueness": splice_site_reference_scope(site, structured_goal or {}).get("description"),
                "reference_scope": splice_site_reference_scope(site, structured_goal or {}),
                "all_coding": site.get("all_coding"),
                "covers_all_isoforms": site.get("covers_all_isoforms"),
            }
        )
        _add_output_type(target, "splice_mod")

    for label, info in route_data.items():
        target = targets.setdefault(label, {"label": label})
        direction = (target.get("direction") or "").strip().lower()
        if not direction or direction == "context":
            target["direction"] = info.get("direction")
        for key in (
            "route_rank",
            "route_goal_label",
            "route_rationale",
            "route_confidence",
            "route_candidate_count",
            "route_threshold_used",
        ):
            value = info.get(key)
            if value not in (None, "", [], {}):
                target[key] = value
        _add_output_type(target, "splice_mod")
        _merge_asos_by_type(target, "splice_mod", info.get("asos") or [])
        _merge_safeguards_by_type(target, "splice_mod", info.get("safeguards") or [])

    if include_steric_targets:
        for bed_target in _build_bed_targets(structured_goal, ranked_asos):
            _merge_target_entry(bed_target)

    gapmer_bed = structured_goal.get("gapmer_bed") if isinstance(structured_goal, dict) else None
    gapmer_rows = gapmer_bed.get("rows") if isinstance(gapmer_bed, dict) else None
    if gapmer_rows:
        for bed_target in _build_bed_targets_from_rows(
            gapmer_rows,
            gapmer_ranked_asos,
            "knockdown",
            "gapmer_tiling",
        ):
            _merge_target_entry(bed_target)

    from aso_agents.report_coordinates import attach_genomic_marker
    map_chrom = _build_gene_structure(structured_goal).get("chrom")
    for target in targets.values():
        if not target.get("position") or not target.get("site_kind"):
            kind, pos = _parse_site_label(target.get("label"))
            if pos is not None and not target.get("position"):
                target["position"] = pos
            if kind and not target.get("site_kind"):
                target["site_kind"] = kind
        target.setdefault("output_types", [])
        target.setdefault("recommended_asos_by_type", {})
        target.setdefault("safeguards_by_type", {})
        for output_type in target["output_types"]:
            target["recommended_asos_by_type"].setdefault(output_type, [])
            target["safeguards_by_type"].setdefault(output_type, [])
        # Aggregate unique ASOs/safeguards for quick lookup.
        merged_asos: List[Dict[str, Any]] = []
        seen_asos = set()
        for asos in target["recommended_asos_by_type"].values():
            for aso in asos or []:
                key = (aso.get("sequence"), aso.get("start"), aso.get("end"))
                if key in seen_asos:
                    continue
                seen_asos.add(key)
                merged_asos.append(aso)
        target["recommended_asos"] = merged_asos

        merged_safeguards: List[Dict[str, Any]] = []
        seen_guards = set()
        for safeguards in target["safeguards_by_type"].values():
            for guard in safeguards or []:
                if not isinstance(guard, dict):
                    continue
                label = guard.get("label")
                if label in seen_guards:
                    continue
                seen_guards.add(label)
                merged_safeguards.append(guard)
        target["safeguards"] = merged_safeguards
        # Add display_label with exon context
        exon_suffix = _format_exon_suffix(target.get("exon_indices"))
        target["display_label"] = f"{target.get('label', '')}{exon_suffix}"
        attach_genomic_marker(target, structured_goal.get("isoform_transcripts") or {},
                              _map_cdna_range_to_genomic_segments, map_chrom)

    return sorted(targets.values(), key=_target_sort_key)


def _serialize_report_json(payload: Dict[str, Any]) -> str:
    raw = json.dumps(payload, ensure_ascii=True, indent=2)
    return raw.replace("</", "<\\/")


def _strip_request_preface(request_text: str) -> str:
    text = (request_text or "").strip()
    if not text:
        return ""
    if text.startswith(ASO_REQUEST_PREFACE):
        text = text[len(ASO_REQUEST_PREFACE):].strip()
        if text.startswith("."):
            text = text[1:].strip()
    if text and text[0].islower():
        text = text[0].upper() + text[1:]
    return text


def _stringify_pipeline_value(value: Any, max_len: int = 220) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, bool):
        text = "true" if value else "false"
    elif isinstance(value, (int, float)):
        text = str(value)
    elif isinstance(value, list):
        items = [str(v).strip() for v in value if v is not None and str(v).strip()]
        text = ", ".join(items)
    else:
        text = str(value).strip()
    if not text:
        return None
    if len(text) > max_len:
        text = text[: max_len - 3] + "..."
    return text


def _build_pipeline_decisions(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
    qa_history: Optional[List[Dict[str, Any]]],
) -> List[Dict[str, Any]]:
    stages: List[Dict[str, Any]] = []
    goal = structured_goal if isinstance(structured_goal, dict) else {}
    payload = final_payload if isinstance(final_payload, dict) else {}

    def add_stage(
        title: str,
        summary: Optional[str] = None,
        items: Optional[List[Dict[str, str]]] = None,
        bullets: Optional[List[str]] = None,
    ) -> None:
        clean_items = items or []
        clean_bullets = [b for b in (bullets or []) if b]
        if not summary and not clean_items and not clean_bullets:
            return
        stages.append(
            {
                "title": title,
                "summary": summary,
                "items": clean_items,
                "bullets": clean_bullets,
            }
        )

    def add_item(items: List[Dict[str, str]], label: str, value: Any) -> None:
        text = _stringify_pipeline_value(value)
        if text:
            items.append({"label": label, "value": text})

    intake_items: List[Dict[str, str]] = []
    add_item(intake_items, "Gene symbol", goal.get("gene_symbol"))
    add_item(intake_items, "Species", goal.get("species"))
    add_item(intake_items, "Intent", goal.get("intent"))
    add_item(intake_items, "Isoform scope source", goal.get("isoform_scope_source"))
    add_item(intake_items, "Desired effect", goal.get("desired_effect"))
    add_item(intake_items, "Target context", goal.get("target_context"))
    add_item(intake_items, "Target region", goal.get("target_region"))
    add_item(intake_items, "Target scope", goal.get("target_scope"))
    add_item(intake_items, "Transcript policy", goal.get("transcript_policy"))
    add_item(intake_items, "Transcript lock", (goal.get("transcript_lock") or {}).get("value") if isinstance(goal.get("transcript_lock"), dict) else None)
    add_item(intake_items, "Requested exon", goal.get("exon_label"))
    add_item(intake_items, "Requested flanks", goal.get("flanks"))
    add_stage("Goal intake", "Parsed the user request into a structured goal.", intake_items)

    isoform_objectives = goal.get("splice_isoform_objectives") or []
    isoform_lines: List[str] = []
    if isinstance(isoform_objectives, list):
        for obj in isoform_objectives:
            if not isinstance(obj, dict):
                continue
            label = _stringify_pipeline_value(obj.get("isoform_label"))
            desired = _stringify_pipeline_value(obj.get("desired_abundance"))
            role = _stringify_pipeline_value(obj.get("role"))
            rationale = _stringify_pipeline_value(obj.get("rationale"), max_len=260)
            if not label:
                continue
            line = label
            if desired:
                line += f": {desired}"
            if role:
                line += f" ({role})"
            if rationale:
                line += f" - {rationale}"
            isoform_lines.append(line)
    if isoform_lines:
        add_stage("Isoform objectives", "LLM-derived isoform priorities from the request.", bullets=isoform_lines)

    clarifications: List[str] = []
    if isinstance(qa_history, list):
        for idx, pair in enumerate(qa_history, start=1):
            if not isinstance(pair, dict):
                continue
            q = _stringify_pipeline_value(pair.get("question"))
            a = _stringify_pipeline_value(pair.get("answer"))
            if q or a:
                clarifications.append(f"Q{idx}: {q or ''} A: {a or ''}".strip())
    if clarifications:
        add_stage("Clarifications", "Follow-up questions used to complete the structured goal.", bullets=clarifications)

    gene_resolution = goal.get("gene_id_resolution") if isinstance(goal, dict) else None
    if not isinstance(gene_resolution, dict):
        gene_resolution = payload.get("gene_id_resolution") if isinstance(payload, dict) else None
    gene_items: List[Dict[str, str]] = []
    if isinstance(gene_resolution, dict):
        add_item(gene_items, "Gene ID", gene_resolution.get("gene_id") or goal.get("gene_id"))
        add_item(gene_items, "Method", gene_resolution.get("method"))
        add_item(gene_items, "Display name", gene_resolution.get("display_name"))
        add_item(gene_items, "Description", gene_resolution.get("description"))
        add_item(gene_items, "Symbol override", gene_resolution.get("symbol_override"))
        add_item(gene_items, "Candidate gene ID", gene_resolution.get("candidate_gene_id"))
        add_stage("Ensembl gene resolution", "Resolved the Ensembl gene ID.", gene_items)
    else:
        add_item(gene_items, "Gene ID", goal.get("gene_id") or payload.get("gene_id"))
        if gene_items:
            add_stage("Ensembl gene resolution", "Resolved the Ensembl gene ID.", gene_items)

    isoform_transcripts = goal.get("isoform_transcripts") if isinstance(goal.get("isoform_transcripts"), dict) else {}
    transcript_lines: List[str] = []
    if isinstance(isoform_transcripts, dict):
        for label in sorted(isoform_transcripts.keys()):
            entry = isoform_transcripts.get(label) or {}
            if not isinstance(entry, dict):
                continue
            tid = _stringify_pipeline_value(entry.get("transcript_id"))
            match_info = entry.get("match_info") if isinstance(entry.get("match_info"), dict) else {}
            method = _stringify_pipeline_value(match_info.get("method"))
            confidence = _stringify_pipeline_value(match_info.get("confidence"))
            rationale = _stringify_pipeline_value(match_info.get("rationale"), max_len=260)
            note = _stringify_pipeline_value(match_info.get("note"), max_len=200)
            if not tid:
                continue
            info_bits: List[str] = []
            if method:
                info_bits.append(f"method={method}")
            if confidence:
                info_bits.append(f"confidence={confidence}")
            if note:
                info_bits.append(note)
            info = f" ({', '.join(info_bits)})" if info_bits else ""
            line = f"{label}: {tid}{info}"
            if rationale:
                line += f" - {rationale}"
            transcript_lines.append(line)
    if transcript_lines:
        add_stage("Transcript resolution", "Matched isoform labels to transcripts.", bullets=transcript_lines)

    splice_analysis = goal.get("splice_strategy_analysis") if isinstance(goal, dict) else None
    if isinstance(splice_analysis, dict):
        splice_items: List[Dict[str, str]] = []
        add_item(splice_items, "Unique splice sites", splice_analysis.get("unique_splice_site_count"))
        add_item(splice_items, "Fallback sites", splice_analysis.get("additional_site_count"))
        add_item(splice_items, "Model", splice_analysis.get("model"))
        add_item(splice_items, "Analysis path", splice_analysis.get("analysis_path"))
        if splice_items:
            add_stage("Splice strategy", "Selected junctions and fallback targets.", splice_items)

    chemistry = goal.get("chemistry") or payload.get("chemistry")
    if isinstance(chemistry, dict):
        chem_items: List[Dict[str, str]] = []
        recommendation = chemistry.get("recommendation") if isinstance(chemistry.get("recommendation"), dict) else chemistry.get("recommendation")
        if isinstance(recommendation, dict):
            add_item(chem_items, "Chemistry", recommendation.get("CHEMISTRY") or recommendation.get("chemistry"))
            add_item(chem_items, "Platform", recommendation.get("platform"))
            add_item(chem_items, "Length", recommendation.get("length"))
            add_item(chem_items, "Rationale", recommendation.get("rationale"))
        else:
            add_item(chem_items, "Chemistry", chemistry.get("CHEMISTRY") or chemistry.get("chemistry"))
            add_item(chem_items, "Platform", chemistry.get("platform"))
            add_item(chem_items, "Length", chemistry.get("length"))
            add_item(chem_items, "Rationale", chemistry.get("rationale"))
        if chem_items:
            add_stage("Chemistry selection", "LLM-selected chemistry profile.", chem_items)

    rbp_result = goal.get("rbp_binding_result") if isinstance(goal, dict) else None
    if isinstance(rbp_result, dict):
        rbp_items: List[Dict[str, str]] = []
        add_item(rbp_items, "RBP", rbp_result.get("rbp"))
        add_item(rbp_items, "Assay", rbp_result.get("assay"))
        add_item(rbp_items, "Assembly", rbp_result.get("assembly"))
        add_item(rbp_items, "Biosample hint", rbp_result.get("biosample_hint"))
        add_item(rbp_items, "Peak count", rbp_result.get("peak_count"))
        selected_dataset = rbp_result.get("selected_dataset") if isinstance(rbp_result.get("selected_dataset"), dict) else None
        if isinstance(selected_dataset, dict):
            add_item(rbp_items, "Dataset", selected_dataset.get("file_accession") or selected_dataset.get("dataset_id"))
            add_item(rbp_items, "Dataset title", selected_dataset.get("dataset_title") or selected_dataset.get("assay_title"))
            add_item(rbp_items, "Biosample", selected_dataset.get("biosample") or selected_dataset.get("biosample_name"))
        add_item(rbp_items, "ENCODE notes", rbp_result.get("encode_notes"))
        add_item(rbp_items, "Error", rbp_result.get("error"))
        if rbp_items:
            add_stage("RBP dataset selection", "ENCODE peak dataset used for RBP tiling.", rbp_items)

    def _find_off_target_summary(container: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        for key in ("tiling_results", "gapmer_tiling_results"):
            results = container.get(key)
            if not isinstance(results, dict):
                continue
            initial = results.get("initial_filtering")
            if isinstance(initial, dict) and isinstance(initial.get("off_target_expression"), dict):
                return initial.get("off_target_expression")
        return None

    off_target_summary = None
    if isinstance(payload, dict):
        off_target_summary = _find_off_target_summary(payload)
    if off_target_summary is None and isinstance(goal, dict):
        off_target_summary = _find_off_target_summary(goal)
    if isinstance(off_target_summary, dict):
        off_items: List[Dict[str, str]] = []
        add_item(off_items, "Rows processed", off_target_summary.get("rows_processed"))
        add_item(off_items, "Rows with expression", off_target_summary.get("rows_with_expression"))
        add_item(off_items, "Cells total", off_target_summary.get("cells_total"))
        add_item(off_items, "Cells sampled", off_target_summary.get("cells_sampled"))
        add_item(off_items, "Expression source", off_target_summary.get("expression_source"))
        selected_dataset = off_target_summary.get("selected_dataset") if isinstance(off_target_summary.get("selected_dataset"), dict) else None
        if isinstance(selected_dataset, dict):
            add_item(off_items, "Dataset", selected_dataset.get("dataset_title") or selected_dataset.get("dataset_id"))
            add_item(off_items, "Tissue", selected_dataset.get("tissue"))
            add_item(off_items, "Cell types", selected_dataset.get("cell_types"))
        add_item(off_items, "Error", off_target_summary.get("error"))
        if off_items:
            add_stage("Cellxgene dataset selection", "Off-target expression dataset used for filtering.", off_items)

    routing = goal.get("strategy_routing") if isinstance(goal, dict) else None
    if isinstance(routing, dict):
        routing_items: List[Dict[str, str]] = []
        add_item(routing_items, "Output dir", routing.get("output_dir"))
        add_item(routing_items, "Goal count", len(routing.get("goals") or []))
        add_item(routing_items, "Error", routing.get("error"))
        add_stage("Strategy routing", "Tile routing summary for splice goals.", routing_items)

    alerts = goal.get("pipeline_alerts") if isinstance(goal, dict) else None
    if isinstance(alerts, list) and alerts:
        alert_lines = [str(item) for item in alerts if item]
        if alert_lines:
            add_stage("Pipeline alerts", "Warnings emitted during the run.", bullets=alert_lines)

    return stages


def _generate_goal_intake_html_report(run_dir: str, structured_goal: Optional[Dict[str, Any]]) -> Optional[str]:
    if not structured_goal:
        structured_path = resolve_run_path(run_dir, "structured_goal.json")
        if structured_path.exists():
            structured_goal = _load_json_path(structured_path)
    if not isinstance(structured_goal, dict):
        print("[warn] HTML report skipped: structured_goal unavailable.")
        return None

    final_payload: Dict[str, Any] = {}
    qa_history: List[Dict[str, Any]] = []
    artifact: Dict[str, Any] = {}
    artifact_path = resolve_run_path(run_dir, "goal_intake.json")
    if artifact_path.exists():
        artifact = _load_json_path(artifact_path) or {}
        if isinstance(artifact.get("final_payload"), dict):
            final_payload = artifact.get("final_payload") or {}
        if isinstance(artifact.get("qa_history"), list):
            qa_history = artifact.get("qa_history") or []
        if not structured_goal and isinstance(final_payload.get("structured_goal"), dict):
            structured_goal = final_payload.get("structured_goal")

    route_data = _collect_route_data(run_dir)
    ranked_asos = _collect_ranked_asos(structured_goal, run_dir)
    gapmer_ranked_asos = _collect_ranked_asos(
        structured_goal,
        run_dir,
        results_key="gapmer_tiling_results",
        tiling_dir_name="gapmer_tiling",
    )
    total_ranked_asos = len(ranked_asos) + len(gapmer_ranked_asos)
    request_text = ""
    request_path = resolve_run_path(run_dir, "request.txt")
    if request_path.exists():
        raw_request = request_path.read_text(encoding="utf-8").strip()
        request_text = _strip_request_preface(raw_request) or raw_request
    splice_strategy = structured_goal.get("splice_strategy_analysis") or {}
    if isinstance(splice_strategy, dict) and not splice_strategy.get("agent_trace"):
        trace_path = splice_strategy.get("agent_trace_path")
        if not trace_path:
            trace_path = str(resolve_run_path(run_dir, "splice_strategy_agent_trace.json"))
        if trace_path and os.path.exists(trace_path):
            try:
                with open(trace_path, "r", encoding="utf-8") as handle:
                    trace_payload = json.load(handle)
                if isinstance(trace_payload, list):
                    splice_strategy["agent_trace"] = trace_payload
            except Exception:
                pass
    pipeline_decisions = _build_pipeline_decisions(structured_goal, final_payload, qa_history)
    report_payload = {
        "meta": {
            "gene_symbol": structured_goal.get("gene_symbol"),
            "gene_id": structured_goal.get("gene_id"),
            "user_request": request_text or None,
            "run_dir": run_dir,
            "generated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "ranked_aso_count": total_ranked_asos,
            "pipeline_alerts": structured_goal.get("pipeline_alerts") or [],
            "steric_merge_summary": structured_goal.get("steric_merge_summary"),
        },
        "gene": _build_gene_structure(structured_goal),
        "targets": _build_targets(structured_goal, route_data, ranked_asos, gapmer_ranked_asos),
        "strategy_routing": _compact_strategy_routing_for_html(
            final_payload.get("strategy_routing") if isinstance(final_payload, dict) else None
        ),
        "llm_rationale": {
            "strategy_analysis": splice_strategy.get("analysis") or "",
            "agent_trace": splice_strategy.get("agent_trace") or [],
        },
        "pipeline_decisions": pipeline_decisions,
    }

    def load_metric_lookup(json_path: Path) -> Dict[Tuple[int, int, str], Dict[str, Any]]:
        if not json_path.exists():
            return {}
        try:
            data = _load_json_path(json_path)
        except Exception:
            return {}
        if not isinstance(data, dict):
            return {}
        rows = data.get("rows") or []
        lookup: Dict[Tuple[int, int, str], Dict[str, Any]] = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            try:
                start = int(row.get("Start"))
                end = int(row.get("End"))
                sequence = row.get("Sequence")
            except (TypeError, ValueError):
                continue
            if not sequence:
                continue
            lookup[(start, end, sequence)] = row
        return lookup

    def coerce_float(value: Any) -> Optional[float]:
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    def coerce_int(value: Any) -> Optional[int]:
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def enrich_asos(asos: Optional[List[Dict[str, Any]]], lookup: Dict[Tuple[int, int, str], Dict[str, Any]]) -> None:
        if not asos or not lookup:
            return
        fields = [
            ("phastcon", "Phastcon", coerce_float),
            ("phylop", "PhyloP", coerce_float),
            ("isoform_uniqueness_score", "isoform_uniqueness_score", coerce_float),
            ("isoform_uniqueness_count", "isoform_uniqueness_count", coerce_int),
        ]
        for aso in asos:
            try:
                key = (int(aso.get("start")), int(aso.get("end")), aso.get("sequence"))
            except (TypeError, ValueError):
                continue
            row = lookup.get(key)
            if not row:
                continue
            for dest, source, coerce in fields:
                if dest in aso or source not in row:
                    continue
                value = coerce(row.get(source))
                if value is None:
                    continue
                aso[dest] = value

    steric_lookup = load_metric_lookup(resolve_run_path(run_dir, "tiling", "scored_tiles.json"))
    gapmer_lookup = load_metric_lookup(resolve_run_path(run_dir, "gapmer_tiling", "gapmer_scored_uniqueness.json"))
    for target in report_payload.get("targets", []):
        if not isinstance(target, dict):
            continue
        output_types = target.get("output_types") or []
        if "steric_tiling" in output_types:
            enrich_asos(target.get("recommended_asos"), steric_lookup)
            by_type = target.get("recommended_asos_by_type") or {}
            enrich_asos(by_type.get("steric_tiling"), steric_lookup)
        if "gapmer_tiling" in output_types:
            enrich_asos(target.get("recommended_asos"), gapmer_lookup)
            by_type = target.get("recommended_asos_by_type") or {}
            enrich_asos(by_type.get("gapmer_tiling"), gapmer_lookup)

    report_manifest = final_payload.get("report_payload") if isinstance(final_payload.get("report_payload"), dict) else {}
    report_md_text = ""
    report_md_path = resolve_run_path(run_dir, "report.md")
    if report_md_path.exists():
        try:
            report_md_text = report_md_path.read_text(encoding="utf-8").strip()
        except OSError:
            report_md_text = ""
    report_explainer_path = resolve_run_path(run_dir, "report_explainer.json")
    explanation_context = build_report_explainer_context(
        run_dir=run_dir,
        payload=artifact,
        structured_goal=structured_goal,
        final_payload=final_payload,
        report_payload=report_manifest,
    )
    if report_manifest.get("payload_kind") == "report_manifest":
        from aso_agents.report_explainer import build_recorded_report_explainer
        # Auxiliary exports now exist. Refresh navigation from their actual
        # inventory instead of carrying pre-export prose into the final HTML.
        report_explainer = build_recorded_report_explainer(explanation_context)
        if report_explainer:
            report_explainer_path.write_text(json.dumps(report_explainer, indent=2), encoding="utf-8")
    else:
        report_explainer_raw = _load_json_path(report_explainer_path) if report_explainer_path.exists() else {}
        report_explainer = normalize_report_explainer(report_explainer_raw, explanation_context)
    if not report_explainer_is_valid(report_explainer):
        print("[warn] HTML report skipped: valid report_explainer.json unavailable.")
        return None

    html_payload = build_goal_intake_html_payload(
        run_dir=run_dir,
        core_payload=report_payload,
        report_manifest=report_manifest,
        structured_goal=structured_goal,
        final_payload=final_payload,
        qa_history=qa_history,
        report_markdown=report_md_text,
        report_explainer=report_explainer,
    )
    html = render_goal_intake_html(html_payload)

    output_path = canonical_run_path(run_dir, "report.html")
    try:
        output_path.write_text(html, encoding="utf-8")
    except Exception as exc:
        print(f"[warn] Failed to write HTML report: {exc}")
        return None
    print(f"[info] HTML report saved to {output_path}")
    return str(output_path)

